insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','2rs',1,1,'E depois da morte de Acabe, Moabe se rebelou contra Israel.'),
('acf','2rs',1,2,'E caiu Acazias pelas grades de um quarto alto, que tinha em Samaria, e adoeceu; e enviou mensageiros, e disse-lhes: Ide, e perguntai a Baal-Zebube, deus de Ecrom, se sararei desta doença.'),
('acf','2rs',1,3,'Mas o anjo do Senhor disse a Elias, o tisbita: Levanta-te, sobe para te encontrares com os mensageiros do rei de Samaria, e dize-lhes: Porventura não há Deus em Israel, para irdes consultar a Baal-Zebube, deus de Ecrom?'),
('acf','2rs',1,4,'E por isso assim diz o Senhor: Da cama, a que subiste, não descerás, mas sem falta morrerás. Então Elias partiu.'),
('acf','2rs',1,5,'E os mensageiros voltaram para ele; e ele lhes disse: Que há, que voltastes?'),
('acf','2rs',1,6,'E eles lhe disseram: Um homem saiu ao nosso encontro, e nos disse: Ide, voltai para o rei que vos mandou, e dizei-lhe: Assim diz o Senhor: Porventura não há Deus em Israel, para que mandes consultar a Baal-Zebube, deus de Ecrom? Portanto da cama, a que subiste, não descerás, mas sem falta morrerás.'),
('acf','2rs',1,7,'E ele lhes disse: Qual era a aparência do homem que veio ao vosso encontro e vos falou estas palavras?'),
('acf','2rs',1,8,'E eles lhe disseram: Era um homem peludo, e com os lombos cingidos de um cinto de couro. Então disse ele: É Elias, o tisbita.'),
('acf','2rs',1,9,'Então o rei lhe enviou um capitão de cinqüenta com seus cinqüenta; e, subindo a ele (porque eis que estava assentado no cume do monte), disse-lhe: Homem de Deus, o rei diz: Desce.'),
('acf','2rs',1,10,'Mas Elias respondeu, e disse ao capitão de cinqüenta: Se eu, pois, sou homem de Deus, desça fogo do céu, e te consuma a ti e aos teus cinqüenta. Então fogo desceu do céu, e consumiu a ele e aos seus cinqüenta.'),
('acf','2rs',1,11,'E tornou o rei a enviar-lhe outro capitão de cinqüenta, com os seus cinqüenta; ele lhe respondeu, dizendo: Homem de Deus, assim diz o rei: Desce depressa.'),
('acf','2rs',1,12,'E respondeu Elias: Se eu sou homem de Deus, desça fogo do céu, e te consuma a ti e aos teus cinqüenta. Então o fogo de Deus desceu do céu, e o consumiu a ele e aos seus cinqüenta.'),
('acf','2rs',1,13,'E tornou a enviar um terceiro capitão de cinqüenta, com os seus cinqüenta; então subiu o capitão de cinqüenta e, chegando, pôs-se de joelhos diante de Elias, e suplicou-lhe, dizendo: Homem de Deus, seja, peço-te, preciosa aos teus olhos a minha vida, e a vida destes cinqüenta teus servos.'),
('acf','2rs',1,14,'Eis que fogo desceu do céu, e consumiu aqueles dois primeiros capitães de cinqüenta, com os seus cinqüenta; porém, agora seja preciosa aos teus olhos a minha vida.'),
('acf','2rs',1,15,'Então o anjo do Senhor disse a Elias: Desce com este, não temas. E levantou-se, e desceu com ele ao rei.'),
('acf','2rs',1,16,'E disse-lhe: Assim diz o Senhor: Por que enviaste mensageiros a consultar a Baal-Zebube, deus de Ecrom? Porventura é porque não há Deus em Israel, para consultar a sua palavra? Portanto desta cama, a que subiste, não descerás, mas certamente morrerás.'),
('acf','2rs',1,17,'Assim, pois, morreu, conforme a palavra do Senhor, que Elias falara; e Jorão começou a reinar no seu lugar no ano segundo de Jeorão, filho de Jeosafá, rei de Judá; porquanto não tinha filho.'),
('acf','2rs',1,18,'O mais dos atos de Acazias, tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','2rs',2,1,'Sucedeu que, quando o SENHOR estava para elevar a Elias num redemoinho ao céu, Elias partiu de Gilgal com Eliseu.'),
('acf','2rs',2,2,'E disse Elias a Eliseu: Fica-te aqui, porque o Senhor me enviou a Betel. Porém Eliseu disse: Vive o Senhor, e vive a tua alma, que não te deixarei. E assim foram a Betel.'),
('acf','2rs',2,3,'Então os filhos dos profetas que estavam em Betel saíram ao encontro de Eliseu, e lhe disseram: Sabes que o SENHOR hoje tomará o teu senhor por sobre a tua cabeça? E ele disse: Também eu bem o sei; calai-vos.'),
('acf','2rs',2,4,'E Elias lhe disse: Eliseu, fica-te aqui, porque o Senhor me enviou a Jericó. Porém ele disse: Vive o Senhor, e vive a tua alma, que não te deixarei. E assim foram a Jericó.'),
('acf','2rs',2,5,'Então os filhos dos profetas que estavam em Jericó se chegaram a Eliseu, e lhe disseram: Sabes que o SENHOR hoje tomará o teu senhor por sobre a tua cabeça? E ele disse: Também eu bem o sei; calai-vos.'),
('acf','2rs',2,6,'E Elias disse: Fica-te aqui, porque o Senhor me enviou ao Jordão. Mas ele disse: Vive o Senhor, e vive a tua alma, que não te deixarei. E assim ambos foram juntos.'),
('acf','2rs',2,7,'E foram cinqüenta homens dos filhos dos profetas, e pararam defronte deles, de longe: e assim ambos pararam junto ao Jordão.'),
('acf','2rs',2,8,'Então Elias tomou a sua capa e a dobrou, e feriu as águas, as quais se dividiram para os dois lados; e passaram ambos em seco.'),
('acf','2rs',2,9,'Sucedeu que, havendo eles passado, Elias disse a Eliseu: Pede-me o que queres que te faça, antes que seja tomado de ti. E disse Eliseu: Peço-te que haja porção dobrada de teu espírito sobre mim.'),
('acf','2rs',2,10,'E disse: Coisa difícil pediste; se me vires quando for tomado de ti, assim se te fará, porém, se não, não se fará.'),
('acf','2rs',2,11,'E sucedeu que, indo eles andando e falando, eis que um carro de fogo, com cavalos de fogo, os separou um do outro; e Elias subiu ao céu num redemoinho.'),
('acf','2rs',2,12,'O que vendo Eliseu, clamou: Meu pai, meu pai, carros de Israel, e seus cavaleiros! E nunca mais o viu; e, pegando as suas vestes, rasgou-as em duas partes.'),
('acf','2rs',2,13,'Também levantou a capa de Elias, que dele caíra; e, voltando-se, parou à margem do Jordão.'),
('acf','2rs',2,14,'E tomou a capa de Elias, que dele caíra, e feriu as águas, e disse: Onde está o Senhor Deus de Elias? Quando feriu as águas elas se dividiram de um ao outro lado; e Eliseu passou.'),
('acf','2rs',2,15,'Vendo-o, pois, os filhos dos profetas que estavam defronte em Jericó, disseram: O espírito de Elias repousa sobre Eliseu. E vieram-lhe ao encontro, e se prostraram diante dele em terra.'),
('acf','2rs',2,16,'E disseram-lhe: Eis que agora entre os teus servos há cinqüenta homens valentes; ora deixa-os ir para buscar a teu senhor; pode ser que o elevasse o Espírito do SENHOR e o lançasse em algum dos montes, ou em algum dos vales. Porém ele disse: Não os envieis.'),
('acf','2rs',2,17,'Mas eles insistiram com ele, até que, constrangido, disse-lhes: Enviai. E enviaram cinqüenta homens, que o buscaram três dias, porém não o acharam.'),
('acf','2rs',2,18,'Então voltaram para ele, pois ficara em Jericó; e disse-lhes: Eu não vos disse que não fôsseis?'),
('acf','2rs',2,19,'E os homens da cidade disseram a Eliseu: Eis que é boa a situação desta cidade, como o meu senhor vê; porém as águas são más, e a terra é estéril.'),
('acf','2rs',2,20,'E ele disse: Trazei-me um prato novo, e ponde nele sal. E lho trouxeram.'),
('acf','2rs',2,21,'Então saiu ele ao manancial das águas, e deitou sal nele; e disse: Assim diz o Senhor: Sararei a estas águas; e não haverá mais nelas morte nem esterilidade.'),
('acf','2rs',2,22,'Ficaram, pois, sãs aquelas águas, até ao dia de hoje, conforme a palavra que Eliseu tinha falado.'),
('acf','2rs',2,23,'Então subiu dali a Betel; e, subindo ele pelo caminho, uns meninos saíram da cidade, e zombavam dele, e diziam-lhe: Sobe, calvo; sobe, calvo!'),
('acf','2rs',2,24,'E, virando-se ele para trás, os viu, e os amaldiçoou no nome do Senhor; então duas ursas saíram do bosque, e despedaçaram quarenta e dois daqueles meninos.'),
('acf','2rs',2,25,'E dali foi para o monte Carmelo de onde voltou para Samaria.'),
('acf','2rs',3,1,'E Jorão, filho de Acabe, começou a reinar sobre Israel, em Samaria, no décimo oitavo ano de Jeosafá, rei de Judá; e reinou doze anos.'),
('acf','2rs',3,2,'E fez o que era mau aos olhos do Senhor; porém não como seu pai, nem como sua mãe; porque tirou a estátua de Baal, que seu pai fizera.'),
('acf','2rs',3,3,'Contudo aderiu aos pecados de Jeroboão, filho de Nebate, com que fizera Israel pecar; não se apartou deles.'),
('acf','2rs',3,4,'Então Mesa, rei dos moabitas, era criador de gado, e pagava de tributo, ao rei de Israel, cem mil cordeiros, e cem mil carneiros com a sua lã.'),
('acf','2rs',3,5,'Sucedeu, porém, que, morrendo Acabe, o rei dos moabitas se rebelou contra o rei de Israel.'),
('acf','2rs',3,6,'Por isso Jorão ao mesmo tempo saiu de Samaria, e fez revista de todo o Israel.'),
('acf','2rs',3,7,'E foi, e mandou dizer a Jeosafá, rei de Judá: O rei dos moabitas se rebelou contra mim; irás tu comigo à guerra contra os moabitas? E disse ele: Subirei; e eu serei como tu, o meu povo como o teu povo, e os meus cavalos como os teus cavalos.'),
('acf','2rs',3,8,'E ele disse: Por que caminho subiremos? Então disse ele: Pelo caminho do deserto de Edom.'),
('acf','2rs',3,9,'E partiram o rei de Israel, o rei de Judá e o rei de Edom; e andaram rodeando com uma marcha de sete dias, e não havia água para o exército e nem para o gado que os seguia.'),
('acf','2rs',3,10,'Então disse o rei de Israel: Ah! o Senhor chamou a estes três reis, para entregá-los nas mãos dos moabitas.'),
('acf','2rs',3,11,'E disse Jeosafá: Não há aqui algum profeta do Senhor, para que consultemos ao Senhor por ele? Então respondeu um dos servos do rei de Israel, dizendo: Aqui está Eliseu, filho de Safate, que derramava água sobre as mãos de Elias.'),
('acf','2rs',3,12,'E disse Jeosafá: Está com ele a palavra do Senhor. Então o rei de Israel, Jeosafá, e o rei de Edom desceram a ter com ele.'),
('acf','2rs',3,13,'Mas Eliseu disse ao rei de Israel: Que tenho eu contigo? Vai aos profetas de teu pai e aos profetas de tua mãe. Porém o rei de Israel lhe disse: Não, porque o Senhor chamou a estes três reis para entregá-los nas mãos dos moabitas.'),
('acf','2rs',3,14,'E disse Eliseu: Vive o Senhor dos Exércitos, em cuja presença estou, que se eu não respeitasse a presença de Jeosafá, rei de Judá, não olharia para ti nem te veria.'),
('acf','2rs',3,15,'Ora, pois, trazei-me um músico. E sucedeu que, tocando o músico, veio sobre ele a mão do Senhor.'),
('acf','2rs',3,16,'E disse: Assim diz o Senhor: Fazei neste vale muitas covas.'),
('acf','2rs',3,17,'Porque assim diz o Senhor: Não vereis vento, e não vereis chuva; todavia este vale se encherá de tanta água, que bebereis vós, o vosso gado e os vossos animais.'),
('acf','2rs',3,18,'E ainda isto é pouco aos olhos do Senhor; também entregará ele os moabitas nas vossas mãos.'),
('acf','2rs',3,19,'E ferireis a todas as cidades fortes, e a todas as cidades escolhidas, e todas as boas árvores cortareis, e entupireis todas as fontes de água, e danificareis com pedras todos os bons campos.'),
('acf','2rs',3,20,'E sucedeu que, pela manhã, oferecendo-se a oferta de alimentos, eis que vinham as águas pelo caminho de Edom; e a terra se encheu de água.'),
('acf','2rs',3,21,'Ouvindo, pois, todos os moabitas que os reis tinham subido para pelejarem contra eles, convocaram a todos os que estavam em idade de cingir cinto e daí para cima, e puseram-se às fronteiras.'),
('acf','2rs',3,22,'E, levantando-se de madrugada, e saindo o sol sobre as águas, viram os moabitas, defronte deles, as águas vermelhas como sangue.'),
('acf','2rs',3,23,'E disseram: Isto é sangue; certamente que os reis se destruíram à espada e se mataram um ao outro! Agora, pois, à presa, moabitas!'),
('acf','2rs',3,24,'Porém, chegando eles ao arraial de Israel, os israelitas se levantaram, e feriram os moabitas, os quais fugiram diante deles e ainda entraram nas suas terras, ferindo ali também os moabitas.'),
('acf','2rs',3,25,'E arrasaram as cidades, e cada um lançou a sua pedra em todos os bons campos, e os entulharam, e entupiram todas as fontes de água, e cortaram todas as boas árvores, até que só em Quir-Haresete deixaram ficar as pedras, mas os fundeiros a cercaram e a feriram.'),
('acf','2rs',3,26,'Mas, vendo o rei dos moabitas que a peleja prevalecia contra ele, tomou consigo setecentos homens que sacavam espada, para romperem contra o rei de Edom, porém não puderam.'),
('acf','2rs',3,27,'Então tomou a seu filho primogênito, que havia de reinar em seu lugar, e o ofereceu em holocausto sobre o muro; pelo que houve grande indignação em Israel; por isso retiraram-se dele, e voltaram para a sua terra.'),
('acf','2rs',4,1,'E uma mulher, das mulheres dos filhos dos profetas, clamou a Eliseu, dizendo: Meu marido, teu servo, morreu; e tu sabes que o teu servo temia ao SENHOR; e veio o credor, para levar os meus dois filhos para serem servos.'),
('acf','2rs',4,2,'E Eliseu lhe disse: Que te hei de fazer? Dize-me que é o que tens em casa. E ela disse: Tua serva não tem nada em casa, senão uma botija de azeite.'),
('acf','2rs',4,3,'Então disse ele: Vai, pede emprestadas, de todos os teus vizinhos, vasilhas vazias, não poucas.'),
('acf','2rs',4,4,'Então entra, e fecha a porta sobre ti, e sobre teus filhos, e deita o azeite em todas aquelas vasilhas, e põe à parte a que estiver cheia.'),
('acf','2rs',4,5,'Partiu, pois, dele, e fechou a porta sobre si e sobre seus filhos; e eles lhe traziam as vasilhas, e ela as enchia.'),
('acf','2rs',4,6,'E sucedeu que, cheias que foram as vasilhas, disse a seu filho: Traze-me ainda uma vasilha. Porém ele lhe disse: Não há mais vasilha alguma. Então o azeite parou.'),
('acf','2rs',4,7,'Então veio ela, e o fez saber ao homem de Deus; e disse ele: Vai, vende o azeite, e paga a tua dívida; e tu e teus filhos vivei do resto.'),
('acf','2rs',4,8,'Sucedeu também um dia que, indo Eliseu a Suném, havia ali uma mulher importante, a qual o reteve para comer pão; e sucedeu que todas as vezes que passava por ali entrava para comer pão.'),
('acf','2rs',4,9,'E ela disse a seu marido: Eis que tenho observado que este que sempre passa por nós é um santo homem de Deus.'),
('acf','2rs',4,10,'Façamos-lhe, pois, um pequeno quarto junto ao muro, e ali lhe ponhamos uma cama, uma mesa, uma cadeira e um candeeiro; e há de ser que, vindo ele a nós, para ali se recolherá.'),
('acf','2rs',4,11,'E sucedeu que um dia ele chegou ali, e recolheu-se àquele quarto, e se deitou.'),
('acf','2rs',4,12,'Então disse ao seu servo Geazi: Chama esta sunamita. E chamando-a ele, ela se pôs diante dele.'),
('acf','2rs',4,13,'Porque ele tinha falado a Geazi: Dize-lhe: Eis que tu nos tens tratado com todo o desvelo; que se há de fazer por ti? Haverá alguma coisa de que se fale por ti ao rei, ou ao capitão do exército? E disse ela: Eu habito no meio do meu povo.'),
('acf','2rs',4,14,'Então disse ele: Que se há de fazer por ela? E Geazi disse: Ora ela não tem filho, e seu marido é velho.'),
('acf','2rs',4,15,'Por isso disse ele: Chama-a. E, chamando-a ele, ela se pôs à porta.'),
('acf','2rs',4,16,'E ele disse: A este tempo determinado, segundo o tempo da vida, abraçarás um filho. E disse ela: Não, meu senhor, homem de Deus, não mintas à tua serva.'),
('acf','2rs',4,17,'E concebeu a mulher, e deu à luz um filho, no tempo determinado, no ano seguinte, segundo Eliseu lhe dissera.'),
('acf','2rs',4,18,'E, crescendo o filho, sucedeu que um dia saiu para ter com seu pai, que estava com os segadores,'),
('acf','2rs',4,19,'E disse a seu pai: Ai, a minha cabeça! Ai, a minha cabeça! Então disse a um moço: Leva-o à sua mãe.'),
('acf','2rs',4,20,'E ele o tomou, e o levou à sua mãe; e esteve sobre os seus joelhos até ao meio-dia, e morreu.'),
('acf','2rs',4,21,'E subiu ela, e o deitou sobre a cama do homem de Deus; e fechou a porta, e saiu.'),
('acf','2rs',4,22,'E chamou a seu marido, e disse: Manda-me já um dos moços, e uma das jumentas, para que eu corra ao homem de Deus, e volte.'),
('acf','2rs',4,23,'E disse ele: Por que vais a ele hoje? Não é lua nova nem sábado. E ela disse: Tudo vai bem.'),
('acf','2rs',4,24,'Então albardou a jumenta, e disse ao seu servo: Guia e anda, e não te detenhas no caminhar, senão quando eu to disser.'),
('acf','2rs',4,25,'Partiu ela, pois, e foi ao homem de Deus, ao monte Carmelo; e sucedeu que, vendo-a o homem de Deus de longe, disse a Geazi, seu servo: Eis aí a sunamita.'),
('acf','2rs',4,26,'Agora, pois, corre-lhe ao encontro e dize-lhe: Vai bem contigo? Vai bem com teu marido? Vai bem com teu filho? E ela disse: Vai bem.'),
('acf','2rs',4,27,'Chegando ela, pois, ao homem de Deus, ao monte, pegou nos seus pés; mas chegou Geazi para retirá-la; disse porém o homem de Deus: Deixa-a, porque a sua alma está triste de amargura, e o Senhor me encobriu, e não me manifestou.'),
('acf','2rs',4,28,'E disse ela: Pedi eu a meu senhor algum filho? Não disse eu: Não me enganes?'),
('acf','2rs',4,29,'E ele disse a Geazi: Cinge os teus lombos, toma o meu bordão na tua mão, e vai; se encontrares alguém não o saúdes, e se alguém te saudar, não lhe respondas; e põe o meu bordão sobre o rosto do menino.'),
('acf','2rs',4,30,'Porém disse a mãe do menino: Vive o Senhor, e vive a tua alma, que não te hei de deixar. Então ele se levantou, e a seguiu.'),
('acf','2rs',4,31,'E Geazi passou adiante deles, e pôs o bordão sobre o rosto do menino; porém não havia nele voz nem sentido; e voltou a encontrar-se com ele, e lhe trouxe aviso, dizendo: O menino não despertou.'),
('acf','2rs',4,32,'E, chegando Eliseu àquela casa, eis que o menino jazia morto sobre a sua cama.'),
('acf','2rs',4,33,'Então entrou ele, e fechou a porta sobre eles ambos, e orou ao Senhor.'),
('acf','2rs',4,34,'E subiu à cama e deitou-se sobre o menino, e, pondo a sua boca sobre a boca dele, e os seus olhos sobre os olhos dele, e as suas mãos sobre as mãos dele, se estendeu sobre ele; e a carne do menino aqueceu.'),
('acf','2rs',4,35,'Depois desceu, e andou naquela casa de uma parte para a outra, e tornou a subir, e se estendeu sobre ele, então o menino espirrou sete vezes, e abriu os olhos.'),
('acf','2rs',4,36,'Então chamou a Geazi, e disse: Chama esta sunamita. E chamou-a, e veio a ele. E disse ele: Toma o teu filho.'),
('acf','2rs',4,37,'E entrou ela, e se prostrou a seus pés, e se inclinou à terra; e tomou o seu filho e saiu.'),
('acf','2rs',4,38,'E, voltando Eliseu a Gilgal, havia fome naquela terra, e os filhos dos profetas estavam assentados na sua presença; e disse ao seu servo: Põe a panela grande ao lume, e faze um caldo de ervas para os filhos dos profetas.'),
('acf','2rs',4,39,'Então um deles saiu ao campo a apanhar ervas, e achou uma parra brava, e colheu dela enchendo a sua capa de colocíntidas; e veio, e as cortou na panela do caldo; porque não as conheciam.'),
('acf','2rs',4,40,'Assim deram de comer para os homens. E sucedeu que, comendo eles daquele caldo, clamaram e disseram: Homem de Deus, há morte na panela. Não puderam comer.'),
('acf','2rs',4,41,'Porém ele disse: Trazei farinha. E deitou-a na panela, e disse: Dai de comer ao povo. E já não havia mal nenhum na panela.'),
('acf','2rs',4,42,'E um homem veio de Baal-Salisa, e trouxe ao homem de Deus pães das primícias, vinte pães de cevada, e espigas verdes na sua palha, e disse: Dá ao povo, para que coma.'),
('acf','2rs',4,43,'Porém seu servo disse: Como hei de pôr isto diante de cem homens? E disse ele: Dá ao povo, para que coma; porque assim diz o Senhor: Comerão, e sobejará.'),
('acf','2rs',4,44,'Então lhos pôs diante, e comeram e ainda sobrou, conforme a palavra do Senhor.'),
('acf','2rs',5,1,'E Naamã, capitão do exército do rei da Síria, era um grande homem diante do seu SENHOR, e de muito respeito; porque por ele o SENHOR dera livramento aos sírios; e era este homem herói valoroso, porém leproso.'),
('acf','2rs',5,2,'E saíram tropas da Síria, da terra de Israel, e levaram presa uma menina que ficou ao serviço da mulher de Naamã.'),
('acf','2rs',5,3,'E disse esta à sua senhora: Antes o meu senhor estivesse diante do profeta que está em Samaria; ele o restauraria da sua lepra.'),
('acf','2rs',5,4,'Então foi Naamã e notificou ao seu senhor, dizendo: Assim e assim falou a menina que é da terra de Israel.'),
('acf','2rs',5,5,'Então disse o rei da Síria: Vai, anda, e enviarei uma carta ao rei de Israel. E foi, e tomou na sua mão dez talentos de prata, seis mil siclos de ouro e dez mudas de roupas.'),
('acf','2rs',5,6,'E levou a carta ao rei de Israel, dizendo: Logo, em chegando a ti esta carta, saibas que eu te enviei Naamã, meu servo, para que o cures da sua lepra.'),
('acf','2rs',5,7,'E sucedeu que, lendo o rei de Israel a carta, rasgou as suas vestes, e disse: Sou eu Deus, para matar e para vivificar, para que este envie a mim um homem, para que eu o cure da sua lepra? Pelo que deveras notai, peço-vos, e vede que busca ocasião contra mim.'),
('acf','2rs',5,8,'Sucedeu, porém, que, ouvindo Eliseu, homem de Deus, que o rei de Israel rasgara as suas vestes, mandou dizer ao rei: Por que rasgaste as tuas vestes? Deixa-o vir a mim, e saberá que há profeta em Israel.'),
('acf','2rs',5,9,'Veio, pois, Naamã com os seus cavalos, e com o seu carro, e parou à porta da casa de Eliseu.'),
('acf','2rs',5,10,'Então Eliseu lhe mandou um mensageiro, dizendo: Vai, e lava-te sete vezes no Jordão, e a tua carne será curada e ficarás purificado.'),
('acf','2rs',5,11,'Porém, Naamã muito se indignou, e se foi, dizendo: Eis que eu dizia comigo: Certamente ele sairá, pôr-se-á em pé, invocará o nome do Senhor seu Deus, e passará a sua mão sobre o lugar, e restaurará o leproso.'),
('acf','2rs',5,12,'Não são porventura Abana e Farpar, rios de Damasco, melhores do que todas as águas de Israel? Não me poderia eu lavar neles, e ficar purificado? E voltou-se, e se foi com indignação.'),
('acf','2rs',5,13,'Então chegaram-se a ele os seus servos, e lhe falaram, e disseram: Meu pai, se o profeta te dissesse alguma grande coisa, porventura não a farias? Quanto mais, dizendo-te ele: Lava-te, e ficarás purificado.'),
('acf','2rs',5,14,'Então desceu, e mergulhou no Jordão sete vezes, conforme a palavra do homem de Deus; e a sua carne tornou-se como a carne de um menino, e ficou purificado.'),
('acf','2rs',5,15,'Então voltou ao homem de Deus, ele e toda a sua comitiva, e chegando, pôs-se diante dele, e disse: Eis que agora sei que em toda a terra não há Deus senão em Israel; agora, pois, peço-te que aceites uma bênção do teu servo.'),
('acf','2rs',5,16,'Porém ele disse: Vive o Senhor, em cuja presença estou, que não a aceitarei. E instou com ele para que a aceitasse, mas ele recusou.'),
('acf','2rs',5,17,'E disse Naamã: Se não queres, dê-se a este teu servo uma carga de terra que baste para carregar duas mulas; porque nunca mais oferecerá este teu servo holocausto nem sacrifício a outros deuses, senão ao Senhor.'),
('acf','2rs',5,18,'Nisto perdoe o SENHOR a teu servo; quando meu senhor entrar na casa de Rimom para ali adorar, e ele se encostar na minha mão, e eu também tenha de me encurvar na casa de Rimom; quando assim me encurvar na casa de Rimom, nisto perdoe o SENHOR a teu servo.'),
('acf','2rs',5,19,'E ele lhe disse: Vai em paz. E foi dele a uma pequena distância.'),
('acf','2rs',5,20,'Então Geazi, servo de Eliseu, homem de Deus, disse: Eis que meu senhor poupou a este sírio Naamã, não recebendo da sua mão alguma coisa do que trazia; porém, vive o SENHOR que hei de correr atrás dele, e receber dele alguma coisa.'),
('acf','2rs',5,21,'E foi Geazi a alcançar Naamã; e Naamã, vendo que corria atrás dele, desceu do carro a encontrá-lo, e disse-lhe: Vai tudo bem?'),
('acf','2rs',5,22,'E ele disse: Tudo vai bem; meu senhor me mandou dizer: Eis que agora mesmo vieram a mim dois jovens dos filhos dos profetas da montanha de Efraim; dá-lhes, pois, um talento de prata e duas mudas de roupas.'),
('acf','2rs',5,23,'E disse Naamã: Sê servido tomar dois talentos. E instou com ele, e amarrou dois talentos de prata em dois sacos, com duas mudas de roupas; e pô-los sobre dois dos seus servos, os quais os levaram diante dele.'),
('acf','2rs',5,24,'E, chegando ele a certa altura, tomou-os das suas mãos, e os depositou na casa; e despediu aqueles homens, e foram-se.'),
('acf','2rs',5,25,'Então ele entrou, e pôs-se diante de seu senhor. E disse-lhe Eliseu: Donde vens, Geazi? E disse: Teu servo não foi nem a uma nem a outra parte.'),
('acf','2rs',5,26,'Porém ele lhe disse: Porventura não foi contigo o meu coração, quando aquele homem voltou do seu carro a encontrar-te? Era a ocasião para receberes prata, e para tomares roupas, olivais e vinhas, ovelhas e bois, servos e servas?'),
('acf','2rs',5,27,'Portanto a lepra de Naamã se pegará a ti e à tua descendência para sempre. Então saiu de diante dele leproso, branco como a neve.'),
('acf','2rs',6,1,'E disseram os filhos dos profetas a Eliseu: Eis que o lugar em que habitamos diante da tua face, nos é estreito.'),
('acf','2rs',6,2,'Vamos, pois, até ao Jordão e tomemos de lá, cada um de nós, uma viga, e façamo-nos ali um lugar para habitar. E disse ele: Ide.'),
('acf','2rs',6,3,'E disse um: Serve-te de ires com os teus servos. E disse: Eu irei.'),
('acf','2rs',6,4,'E foi com eles; e, chegando eles ao Jordão, cortaram madeira.'),
('acf','2rs',6,5,'E sucedeu que, derrubando um deles uma viga, o ferro caiu na água; e clamou, e disse: Ai, meu senhor! ele era emprestado.'),
('acf','2rs',6,6,'E disse o homem de Deus: Onde caiu? E mostrando-lhe ele o lugar, cortou um pau, e o lançou ali, e fez flutuar o ferro.'),
('acf','2rs',6,7,'E disse: Levanta-o. Então ele estendeu a sua mão e o tomou.'),
('acf','2rs',6,8,'E o rei da Síria fazia guerra a Israel; e consultou com os seus servos, dizendo: Em tal e tal lugar estará o meu acampamento.'),
('acf','2rs',6,9,'Mas o homem de Deus enviou ao rei de Israel, dizendo: Guarda-te de passares por tal lugar; porque os sírios desceram ali.'),
('acf','2rs',6,10,'Por isso o rei de Israel enviou àquele lugar, de que o homem de Deus lhe dissera, e de que o tinha avisado, e se guardou ali, não uma nem duas vezes.'),
('acf','2rs',6,11,'Então se turbou com este incidente o coração do rei da Síria, chamou os seus servos, e lhes disse: Não me fareis saber quem dos nossos é pelo rei de Israel?'),
('acf','2rs',6,12,'E disse um dos servos: Não, ó rei meu senhor; mas o profeta Eliseu, que está em Israel, faz saber ao rei de Israel as palavras que tu falas no teu quarto de dormir.'),
('acf','2rs',6,13,'E ele disse: Vai, e vê onde ele está, para que envie, e mande trazê-lo. E fizeram-lhe saber, dizendo: Eis que está em Dotã.'),
('acf','2rs',6,14,'Então enviou para lá cavalos, e carros, e um grande exército, os quais chegaram de noite, e cercaram a cidade.'),
('acf','2rs',6,15,'E o servo do homem de Deus se levantou muito cedo e saiu, e eis que um exército tinha cercado a cidade com cavalos e carros; então o seu servo lhe disse: Ai, meu senhor! Que faremos?'),
('acf','2rs',6,16,'E ele disse: Não temas; porque mais são os que estão conosco do que os que estão com eles.'),
('acf','2rs',6,17,'E orou Eliseu, e disse: Senhor, peço-te que lhe abras os olhos, para que veja. E o Senhor abriu os olhos do moço, e viu; e eis que o monte estava cheio de cavalos e carros de fogo, em redor de Eliseu.'),
('acf','2rs',6,18,'E, como desceram a ele, Eliseu orou ao Senhor e disse: Fere, peço-te, esta gente de cegueira. E feriu-a de cegueira, conforme a palavra de Eliseu.'),
('acf','2rs',6,19,'Então Eliseu lhes disse: Não é este o caminho, nem é esta a cidade; segui-me, e guiar-vos-ei ao homem que buscais. E os guiou a Samaria.'),
('acf','2rs',6,20,'E sucedeu que, chegando eles a Samaria, disse Eliseu: Ó Senhor, abre a estes os olhos para que vejam. O Senhor lhes abriu os olhos, para que vissem, e eis que estavam no meio de Samaria.'),
('acf','2rs',6,21,'E, quando o rei de Israel os viu, disse a Eliseu: Feri-los-ei, feri-los-ei, meu pai?'),
('acf','2rs',6,22,'Mas ele disse: Não os ferirás; feririas tu os que tomasses prisioneiros com a tua espada e com o teu arco? Põe-lhes diante pão e água, para que comam e bebam, e se vão para seu senhor.'),
('acf','2rs',6,23,'E apresentou-lhes um grande banquete, e comeram e beberam; e os despediu e foram para seu senhor; e não entraram mais tropas de sírios na terra de Israel.'),
('acf','2rs',6,24,'E sucedeu, depois disto, que Ben-Hadade, rei da Síria, ajuntou todo o seu exército; e subiu e cercou a Samaria.'),
('acf','2rs',6,25,'E houve grande fome em Samaria, porque eis que a cercaram, até que se vendeu uma cabeça de um jumento por oitenta peças de prata, e a quarta parte de um cabo de esterco de pombas por cinco peças de prata.'),
('acf','2rs',6,26,'E sucedeu que, passando o rei pelo muro, uma mulher lhe bradou, dizendo: Acode-me, ó rei meu senhor.'),
('acf','2rs',6,27,'E ele lhe disse: Se o Senhor te não acode, donde te acudirei eu? Da eira ou do lagar?'),
('acf','2rs',6,28,'Disse-lhe mais o rei: Que tens? E disse ela: Esta mulher me disse: Dá cá o teu filho, para que hoje o comamos, e amanhã comeremos o meu filho.'),
('acf','2rs',6,29,'Cozemos, pois, o meu filho, e o comemos; mas dizendo-lhe eu ao outro dia: Dá cá o teu filho, para que o comamos; escondeu o seu filho.'),
('acf','2rs',6,30,'E sucedeu que, ouvindo o rei as palavras desta mulher, rasgou as suas vestes, e ia passando pelo muro; e o povo viu que o rei trazia cilício por dentro, sobre a sua carne,'),
('acf','2rs',6,31,'E disse: Assim me faça Deus, e outro tanto, se a cabeça de Eliseu, filho de Safate, hoje ficar sobre ele.'),
('acf','2rs',6,32,'Estava então Eliseu assentado em sua casa, e também os anciãos estavam assentados com ele. E enviou o rei um homem adiante de si; mas, antes que o mensageiro viesse a ele, disse ele aos anciãos: Vistes como o filho do homicida mandou tirar-me a cabeça? Olhai pois que, quando vier o mensageiro, fechai-lhe a porta, e empurrai-o para fora com a porta; porventura não vem, após ele, o ruído dos pés de seu senhor?'),
('acf','2rs',6,33,'E, estando ele ainda falando com eles, eis que o mensageiro descia a ele; e disse: Eis que este mal vem do Senhor, que mais, pois, esperaria do Senhor?'),
('acf','2rs',7,1,'Então disse Eliseu: Ouvi a palavra do SENHOR; assim diz o SENHOR: Amanhã, quase a este tempo, haverá uma medida de farinha por um siclo, e duas medidas de cevada por um siclo, à porta de Samaria.'),
('acf','2rs',7,2,'Porém um senhor, em cuja mão o rei se encostava, respondeu ao homem de Deus e disse: Eis que ainda que o SENHOR fizesse janelas no céu, poder-se-ia fazer isso? E ele disse: Eis que o verás com os teus olhos, porém disso não comerás.'),
('acf','2rs',7,3,'E quatro homens leprosos estavam à entrada da porta, os quais disseram uns aos outros: Para que estaremos nós aqui até morrermos?'),
('acf','2rs',7,4,'Se dissermos: Entremos na cidade, há fome na cidade, e morreremos aí; e se ficarmos aqui, também morreremos. Vamos nós, pois, agora, e passemos para o arraial dos sírios; se nos deixarem viver, viveremos, e se nos matarem, tão-somente morreremos.'),
('acf','2rs',7,5,'E levantaram-se ao crepúsculo, para irem ao arraial dos sírios; e, chegando à entrada do arraial dos sírios, eis que não havia ali ninguém.'),
('acf','2rs',7,6,'Porque o Senhor fizera ouvir no arraial dos sírios ruído de carros e ruído de cavalos, como o ruído de um grande exército; de maneira que disseram uns aos outros: Eis que o rei de Israel alugou contra nós os reis dos heteus e os reis dos egípcios, para virem contra nós.'),
('acf','2rs',7,7,'Por isso se levantaram, e fugiram no crepúsculo, e deixaram as suas tendas, os seus cavalos, os seus jumentos e o arraial como estava; e fugiram para salvarem a sua vida.'),
('acf','2rs',7,8,'Chegando, pois, estes leprosos à entrada do arraial, entraram numa tenda, e comeram, beberam e tomaram dali prata, ouro e roupas, e foram e os esconderam; então voltaram, e entraram em outra tenda, e dali também tomaram alguma coisa e a esconderam.'),
('acf','2rs',7,9,'Então disseram uns para os outros: Não fazemos bem; este dia é dia de boas novas, e nos calamos; se esperarmos até à luz da manhã, algum mal nos sobrevirá; por isso agora vamos, e o anunciaremos à casa do rei.'),
('acf','2rs',7,10,'Vieram, pois, e bradaram aos porteiros da cidade, e lhes anunciaram, dizendo: Fomos ao arraial dos sírios e eis que lá não havia ninguém, nem voz de homem, porém só cavalos atados, jumentos atados, e as tendas como estavam.'),
('acf','2rs',7,11,'E chamaram os porteiros, e o anunciaram dentro da casa do rei.'),
('acf','2rs',7,12,'E o rei se levantou de noite, e disse a seus servos: Agora vos farei saber o que é que os sírios nos fizeram; bem sabem eles que esfaimados estamos, pelo que saíram do arraial, a esconder-se pelo campo, dizendo: Quando saírem da cidade, então os tomaremos vivos, e entraremos na cidade.'),
('acf','2rs',7,13,'Então um dos seus servos respondeu e disse: Tomem-se, pois, cinco dos cavalos que restam aqui dentro (eis que são como toda a multidão dos israelitas que ficaram aqui; e eis que são como toda a multidão dos israelitas que já pereceram) e enviemo-los, e vejamos.'),
('acf','2rs',7,14,'Tomaram, pois, dois cavalos de carro; e o rei os enviou com mensageiros após o exército dos sírios, dizendo: Ide, e vede.'),
('acf','2rs',7,15,'E foram após eles até ao Jordão, e eis que todo o caminho estava cheio de roupas e de aviamentos que os sírios, apressando-se, lançaram fora; e voltaram os mensageiros e o anunciaram ao rei.'),
('acf','2rs',7,16,'Então saiu o povo, e saqueou o arraial dos sírios; e havia uma medida de farinha por um siclo, e duas medidas de cevada por um siclo, conforme a palavra do Senhor.'),
('acf','2rs',7,17,'E pusera o rei à porta o senhor em cuja mão se encostava; e o povo o atropelou na porta, e morreu, como falara o homem de Deus, o que falou quando o rei descera a ele.'),
('acf','2rs',7,18,'Porque assim sucedeu como o homem de Deus falara ao rei dizendo: Amanhã, quase a este tempo, haverá duas medidas de cevada por um siclo, e uma medida de farinha por um siclo, à porta de Samaria.'),
('acf','2rs',7,19,'E aquele senhor respondeu ao homem de Deus, e disse: Eis que ainda que o SENHOR fizesse janelas no céu poderia isso suceder? E ele disse: Eis que o verás com os teus olhos, porém dali não comerás.'),
('acf','2rs',7,20,'E assim lhe sucedeu, porque o povo o atropelou à porta, e morreu.'),
('acf','2rs',8,1,'E falou Eliseu àquela mulher cujo filho ele ressuscitara, dizendo: Levanta-te e vai, tu e a tua família, e peregrina onde puderes peregrinar; porque o SENHOR chamou a fome, a qual também virá à terra por sete anos.'),
('acf','2rs',8,2,'E levantou-se a mulher, e fez conforme a palavra do homem de Deus; porque foi ela com a sua família, e peregrinou na terra dos filisteus sete anos.'),
('acf','2rs',8,3,'E sucedeu que, ao fim dos sete anos, a mulher voltou da terra dos filisteus, e saiu a clamar ao rei pela sua casa e pelas suas terras.'),
('acf','2rs',8,4,'Ora o rei falava a Geazi, servo do homem de Deus, dizendo: Conta-me, peço-te, todas as grandes obras que Eliseu tem feito.'),
('acf','2rs',8,5,'E sucedeu que, contando ele ao rei como ressuscitara a um morto, eis que a mulher cujo filho ressuscitara clamou ao rei pela sua casa e pelas suas terras. Então disse Geazi: Ó rei meu senhor, esta é a mulher, e este o seu filho a quem Eliseu ressuscitou.'),
('acf','2rs',8,6,'E o rei perguntou à mulher, e ela lho contou. Então o rei lhe deu um oficial, dizendo: Faze-lhe restituir tudo quanto era seu, e todas as rendas das terras desde o dia em que deixou a terra até agora.'),
('acf','2rs',8,7,'Depois veio Eliseu a Damasco, estando Ben-Hadade, rei da Síria, doente; e lho anunciaram, dizendo: O homem de Deus é chegado aqui.'),
('acf','2rs',8,8,'Então o rei disse a Hazael: Toma um presente na tua mão, e vai a encontrar-te com o homem de Deus; e pergunta por ele ao Senhor, dizendo: Hei de sarar desta doença?'),
('acf','2rs',8,9,'Foi, pois, Hazael a encontrar-se com ele, e tomou um presente na sua mão, a saber: de tudo o que de bom havia em Damasco, quarenta camelos carregados; e veio, e se pôs diante dele e disse: Teu filho Ben-Hadade, rei da Síria, me enviou a ti, a dizer: Sararei eu desta doença?'),
('acf','2rs',8,10,'E Eliseu lhe disse: Vai, e dize-lhe: Certamente viverás. Porém, o Senhor me tem mostrado que certamente morrerá.'),
('acf','2rs',8,11,'E afirmou a sua vista, e fitou os olhos nele até se envergonhar; e o homem de Deus chorou.'),
('acf','2rs',8,12,'Então disse Hazael: Por que chora o meu senhor? E ele disse: Porque sei o mal que hás de fazer aos filhos de Israel; porás fogo às suas fortalezas, e os seus jovens matarás à espada, e os seus meninos despedaçarás, e as suas mulheres grávidas fenderás.'),
('acf','2rs',8,13,'E disse Hazael: Pois, que é teu servo, que não é mais do que um cão, para fazer tão grande coisa? E disse Eliseu: O Senhor me tem mostrado que tu hás de ser rei da Síria.'),
('acf','2rs',8,14,'Então partiu de Eliseu, e foi a seu senhor, o qual lhe disse: Que te disse Eliseu? E disse ele: Disse-me que certamente viverás.'),
('acf','2rs',8,15,'E sucedeu que no outro dia tomou um cobertor e o molhou na água, e o estendeu sobre o seu rosto, e morreu; e Hazael reinou em seu lugar.'),
('acf','2rs',8,16,'E no ano quinto de Jorão, filho de Acabe, rei de Israel, reinando ainda Jeosafá em Judá, começou a reinar Jeorão, filho de Jeosafá, rei de Judá.'),
('acf','2rs',8,17,'Era ele da idade de trinta e dois anos quando começou a reinar, e oito anos reinou em Jerusalém.'),
('acf','2rs',8,18,'E andou no caminho dos reis de Israel, como também fizeram os da casa de Acabe, porque tinha por mulher a filha de Acabe, e fez o que era mal aos olhos do Senhor.'),
('acf','2rs',8,19,'Porém o Senhor não quis destruir a Judá por amor de Davi, seu servo, como lhe tinha falado que lhe daria, para sempre, uma lâmpada, a ele e a seus filhos.'),
('acf','2rs',8,20,'Nos seus dias se rebelaram os edomitas, contra o mando de Judá, e puseram sobre si um rei.'),
('acf','2rs',8,21,'Por isso Jeorão passou a Zair, e todos os carros com ele; e ele se levantou de noite, e feriu os edomitas que estavam ao redor dele, e os capitães dos carros; e o povo foi para as suas tendas.'),
('acf','2rs',8,22,'Todavia os edomitas ficaram rebeldes, contra o mando de Judá, até ao dia de hoje; então, no mesmo tempo, Libna também se rebelou.'),
('acf','2rs',8,23,'O mais dos atos de Jeorão, e tudo quanto fez, porventura não está escrito no livro das crônicas de Judá?'),
('acf','2rs',8,24,'E Jeorão dormiu com seus pais, e foi sepultado com seus pais na cidade de Davi; e Acazias, seu filho, reinou em seu lugar.'),
('acf','2rs',8,25,'No ano doze de Jorão, filho de Acabe, rei de Israel, começou a reinar Acazias, filho de Jeorão, rei de Judá.'),
('acf','2rs',8,26,'Era Acazias de vinte e dois anos de idade quando começou a reinar, e reinou um ano em Jerusalém; e era o nome de sua mãe Atalia, filha de Onri, rei de Israel.'),
('acf','2rs',8,27,'E andou no caminho da casa de Acabe, e fez o que era mal aos olhos do Senhor, como a casa de Acabe, porque era genro da casa de Acabe.'),
('acf','2rs',8,28,'E foi com Jorão, filho de Acabe, a Ramote de Gileade, à peleja contra Hazael, rei da Síria; e os sírios feriram a Jorão.'),
('acf','2rs',8,29,'Então voltou o rei Jorão para se curar, em Jizreel, das feridas que os sírios lhe fizeram em Ramá, quando pelejou contra Hazael, rei da Síria; e desceu Acazias, filho de Jeorão, rei de Judá, para ver a Jorão, filho de Acabe, em Jizreel, porquanto estava doente.'),
('acf','2rs',9,1,'Então o profeta Eliseu chamou um dos filhos dos profetas, e lhe disse: Cinge os teus lombos; e toma este vaso de azeite na tua mão, e vai a Ramote de Gileade;'),
('acf','2rs',9,2,'E, chegando lá, vê onde está Jeú, filho de Jeosafá, filho de Ninsi; entra, e faze que ele se levante do meio de seus irmãos, e leva-o à câmara interior.'),
('acf','2rs',9,3,'E toma o vaso de azeite, e derrama-o sobre a sua cabeça, e dize: Assim diz o Senhor: Ungi-te rei sobre Israel. Então abre a porta, foge, e não te detenhas.'),
('acf','2rs',9,4,'Foi, pois, o moço, o jovem profeta, a Ramote de Gileade.'),
('acf','2rs',9,5,'E, entrando ele, eis que os capitães do exército estavam assentados ali; e disse: Capitão, tenho uma palavra que te dizer. E disse Jeú: A qual de todos nós? E disse: A ti, capitão!'),
('acf','2rs',9,6,'Então se levantou, entrou na casa, e derramou o azeite sobre a sua cabeça, e disse: Assim diz o Senhor Deus de Israel: Ungi-te rei sobre o povo do Senhor, sobre Israel.'),
('acf','2rs',9,7,'E ferirás a casa de Acabe, teu senhor, para que eu vingue o sangue de meus servos, os profetas, e o sangue de todos os servos do SENHOR, da mão de Jezabel.'),
('acf','2rs',9,8,'E toda a casa de Acabe perecerá; destruirei de Acabe todo o homem, tanto o encerrado como o absolvido em Israel.'),
('acf','2rs',9,9,'Porque à casa de Acabe hei de fazer como à casa de Jeroboão, filho de Nebate, e como à casa de Baasa, filho de Aías.'),
('acf','2rs',9,10,'E os cães comerão a Jezabel no pedaço de campo de Jizreel; não haverá quem a enterre. Então abriu a porta e fugiu.'),
('acf','2rs',9,11,'E, saindo Jeú aos servos de seu senhor, disseram-lhe: Vai tudo bem? Por que veio a ti este louco? E ele lhes disse: Bem conheceis o homem e o seu falar.'),
('acf','2rs',9,12,'Mas eles disseram: É mentira; agora faze-nos saber. E disse: Assim e assim me falou, a saber: Assim diz o Senhor: Ungi-te rei sobre Israel.'),
('acf','2rs',9,13,'Então se apressaram, tomando cada um a sua roupa puseram debaixo dele, no mais alto degrau; e tocaram a buzina e disseram: Jeú reina!'),
('acf','2rs',9,14,'Assim Jeú, filho de Jeosafá, filho de Ninsi, conspirou contra Jorão. Tinha, porém, Jorão cercado a Ramote de Gileade, ele e todo o Israel, por causa de Hazael, rei da Síria.'),
('acf','2rs',9,15,'Porém o rei Jorão voltou para se curar em Jizreel das feridas que os sírios lhe fizeram, quando pelejou contra Hazael, rei da Síria. E disse Jeú: Se é da vossa vontade, ninguém saia da cidade, nem escape, para ir denunciar isto em Jizreel.'),
('acf','2rs',9,16,'Então Jeú subiu a um carro, e foi a Jizreel, porque Jorão estava deitado ali; e também Acazias, rei de Judá, descera para ver a Jorão.'),
('acf','2rs',9,17,'E o atalaia estava na torre de Jizreel, e viu a tropa de Jeú, que vinha, e disse: Vejo uma tropa. Então disse Jorão: Toma um cavaleiro, e envia-lho ao encontro; e diga: Há paz?'),
('acf','2rs',9,18,'E o cavaleiro lhe foi ao encontro, e disse: Assim diz o rei: Há paz? E disse Jeú: Que tens tu que fazer com a paz? Passa-te para trás de mim. E o atalaia o fez saber, dizendo: Chegou a eles o mensageiro, porém não volta.'),
('acf','2rs',9,19,'Então enviou outro cavaleiro; e, chegando este a eles, disse: Assim diz o rei: Há paz? E disse Jeú: Que tens tu que fazer com a paz? Passa-te para trás de mim.'),
('acf','2rs',9,20,'E o atalaia o fez saber, dizendo: Também este chegou a eles, porém não volta; e o andar parece como o andar de Jeú, filho de Ninsi, porque anda furiosamente.'),
('acf','2rs',9,21,'Então disse Jorão: Aparelha o carro. E aparelharam o seu carro. E saiu Jorão, rei de Israel, e Acazias, rei de Judá, cada um em seu carro, e saíram ao encontro de Jeú, e o acharam no pedaço de campo de Nabote, o jizreelita.'),
('acf','2rs',9,22,'E sucedeu que, vendo Jorão a Jeú, disse: Há paz, Jeú? E disse ele: Que paz, enquanto as prostituições da tua mãe Jezabel e as suas feitiçarias são tantas?'),
('acf','2rs',9,23,'Então Jorão voltou as mãos e fugiu; e disse a Acazias: Traição há, Acazias.'),
('acf','2rs',9,24,'Mas Jeú entesou o seu arco com toda a força, e feriu a Jorão entre os braços, e a flecha lhe saiu pelo coração; e ele caiu no seu carro.'),
('acf','2rs',9,25,'Então Jeú disse a Bidcar, seu capitão: Toma-o, lança-o no pedaço do campo de Nabote, o jizreelita; porque, lembra-te de que, indo eu e tu juntos a cavalo após seu pai, Acabe, o Senhor pôs sobre ele esta sentença, dizendo:'),
('acf','2rs',9,26,'Por certo vi ontem, à tarde, o sangue de Nabote e o sangue de seus filhos, diz o Senhor; e neste mesmo campo te retribuirei, diz o Senhor. Agora, pois, toma-o e lança-o neste campo, conforme a palavra do Senhor.'),
('acf','2rs',9,27,'O que vendo Acazias, rei de Judá, fugiu pelo caminho da casa do jardim; porém Jeú o perseguiu dizendo: Feri também a este; e o feriram no carro à subida de Gur, que está junto a Ibleão. E fugiu a Megido, e morreu ali.'),
('acf','2rs',9,28,'E seus servos o levaram num carro a Jerusalém, e o sepultaram na sua sepultura junto a seus pais, na cidade de Davi'),
('acf','2rs',9,29,'(E no ano undécimo de Jorão, filho de Acabe, começou Acazias a reinar sobre Judá).'),
('acf','2rs',9,30,'Depois Jeú veio a Jizreel, o que ouvindo Jezabel, pintou-se em volta dos olhos, enfeitou a sua cabeça, e olhou pela janela.'),
('acf','2rs',9,31,'E, entrando Jeú pelas portas, disse ela: Teve paz Zinri, que matou a seu senhor?'),
('acf','2rs',9,32,'E levantou ele o rosto para a janela e disse: Quem é comigo? quem? E dois ou três eunucos olharam para ele.'),
('acf','2rs',9,33,'Então disse ele: Lançai-a daí abaixo. E lançaram-na abaixo; e foram salpicados com o seu sangue a parede e os cavalos, e Jeú a atropelou.'),
('acf','2rs',9,34,'Entrando ele e havendo comido e bebido, disse: Olhai por aquela maldita, e sepultai-a, porque é filha de rei.'),
('acf','2rs',9,35,'E foram para a sepultar; porém não acharam dela senão somente a caveira, os pés e as palmas das mãos.'),
('acf','2rs',9,36,'Então voltaram, e lho fizeram saber; e ele disse: Esta é a palavra do Senhor, a qual falou pelo ministério de Elias, o tisbita, seu servo, dizendo: No pedaço do campo de Jizreel os cães comerão a carne de Jezabel.'),
('acf','2rs',9,37,'E o cadáver de Jezabel será como esterco sobre o campo, na herdade de Jizreel; de modo que não se possa dizer: Esta é Jezabel.'),
('acf','2rs',10,1,'E Acabe tinha setenta filhos em Samaria. Jeú escreveu cartas, e as enviou a Samaria, aos chefes de Jizreel, aos anciãos e aos aios dos filhos de Acabe, dizendo:'),
('acf','2rs',10,2,'Logo, em chegando a vós esta carta, pois estão convosco os filhos de vosso senhor, como também os carros, os cavalos, a cidade fortalecida e as armas,'),
('acf','2rs',10,3,'Olhai pelo melhor e mais reto dos filhos de vosso senhor, o qual ponde sobre o trono de seu pai, e pelejai pela casa de vosso senhor.'),
('acf','2rs',10,4,'Porém eles temeram muitíssimo, e disseram: Eis que dois reis não puderam resistir a ele; como, pois, poderemos nós resistir-lhe?'),
('acf','2rs',10,5,'Então o que tinha cargo da casa, e o que tinha cargo da cidade, os anciãos e os aios mandaram dizer a Jeú: Teus servos somos, e tudo quanto nos disseres faremos; a ninguém constituiremos rei; faze o que parecer bom aos teus olhos.'),
('acf','2rs',10,6,'Então segunda vez lhes escreveu outra carta, dizendo: Se fordes meus, e ouvirdes a minha voz, tomai as cabeças dos homens, filhos de vosso senhor, e vinde a mim amanhã, a este tempo, a Jizreel (os filhos do rei, setenta homens, estavam com os grandes da cidade, que os mantinham).'),
('acf','2rs',10,7,'Sucedeu que, chegada a eles a carta, tomaram os filhos do rei, e os mataram, setenta homens e puseram as suas cabeças nuns cestos, e lhas mandaram a Jizreel.'),
('acf','2rs',10,8,'E um mensageiro veio, e lhe anunciou dizendo: Trouxeram as cabeças dos filhos do rei. E ele disse: Ponde-as em dois montões à entrada da porta, até amanhã.'),
('acf','2rs',10,9,'E sucedeu que, pela manhã, saindo ele, parou, e disse a todo o povo: Vós sois justos; eis que eu conspirei contra o meu senhor, e o matei; mas quem feriu a todos estes?'),
('acf','2rs',10,10,'Sabei, pois, agora que, da palavra do Senhor que o Senhor falou contra a casa de Acabe, nada cairá em terra, porque o Senhor tem feito o que falou pelo ministério de seu servo Elias.'),
('acf','2rs',10,11,'Também Jeú feriu a todos os restantes da casa de Acabe em Jizreel, como também a todos os seus grandes, os seus conhecidos e seus sacerdotes, até não deixar nenhum restante.'),
('acf','2rs',10,12,'Então se levantou e partiu, e foi a Samaria. E, estando no caminho, em Bete-Equede dos pastores,'),
('acf','2rs',10,13,'Jeú achou os irmãos de Acazias, rei de Judá, e disse: Quem sois vós? E eles disseram: Os irmãos de Acazias somos; e descemos a saudar os filhos do rei e os filhos da rainha.'),
('acf','2rs',10,14,'Então disse ele: Apanhai-os vivos. E eles os apanharam vivos, e os mataram junto ao poço de Bete-Equede, quarenta e dois homens; e a nenhum deles deixou ficar.'),
('acf','2rs',10,15,'E, partindo dali, encontrou a Jonadabe, filho de Recabe, que lhe vinha ao encontro, o qual saudou e lhe disse: Reto é o teu coração para comigo, como o meu o é para contigo? E disse Jonadabe: É. Então, se é, dá-me a mão. E deu-lhe a mão, e Jeú fê-lo subir consigo ao carro.'),
('acf','2rs',10,16,'E disse: Vai comigo, e verás o meu zelo para com o Senhor. E o puseram no seu carro.'),
('acf','2rs',10,17,'E, chegando a Samaria, feriu a todos os que ficaram de Acabe em Samaria, até que os destruiu, conforme a palavra que o Senhor dissera a Elias.'),
('acf','2rs',10,18,'E ajuntou Jeú a todo o povo, e disse-lhe: Pouco serviu Acabe a Baal; Jeú, porém, muito o servirá.'),
('acf','2rs',10,19,'Por isso chamai-me agora todos os profetas de Baal, todos os seus servos e todos os seus sacerdotes; não falte nenhum, porque tenho um grande sacrifício a Baal; todo aquele que faltar não viverá. Porém Jeú fazia isto com astúcia, para destruir os servos de Baal.'),
('acf','2rs',10,20,'Disse mais Jeú: Consagrai a Baal uma assembléia solene. E a apregoaram.'),
('acf','2rs',10,21,'Também Jeú enviou por todo o Israel; e vieram todos os servos de Baal, e nenhum homem deles ficou que não viesse; e entraram na casa de Baal, e encheu-se a casa de Baal, de um lado ao outro.'),
('acf','2rs',10,22,'Então disse ao que tinha cargo das vestimentas: Tira as vestimentas para todos os servos de Baal. E ele lhes tirou para fora as vestimentas.'),
('acf','2rs',10,23,'E entrou Jeú com Jonadabe, filho de Recabe, na casa de Baal, e disse aos servos de Baal: Examinai, e vede bem, que porventura nenhum dos servos do Senhor aqui haja convosco, senão somente os servos de Baal.'),
('acf','2rs',10,24,'E, entrando eles a fazerem sacrifícios e holocaustos, Jeú preparou da parte de fora oitenta homens, e disse-lhes: Se escapar algum dos homens que eu entregar em vossas mãos, a vossa vida será pela vida dele.'),
('acf','2rs',10,25,'E sucedeu que, acabando de fazer o holocausto, disse Jeú aos da sua guarda e aos capitães: Entrai, feri-os, não escape nenhum. E os feriram ao fio da espada; e os da guarda e os capitães os lançaram fora, e entraram no mais interior da casa de Baal.'),
('acf','2rs',10,26,'E tiraram as estátuas da casa de Baal, e as queimaram.'),
('acf','2rs',10,27,'Também quebraram a estátua de Baal; e derrubaram a casa de Baal, e fizeram dela latrinas, até ao dia de hoje.'),
('acf','2rs',10,28,'E assim Jeú destruiu a Baal de Israel.'),
('acf','2rs',10,29,'Porém não se apartou Jeú de seguir os pecados de Jeroboão, filho de Nebate, com que fez pecar a Israel, a saber: dos bezerros de ouro, que estavam em Betel e em Dã.'),
('acf','2rs',10,30,'Por isso disse o Senhor a Jeú: Porquanto bem agiste em fazer o que é reto aos meus olhos e, conforme tudo quanto eu tinha no meu coração, fizeste à casa de Acabe, teus filhos, até à quarta geração, se assentarão no trono de Israel.'),
('acf','2rs',10,31,'Mas Jeú não teve cuidado de andar com todo o seu coração na lei do Senhor Deus de Israel, nem se apartou dos pecados de Jeroboão, com que fez pecar a Israel.'),
('acf','2rs',10,32,'Naqueles dias começou o Senhor a diminuir os termos de Israel; porque Hazael os feriu em todas as fronteiras de Israel.'),
('acf','2rs',10,33,'Desde o Jordão até ao nascente do sol, a toda a terra de Gileade; os gaditas, os rubenitas e os manassitas, desde Aroer, que está junto ao ribeiro de Arnom, a saber, Gileade e Basã.'),
('acf','2rs',10,34,'Ora o mais dos atos de Jeú, tudo quanto fez e todo o seu poder, porventura não está escrito no livro das crônicas de Israel?'),
('acf','2rs',10,35,'E Jeú dormiu com seus pais, e o sepultaram em Samaria; e Jeoacaz, seu filho, reinou em seu lugar.'),
('acf','2rs',10,36,'E os dias que Jeú reinou sobre Israel, em Samaria, foram vinte e oito anos.'),
('acf','2rs',11,1,'Vendo, pois, Atalia, mãe de Acazias, que seu filho era morto, levantou-se, e destruiu toda a descendência real.'),
('acf','2rs',11,2,'Mas Jeoseba, filha do rei Jorão, irmã de Acazias, tomou a Joás, filho de Acazias, furtando-o dentre os filhos do rei, aos quais matavam, e o pôs, a ele e à sua ama na recâmara, e o escondeu de Atalia, e assim não o mataram.'),
('acf','2rs',11,3,'E esteve com ela escondido na casa do Senhor seis anos; e Atalia reinava sobre o país.'),
('acf','2rs',11,4,'E no sétimo ano enviou Joiada, e tomou os centuriões, com os capitães, e com os da guarda, e os colocou consigo na casa do Senhor; e fez com eles uma aliança e ajuramentou-os na casa do Senhor; e mostrou-lhes o filho do rei.'),
('acf','2rs',11,5,'E deu-lhes ordem, dizendo: Isto é o que haveis de fazer: Uma terça parte de vós, que entrais no sábado, fará a guarda da casa do rei.'),
('acf','2rs',11,6,'E outra terça parte estará à porta de Sur; e a outra terça parte à porta detrás dos da guarda; assim fareis a guarda desta casa, afastando a todos.'),
('acf','2rs',11,7,'E as duas partes de vós, a saber, todos os que saem no sábado, farão a guarda da casa do Senhor junto ao rei.'),
('acf','2rs',11,8,'E rodeareis o rei, cada um com as suas armas na mão, e aquele que entrar entre as fileiras o matarão; e vós estareis com o rei quando sair e quando entrar.'),
('acf','2rs',11,9,'Fizeram, pois, os centuriões conforme tudo quanto ordenara o sacerdote Joiada, tomando cada um os seus homens, tanto os que entravam no sábado como os que saíam no sábado; e foram ao sacerdote Joiada.'),
('acf','2rs',11,10,'E o sacerdote deu aos centuriões as lanças e os escudos que haviam sido do rei Davi, que estavam na casa do Senhor.'),
('acf','2rs',11,11,'E os da guarda se puseram, cada um com as armas na mão, desde o lado direito da casa até ao lado esquerdo da casa, do lado do altar, e do lado da casa, em redor do rei.'),
('acf','2rs',11,12,'Então Joiada fez sair o filho do rei, e lhe pôs a coroa, e lhe deu o testemunho; e o fizeram rei, e o ungiram, e bateram as palmas, e disseram: Viva o rei!'),
('acf','2rs',11,13,'E Atalia, ouvindo a voz dos da guarda e do povo, foi ter com o povo, na casa do Senhor.'),
('acf','2rs',11,14,'E olhou, e eis que o rei estava junto à coluna, conforme o costume, e os príncipes e os trombeteiros junto ao rei, e todo o povo da terra estava alegre e tocava as trombetas; então Atalia rasgou as suas vestes, e clamou: Traição! Traição!'),
('acf','2rs',11,15,'Porém o sacerdote Joiada deu ordem aos centuriões que comandavam as tropas, dizendo-lhes: Tirai-a para fora das fileiras, e a quem a seguir matai-o à espada. Porque o sacerdote disse: Não a matem na casa do Senhor.'),
('acf','2rs',11,16,'E lançaram mão dela; e ela foi, pelo caminho da entrada dos cavalos, à casa do rei, e ali a mataram.'),
('acf','2rs',11,17,'E Joiada fez uma aliança entre o Senhor e o rei e o povo, para que fosse o povo do Senhor; como também entre o rei e o povo.'),
('acf','2rs',11,18,'Então todo o povo da terra entrou na casa de Baal, e a derrubaram, como também os seus altares, e as suas imagens, totalmente quebraram, e a Matã, sacerdote de Baal, mataram diante dos altares; então o sacerdote pôs oficiais sobre a casa do Senhor.'),
('acf','2rs',11,19,'E tomou os centuriões, e os capitães, e os da guarda, e todo o povo da terra; e conduziram da casa do Senhor, o rei, e foram, pelo caminho da porta dos da guarda, à casa do rei, e ele se assentou no trono dos reis.'),
('acf','2rs',11,20,'E todo o povo da terra se alegrou, e a cidade repousou, depois que mataram a Atalia, à espada, junto à casa do rei,'),
('acf','2rs',11,21,'Era Joás da idade de sete anos quando o fizeram rei.'),
('acf','2rs',12,1,'No ano sétimo de Jeú começou a reinar Joás, e quarenta anos reinou em Jerusalém; e era o nome de sua mãe Zíbia, de Berseba.'),
('acf','2rs',12,2,'E fez Joás o que era reto aos olhos do Senhor todos os dias em que o sacerdote Joiada o dirigia.'),
('acf','2rs',12,3,'Tão-somente os altos não foram tirados; porque ainda o povo sacrificava e queimava incenso nos altos.'),
('acf','2rs',12,4,'E disse Joás aos sacerdotes: Todo o dinheiro das coisas santas que se trouxer à casa do Senhor, a saber, o dinheiro daquele que passa o arrolamento, o dinheiro de cada uma das pessoas, segundo a sua avaliação, e todo o dinheiro que trouxer cada um voluntariamente para a casa do Senhor,'),
('acf','2rs',12,5,'Os sacerdotes o recebam, cada um dos seus conhecidos; e eles mesmos reparem as fendas da casa, toda a fenda que se achar nela.'),
('acf','2rs',12,6,'Sucedeu, porém, que, no ano vinte e três do rei Joás, os sacerdotes ainda não tinham reparado as fendas da casa.'),
('acf','2rs',12,7,'Então o rei Joás chamou o sacerdote Joiada e os mais sacerdotes, e lhes disse: Por que não reparais as fendas da casa? Agora, pois, não tomeis mais dinheiro de vossos conhecidos, mas entregai-o para o reparo das fendas da casa.'),
('acf','2rs',12,8,'E consentiram os sacerdotes em não tomarem mais dinheiro do povo, e em não repararem as fendas da casa.'),
('acf','2rs',12,9,'Porém o sacerdote Joiada tomou um cofre e fez um buraco na tampa; e a pôs ao pé do altar, à mão direita dos que entravam na casa do Senhor; e os sacerdotes que guardavam a entrada da porta punham ali todo o dinheiro que se trazia à casa do Senhor.'),
('acf','2rs',12,10,'Sucedeu que, vendo eles que já havia muito dinheiro no cofre, o escrivão do rei subia com o sumo sacerdote, e contavam e ensacavam o dinheiro que se achava na casa do Senhor.'),
('acf','2rs',12,11,'E o dinheiro, depois de pesado, davam nas mãos dos que faziam a obra, que tinham a seu cargo a casa do Senhor e eles o distribuíam aos carpinteiros e aos edificadores que reparavam a casa do Senhor.'),
('acf','2rs',12,12,'Como também aos pedreiros e aos cabouqueiros; e para se comprar madeira e pedras de cantaria para repararem as fendas da casa do Senhor, e para tudo quanto era necessário para reparar a casa.'),
('acf','2rs',12,13,'Todavia, do dinheiro que se trazia à casa do Senhor não se faziam nem taças de prata, nem garfos, nem bacias, nem trombetas, nem vaso algum de ouro ou vaso de prata para a casa do Senhor.'),
('acf','2rs',12,14,'Porque o davam aos que faziam a obra, e reparavam com ele a casa do Senhor.'),
('acf','2rs',12,15,'Também não pediam contas aos homens em cujas mãos entregavam aquele dinheiro, para o dar aos que faziam a obra, porque procediam com fidelidade.'),
('acf','2rs',12,16,'Mas o dinheiro do sacrifício por delitos, e o dinheiro por sacrifício de pecados, não se trazia à casa do Senhor; porque era para os sacerdotes.'),
('acf','2rs',12,17,'Então subiu Hazael, rei da Síria, e pelejou contra Gate, e a tomou; depois Hazael resolveu marchar contra Jerusalém.'),
('acf','2rs',12,18,'Porém Joás, rei de Judá, tomou todas as coisas santas que Jeosafá, Jorão e Acazias, seus pais, reis de Judá, consagraram, como também todo o ouro que se achou nos tesouros da casa do Senhor e na casa do rei e o mandou a Hazael, rei da Síria; e então se desviou de Jerusalém.'),
('acf','2rs',12,19,'Ora, o mais dos atos de Joás, e tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',12,20,'E levantaram-se os servos de Joás, e conspiraram contra ele ferindo-o na casa de Milo, no caminho que desce para Sila.'),
('acf','2rs',12,21,'Porque Jozacar, filho de Simeate, e Jozabade, filho de Somer, seus servos, o feriram, e morreu, e o sepultaram com seus pais na cidade de Davi. E Amazias, seu filho, reinou em seu lugar.'),
('acf','2rs',13,1,'No ano vinte e três de Joás, filho de Acazias, rei de Judá, começou a reinar Jeoacaz, filho de Jeú, sobre Israel, em Samaria, e reinou dezessete anos.'),
('acf','2rs',13,2,'E fez o que era mau aos olhos do Senhor; porque seguiu os pecados de Jeroboão, filho de Nebate, que fez pecar a Israel; não se apartou deles.'),
('acf','2rs',13,3,'Por isso a ira do Senhor se acendeu contra Israel; e entregou-os na mão de Hazael, rei da Síria, e na mão de Ben-Hadade, filho de Hazael, todos aqueles dias.'),
('acf','2rs',13,4,'Porém Jeoacaz suplicou diante da face do Senhor; e o Senhor ouviu; porque viu a opressão de Israel, pois o rei da Síria os oprimia.'),
('acf','2rs',13,5,'E o Senhor deu um salvador a Israel, e saíram de sob as mãos dos sírios; e os filhos de Israel habitaram nas suas tendas, como no passado'),
('acf','2rs',13,6,'(Contudo não se apartaram dos pecados da casa de Jeroboão, com que fez Israel pecar; porém ele andou neles e também o bosque ficou em pé em Samaria).'),
('acf','2rs',13,7,'Porque não deixou a Jeoacaz, do povo, senão só cinqüenta cavaleiros, dez carros e dez mil homens de pé, porquanto o rei da Síria os tinha destruído e os tinha feito como o pó, trilhando-os.'),
('acf','2rs',13,8,'Ora, o mais dos atos de Jeoacaz, e tudo quanto fez, e o seu poder, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','2rs',13,9,'E Jeoacaz dormiu com seus pais, e o sepultaram em Samaria; e Jeoás, seu filho, reinou em seu lugar.'),
('acf','2rs',13,10,'No ano trinta e sete de Joás, rei de Judá, começou a reinar Jeoás, filho de Jeoacaz, sobre Israel, em Samaria, e reinou dezesseis anos.'),
('acf','2rs',13,11,'E fez o que era mau aos olhos do Senhor; não se apartou de nenhum dos pecados de Jeroboão, filho de Nebate, com que fez Israel pecar, porém andou neles.'),
('acf','2rs',13,12,'Ora, o mais dos atos de Jeoás, e tudo quanto fez, e o seu poder, com que pelejou contra Amazias, rei de Judá, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','2rs',13,13,'E Jeoás dormiu com seus pais, e Jeroboão se assentou no seu trono; e Jeoás foi sepultado em Samaria, junto aos reis de Israel.'),
('acf','2rs',13,14,'E Eliseu estava doente da enfermidade de que morreu, e Jeoás, rei de Israel, desceu a ele, e chorou sobre o seu rosto, e disse: Meu pai, meu pai, o carro de Israel, e seus cavaleiros!'),
('acf','2rs',13,15,'E Eliseu lhe disse: Toma um arco e flechas. E tomou um arco e flechas.'),
('acf','2rs',13,16,'Então disse ao rei de Israel: Põe a tua mão sobre o arco. E pôs sobre ele a sua mão; e Eliseu pôs as suas mãos sobre as do rei.'),
('acf','2rs',13,17,'E disse: Abre a janela para o oriente. E abriu-a. Então disse Eliseu: Atira. E atirou; e disse: A flecha do livramento do Senhor é a flecha do livramento contra os sírios; porque ferirás os sírios; em Afeque, até os consumir.'),
('acf','2rs',13,18,'Disse mais: Toma as flechas. E tomou-as. Então disse ao rei de Israel: Fere a terra. E feriu-a três vezes, e cessou.'),
('acf','2rs',13,19,'Então o homem de Deus se indignou muito contra ele, e disse: Cinco ou seis vezes a deverias ter ferido; então feririas os sírios até os consumir; porém agora só três vezes ferirás os sírios.'),
('acf','2rs',13,20,'Depois morreu Eliseu, e o sepultaram. Ora, as tropas dos moabitas invadiram a terra à entrada do ano.'),
('acf','2rs',13,21,'E sucedeu que, enterrando eles um homem, eis que viram uma tropa, e lançaram o homem na sepultura de Eliseu; e, caindo nela o homem, e tocando os ossos de Eliseu, reviveu, e se levantou sobre os seus pés.'),
('acf','2rs',13,22,'E Hazael, rei da Síria, oprimiu a Israel todos os dias de Jeoacaz.'),
('acf','2rs',13,23,'Porém o Senhor teve misericórdia deles, e se compadeceu deles, e tornou-se para eles por amor da sua aliança com Abraão, Isaque e Jacó, e não os quis destruir, e não os lançou ainda da sua presença.'),
('acf','2rs',13,24,'E morreu Hazael, rei da Síria e Ben-Hadade, seu filho, reinou em seu lugar.'),
('acf','2rs',13,25,'E Jeoás, filho de Jeoacaz, tornou a tomar as cidades das mãos de Ben-Hadade, que ele tinha tomado das mãos de Jeoacaz, seu pai, na guerra; três vezes Jeoás o feriu, e recuperou as cidades de Israel.'),
('acf','2rs',14,1,'No segundo ano de Jeoás, filho de Jeoacaz, rei de Israel, começou a reinar Amazias, filho de Joás, rei de Judá.'),
('acf','2rs',14,2,'Tinha vinte e cinco anos quando começou a reinar, e vinte e nove anos reinou em Jerusalém. E era o nome de sua mãe Joadã, de Jerusalém.'),
('acf','2rs',14,3,'E fez o que era reto aos olhos do Senhor, ainda que não como seu pai Davi; fez, porém, conforme tudo o que fizera Joás seu pai.'),
('acf','2rs',14,4,'Tão-somente os altos não foram tirados; porque o povo ainda sacrificava e queimava incenso nos altos.'),
('acf','2rs',14,5,'Sucedeu que, sendo já o reino confirmado na sua mão, matou os servos que tinham matado o rei, seu pai.'),
('acf','2rs',14,6,'Porém os filhos dos assassinos não matou, como está escrito no livro da lei de Moisés, no qual o Senhor deu ordem, dizendo: Não matarão os pais por causa dos filhos, e os filhos não matarão por causa dos pais; mas cada um será morto pelo seu pecado.'),
('acf','2rs',14,7,'Este feriu a dez mil edomitas no vale do Sal, e tomou a Sela na guerra; e chamou-a Jocteel, até ao dia de hoje.'),
('acf','2rs',14,8,'Então Amazias enviou mensageiros a Jeoás, filho de Jeoacaz, filho de Jeú, rei de Israel, dizendo: Vem, vejamo-nos face a face.'),
('acf','2rs',14,9,'Porém Jeoás, rei de Israel, enviou a Amazias, rei de Judá, dizendo: O cardo que estava no Líbano mandou dizer ao cedro que estava no Líbano: Dá tua filha por mulher a meu filho; mas os animais do campo, que estavam no Líbano, passaram e pisaram o cardo.'),
('acf','2rs',14,10,'Na verdade feriste os moabitas, e o teu coração se ensoberbeceu; gloria-te disso, e fica em tua casa; e por que te entremeterias no mal, para caíres tu, e Judá contigo?'),
('acf','2rs',14,11,'Mas Amazias não o ouviu. E subiu Jeoás, rei de Israel, e Amazias, rei de Judá, e viram-se face a face, em Bete-Semes, que está em Judá.'),
('acf','2rs',14,12,'E Judá foi ferido diante de Israel, e fugiu cada um para a sua tenda.'),
('acf','2rs',14,13,'E Jeoás, rei de Israel, tomou a Amazias, rei de Judá, filho de Joás, filho de Acazias, em Bete-Semes; e veio a Jerusalém, e rompeu o muro de Jerusalém, desde a porta de Efraim até a porta da esquina, quatrocentos côvados.'),
('acf','2rs',14,14,'E tomou todo o ouro e a prata, e todos os vasos que se acharam na casa do Senhor e nos tesouros da casa do rei, como também os reféns e voltou para Samaria.'),
('acf','2rs',14,15,'Ora, o mais dos atos de Jeoás, o que fez e o seu poder, e como pelejou contra Amazias, rei de Judá, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','2rs',14,16,'E dormiu Jeoás com seus pais, e foi sepultado em Samaria, junto aos reis de Israel; e Jeroboão, seu filho, reinou em seu lugar.'),
('acf','2rs',14,17,'E viveu Amazias, filho de Joás, rei de Judá, depois da morte de Jeoás, filho de Jeoacaz, rei de Israel, quinze anos.'),
('acf','2rs',14,18,'Ora, o mais dos atos de Amazias, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',14,19,'E conspiraram contra ele em Jerusalém, e fugiu para Laquis; porém enviaram após ele até Laquis, e o mataram ali.'),
('acf','2rs',14,20,'E o trouxeram em cima de cavalos; e o sepultaram em Jerusalém, junto a seus pais, na cidade de Davi.'),
('acf','2rs',14,21,'E todo o povo de Judá tomou a Azarias, que já era de dezesseis anos, e o fizeram rei em lugar de Amazias, seu pai.'),
('acf','2rs',14,22,'Este edificou a Elate, e a restituiu a Judá, depois que o rei dormiu com seus pais.'),
('acf','2rs',14,23,'No décimo quinto ano de Amazias, filho de Joás, rei de Judá, começou a reinar em Samaria, Jeroboão, filho de Jeoás, rei de Israel, e reinou quarenta e um anos.'),
('acf','2rs',14,24,'E fez o que era mau aos olhos do Senhor; nunca se apartou de nenhum dos pecados de Jeroboão, filho de Nebate, com que fez pecar a Israel.'),
('acf','2rs',14,25,'Também este restituiu os termos de Israel, desde a entrada de Hamate, até ao mar da planície; conforme a palavra do Senhor Deus de Israel, a qual falara pelo ministério de seu servo Jonas, filho do profeta Amitai, o qual era de Gate-Hefer.'),
('acf','2rs',14,26,'Porque viu o Senhor que a miséria de Israel era muito amarga, e que nem havia escravo, nem absolvido, nem quem ajudasse a Israel.'),
('acf','2rs',14,27,'E ainda não falara o Senhor em apagar o nome de Israel de debaixo do céu; porém os livrou por meio de Jeroboão, filho de Jeoás.'),
('acf','2rs',14,28,'Ora, o mais dos atos de Jeroboão, tudo quanto fez, e seu poder, como pelejou, e como restituiu a Damasco e a Hamate, pertencentes a Judá, sendo rei em Israel, porventura não está escrito no livro das crônicas de Israel?'),
('acf','2rs',14,29,'E Jeroboão dormiu com seus pais, com os reis de Israel; e Zacarias, seu filho, reinou em seu lugar.'),
('acf','2rs',15,1,'No ano vinte e sete de Jeroboão, rei de Israel, começou a reinar Azarias, filho de Amazias, rei de Judá.'),
('acf','2rs',15,2,'Tinha dezesseis anos quando começou a reinar, e cinqüenta e dois anos reinou em Jerusalém; e era o nome de sua mãe Jecolias, de Jerusalém.'),
('acf','2rs',15,3,'E fez o que era reto aos olhos do Senhor, conforme tudo o que fizera Amazias, seu pai.'),
('acf','2rs',15,4,'Tão-somente os altos não foram tirados; porque o povo ainda sacrificava e queimava incenso nos altos.'),
('acf','2rs',15,5,'E o Senhor feriu o rei, e ficou leproso até ao dia da sua morte; e habitou numa casa separada; porém Jotão, filho do rei, tinha o cargo da casa, julgando o povo da terra.'),
('acf','2rs',15,6,'Ora, o mais dos atos de Azarias, e tudo o que fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',15,7,'E Azarias dormiu com seus pais e o sepultaram junto a seus pais, na cidade de Davi; e Jotão, seu filho, reinou em seu lugar.'),
('acf','2rs',15,8,'No ano trinta e oito de Azarias, rei de Judá, reinou Zacarias, filho de Jeroboão, sobre Israel, em Samaria, seis meses.'),
('acf','2rs',15,9,'E fez o que era mau aos olhos do Senhor, como tinham feito seus pais; nunca se apartou dos pecados de Jeroboão, filho de Nebate, com que fez pecar a Israel.'),
('acf','2rs',15,10,'E Salum, filho de Jabes, conspirou contra ele e feriu-o diante do povo, e matou-o; e reinou em seu lugar.'),
('acf','2rs',15,11,'Ora, o mais dos atos de Zacarias, eis que está escrito no livro das crônicas dos reis de Israel.'),
('acf','2rs',15,12,'Esta foi a palavra do Senhor, que falou a Jeú: Teus filhos, até à quarta geração, se assentarão sobre o trono de Israel. E assim foi.'),
('acf','2rs',15,13,'Salum, filho de Jabes, começou a reinar no ano trinta e nove de Uzias, rei de Judá, e reinou um mês inteiro em Samaria.'),
('acf','2rs',15,14,'Porque Menaém, filho de Gadi, subiu de Tirza, e veio a Samaria; e feriu a Salum, filho de Jabes, em Samaria, e o matou, e reinou em seu lugar.'),
('acf','2rs',15,15,'Ora, o mais dos atos de Salum, e a conspiração que fez, eis que está escrito no livro das crônicas dos reis de Israel.'),
('acf','2rs',15,16,'Então Menaém feriu a Tifsa, e a todos os que nela havia, como também a seus termos desde Tirza, porque não lha tinham aberto; e os feriu, pois, e a todas as mulheres grávidas fendeu pelo meio.'),
('acf','2rs',15,17,'Desde o ano trinta e nove de Azarias, rei de Judá, Menaém, filho de Gadi, começou a reinar sobre Israel, e reinou dez anos em Samaria.'),
('acf','2rs',15,18,'E fez o que era mau aos olhos do Senhor; todos os seus dias não se apartou dos pecados de Jeroboão, filho de Nebate, com que fez pecar a Israel.'),
('acf','2rs',15,19,'Então veio Pul, rei da Assíria, contra a terra; e Menaém deu a Pul mil talentos de prata, para que este o ajudasse a firmar o reino na sua mão.'),
('acf','2rs',15,20,'E Menaém tirou este dinheiro de Israel, de todos os poderosos e ricos, para dá-lo ao rei da Assíria, de cada homem cinqüenta siclos de prata; assim voltou o rei da Assíria, e não ficou ali na terra.'),
('acf','2rs',15,21,'Ora, o mais dos atos de Menaém, e tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Israel?'),
('acf','2rs',15,22,'E Menaém dormiu com seus pais; e Pecaías, seu filho, reinou em seu lugar.'),
('acf','2rs',15,23,'No ano cinqüenta de Azarias, rei de Judá, começou a reinar Pecaías, filho de Menaém, sobre Israel, em Samaria, e reinou dois anos.'),
('acf','2rs',15,24,'E fez o que era mau aos olhos do Senhor; nunca se apartou dos pecados de Jeroboão, filho de Nebate, com que fez pecar a Israel.'),
('acf','2rs',15,25,'E Peca, filho de Remalias, seu capitão, conspirou contra ele, e o feriu em Samaria, no paço da casa do rei, juntamente com Argobe e com Arié, e com ele cinqüenta homens dos filhos dos gileaditas; e o matou, e reinou em seu lugar.'),
('acf','2rs',15,26,'Ora, o mais dos atos de Pecaías, e tudo quanto fez, eis que está escrito no livro das crônicas dos reis de Israel.'),
('acf','2rs',15,27,'No ano cinqüenta e dois de Azarias, rei de Judá, começou a reinar Peca, filho de Remalias, sobre Israel, em Samaria, e reinou vinte anos.'),
('acf','2rs',15,28,'E fez o que era mau aos olhos do Senhor; nunca se apartou dos pecados de Jeroboão, filho de Nebate, com que fez pecar a Israel.'),
('acf','2rs',15,29,'Nos dias de Peca, rei de Israel, veio Tiglate-Pileser, rei da Assíria, e tomou a Ijom, a Abel-Bete-Maaca, a Janoa, e a Quedes, a Hazor, a Gileade, e a Galiléia, e a toda a terra de Naftali, e os levou à Assíria.'),
('acf','2rs',15,30,'E Oséias, filho de Elá, conspirou contra Peca, filho de Remalias, e o feriu, e o matou, e reinou em seu lugar, no vigésimo ano de Jotão, filho de Uzias.'),
('acf','2rs',15,31,'Ora, o mais dos atos de Peca, e tudo quanto fez, eis que está escrito no livro das crônicas dos reis de Israel.'),
('acf','2rs',15,32,'No ano segundo de Peca, filho de Remalias, rei de Israel, começou a reinar Jotão, filho de Uzias, rei de Judá.'),
('acf','2rs',15,33,'Tinha vinte e cinco anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém; e era o nome de sua mãe Jerusa, filha de Zadoque.'),
('acf','2rs',15,34,'E fez o que era reto aos olhos do Senhor; fez conforme tudo quanto fizera seu pai Uzias.'),
('acf','2rs',15,35,'Tão-somente os altos não foram tirados; porque o povo ainda sacrificava e queimava incenso nos altos. Este edificou a porta alta da casa do Senhor.'),
('acf','2rs',15,36,'Ora, o mais dos atos de Jotão, e tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',15,37,'Naqueles dias começou o Senhor a enviar contra Judá a Rezim, rei da Síria, e a Peca, filho de Remalias.'),
('acf','2rs',15,38,'E Jotão dormiu com seus pais, e foi sepultado junto a seus pais, na cidade de Davi, seu pai; e Acaz, seu filho, reinou em seu lugar.'),
('acf','2rs',16,1,'No ano dezessete de Peca, filho de Remalias, começou a reinar Acaz, filho de Jotão, rei de Judá.'),
('acf','2rs',16,2,'Tinha Acaz vinte anos de idade quando começou a reinar, e reinou dezesseis anos em Jerusalém, e não fez o que era reto aos olhos do Senhor seu Deus, como Davi, seu pai.'),
('acf','2rs',16,3,'Porque andou no caminho dos reis de Israel, e até a seu filho fez passar pelo fogo, segundo as abominações dos gentios que o Senhor lançara fora de diante dos filhos de Israel.'),
('acf','2rs',16,4,'Também sacrificou, e queimou incenso nos altos e nos outeiros, como também debaixo de todo o arvoredo.'),
('acf','2rs',16,5,'Então subiu Rezim, rei da Síria, com Peca, filho de Remalias, rei de Israel, a Jerusalém, para pelejar; e cercaram a Acaz, porém não o puderam vencer.'),
('acf','2rs',16,6,'Naquele mesmo tempo Rezim, rei da Síria, restituiu Elate à Síria, e lançou fora de Elate os judeus; e os sírios vieram a Elate, e habitaram ali até ao dia de hoje.'),
('acf','2rs',16,7,'E Acaz enviou mensageiros a Tiglate-Pileser, rei da Assíria, dizendo: Eu sou teu servo e teu filho; sobe, e livra-me das mãos do rei da Síria, e das mãos do rei de Israel, que se levantam contra mim.'),
('acf','2rs',16,8,'E tomou Acaz a prata e o ouro que se achou na casa do Senhor, e nos tesouros da casa do rei, e mandou um presente ao rei da Assíria.'),
('acf','2rs',16,9,'E o rei da Assíria lhe deu ouvidos; pois o rei da Assíria subiu contra Damasco, e tomou-a e levou cativo o povo para Quir, e matou a Rezim.'),
('acf','2rs',16,10,'Então o rei Acaz foi a Damasco, a encontrar-se com Tiglate-Pileser, rei da Assíria; e, vendo um altar que estava em Damasco, o rei Acaz enviou ao sacerdote Urias o desenho e o modelo do altar, conforme toda a sua feitura.'),
('acf','2rs',16,11,'E Urias, o sacerdote, edificou um altar conforme tudo o que o rei Acaz lhe tinha enviado de Damasco; assim o fez o sacerdote Urias, antes que o rei Acaz viesse de Damasco.'),
('acf','2rs',16,12,'Vindo, pois, o rei de Damasco, viu o altar; e o rei se chegou ao altar, e sacrificou nele.'),
('acf','2rs',16,13,'E queimou o seu holocausto, e a sua oferta de alimentos, e derramou a sua libação, e espargiu o sangue dos seus sacrifícios pacíficos sobre o altar.'),
('acf','2rs',16,14,'Porém o altar de cobre, que estava perante o Senhor, ele tirou de diante da casa, de entre o seu altar e a casa do Senhor, e pô-lo ao lado do altar, do lado do norte.'),
('acf','2rs',16,15,'E o rei Acaz ordenou a Urias, o sacerdote, dizendo: Queima no grande altar o holocausto da manhã, como também a oferta de alimentos da noite, o holocausto do rei e a sua oferta de alimentos, e o holocausto de todo o povo da terra, a sua oferta de alimentos, as suas ofertas de bebidas e todo o sangue dos holocaustos, e todo o sangue dos sacrifícios espargirás nele; porém o altar de cobre será para mim, para nele inquirir.'),
('acf','2rs',16,16,'E fez Urias, o sacerdote, conforme tudo quanto o rei Acaz lhe ordenara.'),
('acf','2rs',16,17,'E o rei Acaz cortou as cintas das bases, e de cima delas tomou a pia, e tirou o mar de sobre os bois de cobre, que estavam debaixo dele, e pô-lo sobre um pavimento de pedra.'),
('acf','2rs',16,18,'Também a coberta que, para o sábado, edificaram na casa, e a entrada real externa, retirou da casa do Senhor, por causa do rei da Assíria.'),
('acf','2rs',16,19,'Ora, o mais dos atos de Acaz e o que fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',16,20,'E dormiu Acaz com seus pais, e foi sepultado junto a seus pais, na cidade de Davi; e Ezequias, seu filho, reinou em seu lugar.'),
('acf','2rs',17,1,'No ano duodécimo de Acaz, rei de Judá, começou a reinar Oséias, filho de Elá, e reinou sobre Israel, em Samaria, nove anos.'),
('acf','2rs',17,2,'E fez o que era mau aos olhos do Senhor, contudo não como os reis de Israel que foram antes dele.'),
('acf','2rs',17,3,'Contra ele subiu Salmaneser, rei da Assíria; e Oséias ficou sendo servo dele, e pagava-lhe tributos.'),
('acf','2rs',17,4,'Porém o rei da Assíria achou em Oséias conspiração; porque enviara mensageiros a Sô, rei do Egito, e não pagava tributos ao rei da Assíria cada ano, como dantes; então o rei da Assíria o encerrou e aprisionou na casa do cárcere.'),
('acf','2rs',17,5,'Porque o rei da Assíria subiu por toda a terra, e veio até Samaria, e a cercou três anos.'),
('acf','2rs',17,6,'No ano nono de Oséias, o rei da Assíria tomou a Samaria, e levou Israel cativo para a Assíria; e fê-los habitar em Hala e em Habor junto ao rio de Gozã, e nas cidades dos medos,'),
('acf','2rs',17,7,'Porque sucedeu que os filhos de Israel pecaram contra o Senhor seu Deus, que os fizera subir da terra do Egito, de debaixo da mão de Faraó, rei do Egito; e temeram a outros deuses.'),
('acf','2rs',17,8,'E andaram nos estatutos das nações que o Senhor lançara fora de diante dos filhos de Israel, e nos dos reis de Israel, que eles fizeram.'),
('acf','2rs',17,9,'E os filhos de Israel fizeram secretamente coisas que não eram retas, contra o Senhor seu Deus; e edificaram altos em todas as suas cidades, desde a torre dos atalaias até à cidade fortificada.'),
('acf','2rs',17,10,'E levantaram, para si, estátuas e imagens do bosque, em todos os altos outeiros, e debaixo de todas as árvores verdes.'),
('acf','2rs',17,11,'E queimaram ali incenso em todos os altos, como as nações, que o Senhor expulsara de diante deles; e fizeram coisas ruins, para provocarem à ira o Senhor.'),
('acf','2rs',17,12,'E serviram os ídolos, dos quais o Senhor lhes dissera: Não fareis estas coisas.'),
('acf','2rs',17,13,'E o Senhor advertiu a Israel e a Judá, pelo ministério de todos os profetas e de todos os videntes, dizendo: Convertei-vos de vossos maus caminhos, e guardai os meus mandamentos e os meus estatutos, conforme toda a lei que ordenei a vossos pais e que eu vos enviei pelo ministério de meus servos, os profetas.'),
('acf','2rs',17,14,'Porém não deram ouvidos; antes endureceram a sua cerviz, como a cerviz de seus pais, que não creram no Senhor seu Deus.'),
('acf','2rs',17,15,'E rejeitaram os seus estatutos, e a sua aliança que fizera com seus pais, como também as suas advertências, com que protestara contra eles; e seguiram a vaidade, e tornaram-se vãos; como também seguiram as nações, que estavam ao redor deles, das quais o Senhor lhes tinha ordenado que não as imitassem.'),
('acf','2rs',17,16,'E deixaram todos os mandamentos do Senhor seu Deus, e fizeram imagens de fundição, dois bezerros; e fizeram um ídolo do bosque, e adoraram perante todo o exército do céu, e serviram a Baal.'),
('acf','2rs',17,17,'Também fizeram passar pelo fogo a seus filhos e suas filhas, e deram-se a adivinhações, e criam em agouros; e venderam-se para fazer o que era mau aos olhos do Senhor, para o provocarem à ira.'),
('acf','2rs',17,18,'Portanto o Senhor muito se indignou contra Israel, e os tirou de diante da sua face; nada mais ficou, senão somente a tribo de Judá.'),
('acf','2rs',17,19,'Até Judá não guardou os mandamentos do Senhor seu Deus; antes andaram nos estatutos de Israel, que eles fizeram.'),
('acf','2rs',17,20,'Por isso o Senhor rejeitou a toda a descendência de Israel, e os oprimiu, e os deu nas mãos dos despojadores, até que os expulsou da sua presença.'),
('acf','2rs',17,21,'Porque rasgou a Israel da casa de Davi; e eles fizeram rei a Jeroboão, filho de Nebate. E Jeroboão apartou a Israel de seguir ao Senhor, e os fez cometer um grande pecado.'),
('acf','2rs',17,22,'Assim andaram os filhos de Israel em todos os pecados que Jeroboão tinha feito; nunca se apartaram deles;'),
('acf','2rs',17,23,'Até que o Senhor tirou a Israel de diante da sua presença, como falara pelo ministério de todos os seus servos, os profetas; assim foi Israel expulso da sua terra à Assíria até ao dia de hoje.'),
('acf','2rs',17,24,'E o rei da Assíria trouxe gente de Babilônia, de Cuta, de Ava, de Hamate e Sefarvaim, e a fez habitar nas cidades de Samaria, em lugar dos filhos de Israel; e eles tomaram a Samaria em herança, e habitaram nas suas cidades.'),
('acf','2rs',17,25,'E sucedeu que, no princípio da sua habitação ali, não temeram ao Senhor; e o Senhor mandou entre eles, leões, que mataram a alguns deles.'),
('acf','2rs',17,26,'Por isso falaram ao rei da Assíria, dizendo: A gente que transportaste e fizeste habitar nas cidades de Samaria, não sabe o costume do Deus da terra; assim mandou leões entre ela, e eis que a matam, porquanto não sabe o culto do Deus da terra.'),
('acf','2rs',17,27,'Então o rei da Assíria mandou dizer: Levai ali um dos sacerdotes que transportastes de lá; e vá e habite lá, e ele lhes ensine o costume do Deus da terra.'),
('acf','2rs',17,28,'Veio, pois, um dos sacerdotes que transportaram de Samaria, e habitou em Betel, e lhes ensinou como deviam temer ao Senhor.'),
('acf','2rs',17,29,'Porém cada nação fez os seus deuses, e os puseram nas casas dos altos que os samaritanos fizeram, cada nação nas cidades, em que habitava.'),
('acf','2rs',17,30,'E os de babilônia fizeram Sucote-Benote; e os de Cuta fizeram Nergal; e os de Hamate fizeram Asima.'),
('acf','2rs',17,31,'E os aveus fizeram Nibaz e Tartaque; e os sefarvitas queimavam seus filhos no fogo a Adrameleque, e a Anameleque, deuses de Sefarvaim.'),
('acf','2rs',17,32,'Também temiam ao Senhor; e dos mais baixos do povo fizeram sacerdotes dos lugares altos, os quais lhes faziam o ministério nas casas dos lugares altos.'),
('acf','2rs',17,33,'Assim temiam ao Senhor, mas também serviam a seus deuses, segundo o costume das nações dentre as quais tinham sido transportados.'),
('acf','2rs',17,34,'Até ao dia de hoje fazem segundo os primeiros costumes; não temem ao Senhor, nem fazem segundo os seus estatutos, segundo as suas ordenanças, segundo a lei e segundo o mandamento que o Senhor ordenou aos filhos de Jacó, a quem deu o nome de Israel.'),
('acf','2rs',17,35,'Contudo o Senhor tinha feito uma aliança com eles, e lhes ordenara, dizendo: Não temereis a outros deuses, nem vos inclinareis diante deles, nem os servireis, nem lhes sacrificareis.'),
('acf','2rs',17,36,'Mas o Senhor, que vos fez subir da terra do Egito com grande força e com braço estendido, a este temereis, e a ele vos inclinareis e a ele sacrificareis.'),
('acf','2rs',17,37,'E os estatutos, as ordenanças, a lei e o mandamento, que vos escreveu, tereis cuidado de fazer todos os dias; e não temereis a outros deuses.'),
('acf','2rs',17,38,'E da aliança que fiz convosco não vos esquecereis; e não temereis a outros deuses.'),
('acf','2rs',17,39,'Mas ao Senhor vosso Deus temereis, e ele vos livrará das mãos de todos os vossos inimigos.'),
('acf','2rs',17,40,'Porém eles não ouviram; antes fizeram segundo o seu primeiro costume.'),
('acf','2rs',17,41,'Assim estas nações temiam ao Senhor e serviam as suas imagens de escultura; também seus filhos, e os filhos de seus filhos, como fizeram seus pais, assim fazem eles até ao dia de hoje.'),
('acf','2rs',18,1,'E sucedeu que, no terceiro ano de Oséias, filho de Elá, rei de Israel, começou a reinar Ezequias, filho de Acaz, rei de Judá.'),
('acf','2rs',18,2,'Tinha vinte e cinco anos de idade quando começou a reinar, e vinte e nove anos reinou em Jerusalém; e era o nome de sua mãe Abi, filha de Zacarias.'),
('acf','2rs',18,3,'E fez o que era reto aos olhos do Senhor, conforme tudo o que fizera Davi, seu pai.'),
('acf','2rs',18,4,'Ele tirou os altos, quebrou as estátuas, deitou abaixo os bosques, e fez em pedaços a serpente de metal que Moisés fizera; porquanto até àquele dia os filhos de Israel lhe queimavam incenso, e lhe chamaram Neustã.'),
('acf','2rs',18,5,'No Senhor Deus de Israel confiou, de maneira que depois dele não houve quem lhe fosse semelhante entre todos os reis de Judá, nem entre os que foram antes dele.'),
('acf','2rs',18,6,'Porque se chegou ao Senhor, não se apartou dele, e guardou os mandamentos que o Senhor tinha dado a Moisés.'),
('acf','2rs',18,7,'Assim foi o Senhor com ele; para onde quer que saía se conduzia com prudência; e se rebelou contra o rei da Assíria, e não o serviu.'),
('acf','2rs',18,8,'Ele feriu os filisteus até Gaza, como também os seus termos, desde a torre dos atalaias até à cidade fortificada.'),
('acf','2rs',18,9,'E sucedeu, no quarto ano do rei Ezequias (que era o sétimo ano de Oséias, filho de Elá, rei de Israel), que Salmaneser, rei da Assíria, subiu contra Samaria, e a cercou.'),
('acf','2rs',18,10,'E a tomaram ao fim de três anos, no ano sexto de Ezequias, que era o ano nono de Oséias, rei de Israel, quando tomaram Samaria.'),
('acf','2rs',18,11,'E o rei da Assíria transportou a Israel para a Assíria; e os fez levar a Hala e a Habor, junto ao rio de Gozã, e às cidades dos medos;'),
('acf','2rs',18,12,'Porquanto não obedeceram à voz do Senhor seu Deus, antes transgrediram a sua aliança; e tudo quanto Moisés, servo do Senhor, tinha ordenado, nem o ouviram nem o fizeram.'),
('acf','2rs',18,13,'Porém no ano décimo quarto do rei Ezequias subiu Senaqueribe, rei da Assíria, contra todas as cidades fortificadas de Judá, e as tomou.'),
('acf','2rs',18,14,'Então Ezequias, rei de Judá, enviou ao rei da Assíria, a Laquis, dizendo: Pequei; retira-te de mim; tudo o que me impuseres suportarei. Então o rei da Assíria impôs a Ezequias, rei de Judá, trezentos talentos de prata e trinta talentos de ouro.'),
('acf','2rs',18,15,'Assim deu Ezequias toda a prata que se achou na casa do Senhor e nos tesouros da casa do rei.'),
('acf','2rs',18,16,'Naquele tempo cortou Ezequias o ouro das portas do templo do Senhor, e das ombreiras, de que ele, rei de Judá, as cobrira, e o deu ao rei da Assíria.'),
('acf','2rs',18,17,'Contudo enviou o rei da Assíria a Tartã, e a Rabe-Saris, e a Rabsaqué, de Laquis, com grande exército ao rei Ezequias, a Jerusalém; subiram, e vieram a Jerusalém. E, subindo e vindo eles, pararam ao pé do aqueduto da piscina superior, que está junto ao caminho do campo do lavandeiro.'),
('acf','2rs',18,18,'E chamaram o rei; e saíram a eles Eliaquim, filho de Hilquias, o mordomo, e Sebna, o escrivão, e Joá, filho de Asafe, o cronista.'),
('acf','2rs',18,19,'E Rabsaqué lhes disse: Ora, dizei a Ezequias: Assim diz o grande rei, o rei da Assíria: Que confiança é esta em que te estribas?'),
('acf','2rs',18,20,'Dizes tu (porém são palavras só de lábios): Há conselho e poder para a guerra. Em quem, pois, agora confias, que contra mim te rebelas?'),
('acf','2rs',18,21,'Eis que agora tu confias naquele bordão de cana quebrada, no Egito, no qual, se alguém se encostar, entrar-lhe-á pela mão e a furará; assim é Faraó, rei do Egito, para com todos os que nele confiam.'),
('acf','2rs',18,22,'Se, porém, me disserdes: No Senhor nosso Deus confiamos; porventura não é esse aquele cujos altos e cujos altares Ezequias tirou, dizendo a Judá e a Jerusalém: Perante este altar vos inclinareis em Jerusalém?'),
('acf','2rs',18,23,'Ora, pois, dá agora reféns ao meu senhor, o rei da Assíria, e dar-te-ei dois mil cavalos, se tu puderes dar cavaleiros para eles.'),
('acf','2rs',18,24,'Como, pois, farias virar o rosto de um só capitão dos menores servos de meu senhor, quando tu confias no Egito, por causa dos carros e cavaleiros?'),
('acf','2rs',18,25,'Agora, pois, subi eu porventura sem o Senhor contra este lugar, para o destruir? O Senhor me disse: Sobe contra esta terra, e destrói-a.'),
('acf','2rs',18,26,'Então disse Eliaquim, filho de Hilquias, e Sebna e Joá, a Rabsaqué: Rogamos-te que fales aos teus servos em siríaco; porque bem o entendemos; e não nos fales em judaico, aos ouvidos do povo que está em cima do muro.'),
('acf','2rs',18,27,'Porém Rabsaqué lhes disse: Porventura mandou-me meu senhor somente a teu senhor e a ti, para falar estas palavras e não antes aos homens, que estão sentados em cima do muro, para que juntamente convosco comam o seu excremento e bebam a sua urina?'),
('acf','2rs',18,28,'Rabsaqué, pois, se pôs em pé, e clamou em alta voz em judaico, e respondeu, dizendo: Ouvi a palavra do grande rei, do rei da Assíria.'),
('acf','2rs',18,29,'Assim diz o rei: Não vos engane Ezequias; porque não vos poderá livrar da sua mão;'),
('acf','2rs',18,30,'Nem tampouco vos faça Ezequias confiar no Senhor, dizendo: Certamente nos livrará o Senhor, e esta cidade não será entregue na mão do rei da Assíria.'),
('acf','2rs',18,31,'Não deis ouvidos a Ezequias; porque assim diz o rei da Assíria: Contratai comigo por presentes, e saí a mim, e coma cada um da sua vide e da sua figueira, e beba cada um a água da sua cisterna;'),
('acf','2rs',18,32,'Até que eu venha, e vos leve para uma terra como a vossa, terra de trigo e de mosto, terra de pão e de vinhas, terra de oliveiras, de azeite e de mel; e assim vivereis, e não morrereis; e não deis ouvidos a Ezequias; porque vos incita, dizendo: O Senhor nos livrará.'),
('acf','2rs',18,33,'Porventura os deuses das nações puderam livrar, cada um a sua terra, das mãos do rei da Assíria?'),
('acf','2rs',18,34,'Que é feito dos deuses de Hamate e de Arpade? Que é feito dos deuses de Sefarvaim, Hena e Iva? Porventura livraram a Samaria da minha mão?'),
('acf','2rs',18,35,'Quais são eles, dentre todos os deuses das terras, que livraram a sua terra da minha mão, para que o Senhor livrasse a Jerusalém da minha mão?'),
('acf','2rs',18,36,'Porém calou-se o povo, e não lhe respondeu uma só palavra; porque mandado do rei havia, dizendo: Não lhe respondereis.'),
('acf','2rs',18,37,'Então Eliaquim, filho de Hilquias, o mordomo, e Sebna, o escrivão, e Joá, filho de Asafe, o cronista, vieram a Ezequias com as vestes rasgadas, e lhe fizeram saber as palavras de Rabsaqué.'),
('acf','2rs',19,1,'E aconteceu que, tendo Ezequias ouvido isto, rasgou as suas vestes, e se cobriu de saco, e entrou na casa do SENHOR.'),
('acf','2rs',19,2,'Então enviou a Eliaquim, o mordomo, e a Sebna, o escrivão, e os anciãos dos sacerdotes, cobertos de sacos, ao profeta Isaías, filho de Amós.'),
('acf','2rs',19,3,'E disseram-lhe: Assim diz Ezequias: Este dia é dia de angústia, de vituperação e de blasfêmia; porque os filhos chegaram ao parto, e não há força para dá-los à luz.'),
('acf','2rs',19,4,'Bem pode ser que o SENHOR teu Deus ouça todas as palavras de Rabsaqué, a quem enviou o seu senhor, o rei da Assíria, para afrontar o Deus vivo, e para vituperá-lo com as palavras que o SENHOR teu Deus tem ouvido; faze, pois, oração pelo restante que subsiste.'),
('acf','2rs',19,5,'E os servos do rei Ezequias foram a Isaías.'),
('acf','2rs',19,6,'E Isaías lhes disse: Assim direis a vosso senhor: Assim diz o SENHOR: Não temas as palavras que ouviste, com as quais os servos do rei da Assíria me blasfemaram.'),
('acf','2rs',19,7,'Eis que porei nele um espírito, e ele ouvirá um rumor, e voltará para a sua terra; à espada o farei cair na sua terra.'),
('acf','2rs',19,8,'Voltou, pois, Rabsaqué, e achou o rei da Assíria pelejando contra Libna, porque tinha ouvido que o rei havia partido de Laquis.'),
('acf','2rs',19,9,'E, ouvindo ele dizer de Tiraca, rei da Etiópia: Eis que saiu para te fazer guerra; tornou a enviar mensageiros a Ezequias, dizendo:'),
('acf','2rs',19,10,'Assim falareis a Ezequias, rei de Judá: Não te engane o teu Deus, em quem confias, dizendo: Jerusalém não será entregue na mão do rei da Assíria.'),
('acf','2rs',19,11,'Eis que já tens ouvido o que fizeram os reis da Assíria a todas as terras, destruindo-as totalmente; e tu, te livrarás?'),
('acf','2rs',19,12,'Porventura as livraram os deuses das nações, a quem meus pais destruíram, como a Gozã, a Harã, a Rezefe, e aos filhos de Éden, que estavam em Telassar?'),
('acf','2rs',19,13,'Que é feito do rei de Hamate, do rei de Arpade, e do rei da cidade de Sefarvaim, Hena e Iva?'),
('acf','2rs',19,14,'Recebendo, pois, Ezequias as cartas das mãos dos mensageiros e lendo-as, subiu à casa do Senhor; e Ezequias as estendeu perante o Senhor.'),
('acf','2rs',19,15,'E orou Ezequias perante o Senhor e disse: Ó Senhor Deus de Israel, que habitas entre os querubins, tu mesmo, só tu és Deus de todos os reinos da terra; tu fizeste os céus e a terra.'),
('acf','2rs',19,16,'Inclina, Senhor, o teu ouvido, e ouve; abre, Senhor, os teus olhos, e olha; e ouve as palavras de Senaqueribe, que enviou a este, para afrontar o Deus vivo.'),
('acf','2rs',19,17,'Verdade é, ó Senhor, que os reis da Assíria assolaram as nações e as suas terras.'),
('acf','2rs',19,18,'E lançaram os seus deuses no fogo; porquanto não eram deuses, mas obra de mãos de homens, madeira e pedra; por isso os destruíram.'),
('acf','2rs',19,19,'Agora, pois, ó Senhor nosso Deus, te suplico, livra-nos da sua mão; e assim saberão todos os reinos da terra que só tu és o Senhor Deus.'),
('acf','2rs',19,20,'Então Isaías, filho de Amós, mandou dizer a Ezequias: Assim diz o Senhor Deus de Israel: O que me pediste acerca de Senaqueribe, rei da Assíria, ouvi.'),
('acf','2rs',19,21,'Esta é a palavra que o Senhor falou dele: A virgem, a filha de Sião, te despreza, de ti zomba; a filha de Jerusalém meneia a cabeça por detrás de ti.'),
('acf','2rs',19,22,'A quem afrontaste e blasfemaste? E contra quem alçaste a voz e ergueste os teus olhos ao alto? Contra o Santo de Israel?'),
('acf','2rs',19,23,'Por meio de teus mensageiros afrontaste o Senhor, e disseste: Com a multidão de meus carros subi ao alto dos montes, aos lados do Líbano, e cortarei os seus altos cedros e as suas mais formosas faias, e entrarei nas suas pousadas extremas, até no bosque do seu campo fértil.'),
('acf','2rs',19,24,'Eu cavei, e bebi águas estranhas; e com as plantas de meus pés sequei todos os rios do Egito.'),
('acf','2rs',19,25,'Porventura não ouviste que já dantes fiz isto, e já desde os dias antigos o planejei? Agora, porém, o fiz vir, para que fosses tu que reduzisses as cidades fortificadas a montões desertos.'),
('acf','2rs',19,26,'Por isso os moradores delas, com pouca força, ficaram pasmados e confundidos; eram como a erva do campo, e a hortaliça verde, e o feno dos telhados, e o trigo queimado, antes de amadurecer.'),
('acf','2rs',19,27,'Porém o teu assentar, e o teu sair e o teu entrar, e o teu furor contra mim, eu o sei.'),
('acf','2rs',19,28,'Por causa do teu furor contra mim, e porque a tua revolta subiu aos meus ouvidos, portanto porei o meu anzol no teu nariz e o meu freio nos teus lábios, e te farei voltar pelo caminho por onde vieste.'),
('acf','2rs',19,29,'E isto te será por sinal; este ano se comerá o que nascer por si mesmo, e no ano seguinte o que daí proceder; porém, no terceiro ano semeai e segai, plantai vinhas, e comei os seus frutos.'),
('acf','2rs',19,30,'Porque o que escapou da casa de Judá, e restou, tornará a lançar raízes para baixo, e dará fruto para cima.'),
('acf','2rs',19,31,'Porque de Jerusalém sairá o restante, e do monte Sião o que escapou; o zelo do Senhor dos Exércitos fará isto.'),
('acf','2rs',19,32,'Portanto, assim diz o Senhor acerca do rei da Assíria: Não entrará nesta cidade, nem lançará nela flecha alguma; tampouco virá perante ela com escudo, nem levantará contra ela trincheira alguma.'),
('acf','2rs',19,33,'Pelo caminho por onde vier, por ele voltará; porém nesta cidade não entrará, diz o Senhor.'),
('acf','2rs',19,34,'Porque eu ampararei a esta cidade, para a livrar, por amor de mim e por amor do meu servo Davi.'),
('acf','2rs',19,35,'Sucedeu, pois, que naquela mesma noite saiu o anjo do Senhor, e feriu no arraial dos assírios a cento e oitenta e cinco mil deles; e, levantando-se pela manhã cedo, eis que todos eram cadáveres.'),
('acf','2rs',19,36,'Então Senaqueribe, rei da Assíria, partiu, e se foi, e voltou e ficou em Nínive.'),
('acf','2rs',19,37,'E sucedeu que, estando ele prostrado na casa de Nisroque, seu deus, Adrameleque e Sarezer, seus filhos, o feriram à espada; porém eles escaparam para a terra de Ararate; e Esar-Hadom, seu filho, reinou em seu lugar.'),
('acf','2rs',20,1,'Naqueles dias adoeceu Ezequias mortalmente; e o profeta Isaías, filho de Amós, veio a ele e lhe disse: Assim diz o SENHOR: Põe em ordem a tua casa, porque morrerás, e não viverás.'),
('acf','2rs',20,2,'Então virou o rosto para a parede, e orou ao Senhor, dizendo:'),
('acf','2rs',20,3,'Ah, Senhor! Suplico-te lembrar de que andei diante de ti em verdade, com o coração perfeito, e fiz o que era bom aos teus olhos. E chorou Ezequias muitíssimo.'),
('acf','2rs',20,4,'Sucedeu, pois, que, não havendo Isaías ainda saído do meio do pátio, veio a ele a palavra do Senhor dizendo:'),
('acf','2rs',20,5,'Volta, e dize a Ezequias, capitão do meu povo: Assim diz o Senhor, o Deus de Davi, teu pai: Ouvi a tua oração, e vi as tuas lágrimas; eis que eu te sararei; ao terceiro dia subirás à casa do Senhor.'),
('acf','2rs',20,6,'E acrescentarei aos teus dias quinze anos, e das mãos do rei da Assíria te livrarei, a ti e a esta cidade; e ampararei esta cidade por amor de mim, e por amor de Davi, meu servo.'),
('acf','2rs',20,7,'Disse mais Isaías: Tomai uma pasta de figos. E a tomaram, e a puseram sobre a chaga; e ele sarou.'),
('acf','2rs',20,8,'E Ezequias disse a Isaías: Qual é o sinal de que o Senhor me sarará, e de que ao terceiro dia subirei à casa do Senhor?'),
('acf','2rs',20,9,'Disse Isaías: Isto te será sinal, da parte do Senhor, de que o Senhor cumprirá a palavra que disse: Adiantar-se-á a sombra dez graus, ou voltará dez graus atrás?'),
('acf','2rs',20,10,'Então disse Ezequias: É fácil que a sombra decline dez graus; não seja assim, mas volte a sombra dez graus atrás.'),
('acf','2rs',20,11,'Então o profeta Isaías clamou ao Senhor; e fez voltar a sombra dez graus atrás, pelos graus que tinha declinado no relógio de sol de Acaz.'),
('acf','2rs',20,12,'Naquele tempo enviou Berodaque-Baladã, filho de Baladã, rei de babilônia, cartas e um presente a Ezequias; porque ouvira que Ezequias tinha estado doente.'),
('acf','2rs',20,13,'E Ezequias lhes deu ouvidos; e lhes mostrou toda a casa de seu tesouro, a prata, o ouro, as especiarias e os melhores ungüentos, e a sua casa de armas, e tudo quanto se achou nos seus tesouros; coisa nenhuma houve que não lhes mostrasse, nem em sua casa, nem em todo o seu domínio.'),
('acf','2rs',20,14,'Então o profeta Isaías veio ao rei Ezequias, e lhe disse: Que disseram aqueles homens, e de onde vieram a ti? Disse Ezequias: Vieram de um país muito remoto, de babilônia.'),
('acf','2rs',20,15,'E disse ele: Que viram em tua casa? E disse Ezequias: Tudo quanto há em minha casa viram; coisa nenhuma há nos meus tesouros que eu não lhes mostrasse.'),
('acf','2rs',20,16,'Então disse Isaías a Ezequias: Ouve a palavra do Senhor.'),
('acf','2rs',20,17,'Eis que vêm dias em que tudo quanto houver em tua casa, e o que entesouraram teus pais até ao dia de hoje, será levado a babilônia; não ficará coisa alguma, disse o SENHOR.'),
('acf','2rs',20,18,'E ainda até de teus filhos, que procederem de ti, e que tu gerares, tomarão, para que sejam eunucos no paço do rei da babilônia.'),
('acf','2rs',20,19,'Então disse Ezequias a Isaías: Boa é a palavra do Senhor que disseste. Disse mais: E não haverá, pois, em meus dias paz e verdade?'),
('acf','2rs',20,20,'Ora, o mais dos atos de Ezequias, e todo o seu poder, e como fez a piscina e o aqueduto, e como fez vir a água à cidade, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',20,21,'E Ezequias dormiu com seus pais; e Manassés, seu filho, reinou em seu lugar.'),
('acf','2rs',21,1,'Tinha Manassés doze anos de idade quando começou a reinar, e cinqüenta e cinco anos reinou em Jerusalém; e era o nome de sua mãe Hefzibá.'),
('acf','2rs',21,2,'E fez o que era mau aos olhos do Senhor, conforme as abominações dos gentios que o Senhor expulsara de suas possessões, de diante dos filhos de Israel.'),
('acf','2rs',21,3,'Porque tornou a edificar os altos que Ezequias, seu pai, tinha destruído, e levantou altares a Baal, e fez um bosque como o que fizera Acabe, rei de Israel, e se inclinou diante de todo o exército dos céus, e os serviu.'),
('acf','2rs',21,4,'E edificou altares na casa do Senhor, da qual o Senhor tinha falado: Em Jerusalém porei o meu nome.'),
('acf','2rs',21,5,'Também edificou altares a todo o exército dos céus em ambos os átrios da casa do Senhor.'),
('acf','2rs',21,6,'E até fez passar a seu filho pelo fogo, adivinhava pelas nuvens, era agoureiro e ordenou adivinhos e feiticeiros; e prosseguiu em fazer o que era mau aos olhos do Senhor, para o provocar à ira.'),
('acf','2rs',21,7,'Também pôs uma imagem de escultura, do bosque que tinha feito, na casa de que o Senhor dissera a Davi e a Salomão, seu filho: Nesta casa e em Jerusalém, que escolhi de todas as tribos de Israel, porei o meu nome para sempre;'),
('acf','2rs',21,8,'E não mais farei mover o pé de Israel desta terra que tenho dado a seus pais; contanto que somente tenham cuidado de fazer conforme tudo o que lhes tenho ordenado, e conforme toda a lei que Moisés, meu servo, lhes ordenou.'),
('acf','2rs',21,9,'Porém não ouviram; porque Manassés de tal modo os fez errar, que fizeram pior do que as nações, que o Senhor tinha destruído de diante dos filhos de Israel.'),
('acf','2rs',21,10,'Então o Senhor falou pelo ministério de seus servos, os profetas, dizendo:'),
('acf','2rs',21,11,'Porquanto Manassés, rei de Judá, fez estas abominações, fazendo pior do que tudo quanto fizeram os amorreus, que foram antes dele, e até também a Judá fez pecar com os seus ídolos;'),
('acf','2rs',21,12,'Por isso, assim diz o Senhor Deus de Israel: Eis que hei de trazer um mal sobre Jerusalém e Judá, que qualquer que ouvir, lhe ficarão retinindo ambos os ouvidos.'),
('acf','2rs',21,13,'E estenderei sobre Jerusalém o cordel de Samaria e o prumo da casa de Acabe; e limparei a Jerusalém, como quem limpa o prato, limpa-o e vira-o para baixo.'),
('acf','2rs',21,14,'E desampararei os restantes da minha herança, entregá-los-ei na mão de seus inimigos; e servirão de presa e despojo para todos os seus inimigos;'),
('acf','2rs',21,15,'Porquanto fizeram o que era mau aos meus olhos e me provocaram à ira, desde o dia em que seus pais saíram do Egito até hoje.'),
('acf','2rs',21,16,'Além disso, também Manassés derramou muitíssimo sangue inocente, até que encheu a Jerusalém de um ao outro extremo, afora o seu pecado, com que fez Judá pecar, fazendo o que era mau aos olhos do Senhor.'),
('acf','2rs',21,17,'Quanto ao mais dos feitos de Manassés, e a tudo quanto fez, e ao seu pecado, que praticou, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',21,18,'E Manassés dormiu com seus pais, e foi sepultado no jardim da sua casa, no jardim de Uzá; e Amom, seu filho, reinou em seu lugar.'),
('acf','2rs',21,19,'Tinha Amom vinte e dois anos de idade quando começou a reinar, e dois anos reinou em Jerusalém; e era o nome de sua mãe Mesulemete, filha de Harus, de Jotbá.'),
('acf','2rs',21,20,'E fez o que era mau aos olhos do Senhor, como fizera Manassés, seu pai.'),
('acf','2rs',21,21,'Porque andou em todo o caminho em que andara seu pai; e serviu os ídolos, a que seu pai tinha servido, e se inclinou diante deles.'),
('acf','2rs',21,22,'Assim deixou ao Senhor Deus de seus pais, e não andou no caminho do Senhor.'),
('acf','2rs',21,23,'E os servos de Amom conspiraram contra ele, e mataram o rei em sua casa.'),
('acf','2rs',21,24,'Porém o povo da terra feriu a todos os que conspiraram contra o rei Amom; e o povo da terra pôs Josias, seu filho, rei em seu lugar.'),
('acf','2rs',21,25,'Quanto ao mais dos atos de Amom, que fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',21,26,'E o sepultaram na sua sepultura, no jardim de Uzá; e Josias, seu filho, reinou em seu lugar.'),
('acf','2rs',22,1,'Tinha Josias oito anos de idade quando começou a reinar, e reinou trinta e um anos em Jerusalém; e era o nome de sua mãe, Jedida, filha de Adaías, de Bozcate.'),
('acf','2rs',22,2,'E fez o que era reto aos olhos do Senhor; e andou em todo o caminho de Davi, seu pai, e não se apartou dele nem para a direita nem para a esquerda.'),
('acf','2rs',22,3,'Sucedeu que, no ano décimo oitavo do rei Josias, o rei mandou ao escrivão Safã, filho de Azalias, filho de Mesulão, à casa do Senhor, dizendo:'),
('acf','2rs',22,4,'Sobe a Hilquias, o sumo sacerdote, para que tome o dinheiro que se trouxe à casa do Senhor, o qual os guardas do umbral da porta ajuntaram do povo,'),
('acf','2rs',22,5,'E que o dêem na mão dos que têm cargo da obra, e estão encarregados da casa do Senhor; para que o dêem àqueles que fazem a obra que há na casa do Senhor, para repararem as fendas da casa;'),
('acf','2rs',22,6,'Aos carpinteiros, aos edificadores e aos pedreiros; e para comprar madeira e pedras lavradas, para repararem a casa.'),
('acf','2rs',22,7,'Porém não se pediu conta do dinheiro que se lhes entregara nas suas mãos, porquanto procediam com fidelidade.'),
('acf','2rs',22,8,'Então disse o sumo sacerdote Hilquias ao escrivão Safã: Achei o livro da lei na casa do Senhor. E Hilquias deu o livro a Safã, e ele o leu.'),
('acf','2rs',22,9,'Então o escrivão Safã veio ter com o rei e, dando-lhe conta, disse: Teus servos ajuntaram o dinheiro que se achou na casa, e o entregaram na mão dos que têm cargo da obra, que estão encarregados da casa do Senhor.'),
('acf','2rs',22,10,'Também Safã, o escrivão, fez saber ao rei, dizendo: O sacerdote Hilquias me deu um livro. E Safã o leu diante do rei.'),
('acf','2rs',22,11,'Sucedeu, pois, que, ouvindo o rei as palavras do livro da lei, rasgou as suas vestes.'),
('acf','2rs',22,12,'E o rei mandou a Hilquias, o sacerdote, a Aicão, filho de Safã, a Acbor, filho de Micaías, a Safã o escrivão e a Asaías, o servo do rei, dizendo:'),
('acf','2rs',22,13,'Ide, e consultai o Senhor por mim, pelo povo e por todo o Judá, acerca das palavras deste livro que se achou; porque grande é o furor do Senhor, que se acendeu contra nós; porquanto nossos pais não deram ouvidos às palavras deste livro, para fazerem conforme tudo quanto acerca de nós está escrito.'),
('acf','2rs',22,14,'Então foi o sacerdote Hilquias, e Aicão, Acbor, Safã e Asaías à profetisa Hulda, mulher de Salum, filho de Ticvá, o filho de Harás, o guarda das vestiduras (e ela habitava em Jerusalém, na segunda parte), e lhe falaram.'),
('acf','2rs',22,15,'E ela lhes disse: Assim diz o Senhor Deus de Israel: Dizei ao homem que vos enviou a mim:'),
('acf','2rs',22,16,'Assim diz o Senhor: Eis que trarei mal sobre este lugar, e sobre os seus moradores, a saber: todas as palavras do livro que leu o rei de Judá.'),
('acf','2rs',22,17,'Porquanto me deixaram, e queimaram incenso a outros deuses, para me provocarem à ira por todas as obras das suas mãos, o meu furor se acendeu contra este lugar, e não se apagará.'),
('acf','2rs',22,18,'Porém ao rei de Judá, que vos enviou a consultar o Senhor, assim lhe direis: Assim diz o Senhor Deus de Israel, acerca das palavras, que ouviste:'),
('acf','2rs',22,19,'Porquanto o teu coração se enterneceu, e te humilhaste perante o Senhor, quando ouviste o que falei contra este lugar, e contra os seus moradores, que seria para assolação e para maldição, e que rasgaste as tuas vestes, e choraste perante mim, também eu te ouvi, diz o Senhor.'),
('acf','2rs',22,20,'Por isso eis que eu te recolherei a teus pais, e tu serás recolhido em paz à tua sepultura, e os teus olhos não verão todo o mal que hei de trazer sobre este lugar. Então tornaram a trazer ao rei a resposta.'),
('acf','2rs',23,1,'Então o rei ordenou, e todos os anciãos de Judá e de Jerusalém se reuniram a ele.'),
('acf','2rs',23,2,'O rei subiu à casa do Senhor, e com ele todos os homens de Judá, e todos os moradores de Jerusalém, os sacerdotes, os profetas e todo o povo, desde o menor até ao maior; e leu aos ouvidos deles todas as palavras do livro da aliança, que se achou na casa do Senhor.'),
('acf','2rs',23,3,'E o rei se pôs em pé junto à coluna, e fez a aliança perante o Senhor, para seguirem o Senhor, e guardarem os seus mandamentos, os seus testemunhos e os seus estatutos, com todo o coração e com toda a alma, confirmando as palavras desta aliança, que estavam escritas naquele livro; e todo o povo apoiou esta aliança.'),
('acf','2rs',23,4,'E o rei mandou ao sumo sacerdote Hilquias, aos sacerdotes da segunda ordem, e aos guardas do umbral da porta, que tirassem do templo do Senhor todos os vasos que se tinham feito para Baal, para o bosque e para todo o exército dos céus e os queimou fora de Jerusalém, nos campos de Cedrom e levou as cinzas deles a Betel.'),
('acf','2rs',23,5,'Também destituiu os sacerdotes que os reis de Judá estabeleceram para incensarem sobre os altos nas cidades de Judá e ao redor de Jerusalém, como também os que queimavam incenso a Baal, ao sol, à lua, e aos planetas, e a todo o exército dos céus.'),
('acf','2rs',23,6,'Também tirou da casa do Senhor o ídolo do bosque levando-o para fora de Jerusalém até ao ribeiro de Cedrom, e o queimou junto ao ribeiro de Cedrom, e o desfez em pó, e lançou o seu pó sobre as sepulturas dos filhos do povo.'),
('acf','2rs',23,7,'Também derrubou as casas dos sodomitas que estavam na casa do Senhor, em que as mulheres teciam casinhas para o ídolo do bosque.'),
('acf','2rs',23,8,'E a todos os sacerdotes trouxe das cidades de Judá, e profanou os altos em que os sacerdotes queimavam incenso, desde Geba até Berseba; e derrubou os altos que estavam às portas, junto à entrada da porta de Josué, o governador da cidade, que estava à esquerda daquele que entrava pela porta da cidade.'),
('acf','2rs',23,9,'Mas os sacerdotes dos altos não sacrificavam sobre o altar do Senhor em Jerusalém; porém comiam pães ázimos no meio de seus irmãos.'),
('acf','2rs',23,10,'Também profanou a Tofete, que está no vale dos filhos de Hinom, para que ninguém fizesse passar a seu filho, ou sua filha, pelo fogo a Moloque.'),
('acf','2rs',23,11,'Também tirou os cavalos que os reis de Judá tinham dedicado ao sol, à entrada da casa do Senhor, perto da câmara de Natã-Meleque, o camareiro, que estava no recinto; e os carros do sol queimou a fogo.'),
('acf','2rs',23,12,'Também o rei derrubou os altares que estavam sobre o terraço do cenáculo de Acaz, os quais os reis de Judá tinham feito, como também o rei derrubou os altares que fizera Manassés nos dois átrios da casa do Senhor; e esmiuçados os tirou dali e lançou o pó deles no ribeiro de Cedrom.'),
('acf','2rs',23,13,'O rei profanou também os altos que estavam defronte de Jerusalém, à mão direita do monte de Masite, os quais edificara Salomão, rei de Israel, a Astarote, a abominação dos sidônios, e a Quemós, a abominação dos moabitas, e a Milcom, a abominação dos filhos de Amom.'),
('acf','2rs',23,14,'Semelhantemente quebrou as estátuas, cortou os bosques e encheu o seu lugar com ossos de homens.'),
('acf','2rs',23,15,'E também o altar que estava em Betel, e o alto que fez Jeroboão, filho de Nebate, com que tinha feito Israel pecar, esse altar derrubou juntamente com o alto; queimando o alto, em pó o esmiuçou, e queimou o ídolo do bosque.'),
('acf','2rs',23,16,'E, virando-se Josias, viu as sepulturas que estavam ali no monte; e mandou tirar os ossos das sepulturas, e os queimou sobre aquele altar, e assim o profanou, conforme a palavra do Senhor, que profetizara o homem de Deus, quando anunciou estas palavras.'),
('acf','2rs',23,17,'Então disse: Que é este monumento que vejo? E os homens da cidade lhe disseram: É a sepultura do homem de Deus que veio de Judá, e anunciou estas coisas que fizeste contra este altar de Betel.'),
('acf','2rs',23,18,'E disse: Deixai-o estar; ninguém mexa nos seus ossos. Assim deixaram estar os seus ossos com os ossos do profeta que viera de Samaria.'),
('acf','2rs',23,19,'Demais disto também Josias tirou todas as casas dos altos que havia nas cidades de Samaria, e que os reis de Israel tinham feito para provocarem à ira o Senhor; e lhes fez conforme todos os atos que tinha feito em Betel.'),
('acf','2rs',23,20,'E sacrificou todos os sacerdotes dos altos, que havia ali, sobre os altares, e queimou ossos humanos sobre eles; depois voltou a Jerusalém.'),
('acf','2rs',23,21,'O rei deu ordem a todo o povo, dizendo: Celebrai a páscoa ao Senhor vosso Deus, como está escrito no livro da aliança.'),
('acf','2rs',23,22,'Porque nunca se celebrou tal páscoa como esta desde os dias dos juízes que julgaram a Israel, nem em todos os dias dos reis de Israel, nem tampouco dos reis de Judá.'),
('acf','2rs',23,23,'Porém no ano décimo oitavo do rei Josias esta páscoa se celebrou ao Senhor em Jerusalém.'),
('acf','2rs',23,24,'E também os adivinhos, os feiticeiros, os terafins, os ídolos, e todas as abominações que se viam na terra de Judá e em Jerusalém, os extirpou Josias, para confirmar as palavras da lei, que estavam escritas no livro que o sacerdote Hilquias achara na casa do Senhor.'),
('acf','2rs',23,25,'E antes dele não houve rei semelhante, que se convertesse ao Senhor com todo o seu coração, com toda a sua alma e com todas as suas forças, conforme toda a lei de Moisés; e depois dele nunca se levantou outro tal.'),
('acf','2rs',23,26,'Todavia o Senhor não se demoveu do ardor da sua grande ira, com que ardia contra Judá, por todas as provocações com que Manassés o tinha provocado.'),
('acf','2rs',23,27,'E disse o Senhor: Também a Judá hei de tirar de diante da minha face, como tirei a Israel, e rejeitarei esta cidade de Jerusalém que escolhi, como também a casa de que disse: Estará ali o meu nome.'),
('acf','2rs',23,28,'Ora, o mais dos atos de Josias e tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',23,29,'Nos seus dias subiu Faraó Neco, rei do Egito, contra o rei da Assíria, ao rio Eufrates; e o rei Josias lhe foi ao encontro; e, vendo-o ele, o matou em Megido.'),
('acf','2rs',23,30,'E seus servos, num carro, o levaram morto, de Megido, e o trouxeram a Jerusalém, e o sepultaram na sua sepultura; e o povo da terra tomou a Jeoacaz, filho de Josias, e ungiram-no, e fizeram-no rei em lugar de seu pai.'),
('acf','2rs',23,31,'Tinha Jeoacaz vinte e três anos de idade quando começou a reinar, e três meses reinou em Jerusalém; e era o nome de sua mãe Hamutal, filha de Jeremias, de Libna.'),
('acf','2rs',23,32,'E fez o que era mau aos olhos do Senhor, conforme tudo o que fizeram seus pais.'),
('acf','2rs',23,33,'Porém Faraó Neco o mandou prender em Ribla, em terra de Hamate, para que não reinasse em Jerusalém; e à terra impôs pena de cem talentos de prata e um talento de ouro.'),
('acf','2rs',23,34,'Também Faraó Neco constituiu rei a Eliaquim, filho de Josias, em lugar de seu pai Josias, e lhe mudou o nome para Jeoiaquim; porém a Jeoacaz tomou consigo, e foi ao Egito, e morreu ali.'),
('acf','2rs',23,35,'E Jeoiaquim deu aquela prata e aquele ouro a Faraó; porém tributou a terra, para dar esse dinheiro conforme o mandado de Faraó; a cada um segundo a sua avaliação exigiu a prata e o ouro do povo da terra, para o dar a Faraó Neco.'),
('acf','2rs',23,36,'Tinha Jeoiaquim vinte e cinco anos de idade quando começou a reinar, e reinou onze anos em Jerusalém; e era o nome de sua mãe Zebida, filha de Pedaías, de Ruma.'),
('acf','2rs',23,37,'E fez o que era mau aos olhos do Senhor, conforme tudo quanto fizeram seus pais.'),
('acf','2rs',24,1,'Nos seus dias subiu Nabucodonosor, rei de babilônia, e Jeoiaquim ficou três anos seu servo; depois se virou, e se rebelou contra ele.'),
('acf','2rs',24,2,'E o Senhor enviou contra ele as tropas dos caldeus, as tropas dos sírios, as tropas dos moabitas e as tropas dos filhos de Amom; e as enviou contra Judá, para o destruir, conforme a palavra do Senhor, que falara pelo ministério de seus servos, os profetas.'),
('acf','2rs',24,3,'E, na verdade, conforme o mandado do Senhor, assim sucedeu a Judá, para o afastar da sua presença por causa dos pecados de Manassés, conforme tudo quanto fizera.'),
('acf','2rs',24,4,'Como também por causa do sangue inocente que derramou; pois encheu a Jerusalém de sangue inocente; e por isso o Senhor não quis perdoar.'),
('acf','2rs',24,5,'Ora, o mais dos atos de Jeoiaquim, e tudo quanto fez, porventura não está escrito no livro das crônicas dos reis de Judá?'),
('acf','2rs',24,6,'E Jeoiaquim dormiu com seus pais; e Joaquim, seu filho, reinou em seu lugar.'),
('acf','2rs',24,7,'E o rei do Egito nunca mais saiu da sua terra; porque o rei de babilônia tomou tudo quanto era do rei do Egito, desde o rio do Egito até ao rio Eufrates.'),
('acf','2rs',24,8,'Tinha Joaquim dezoito anos de idade quando começou a reinar, e reinou três meses em Jerusalém; e era o nome de sua mãe, Neusta, filha de Elnatã, de Jerusalém.'),
('acf','2rs',24,9,'E fez o que era mau aos olhos do Senhor, conforme tudo quanto fizera seu pai.'),
('acf','2rs',24,10,'Naquele tempo subiram os servos de Nabucodonosor, rei de babilônia, a Jerusalém; e a cidade foi cercada.'),
('acf','2rs',24,11,'Também veio Nabucodonosor, rei de babilônia, contra a cidade, quando já os seus servos a estavam sitiando.'),
('acf','2rs',24,12,'Então saiu Joaquim, rei de Judá, ao rei de babilônia, ele, sua mãe, seus servos, seus príncipes e seus oficiais; e o rei de babilônia o tomou preso, no ano oitavo do seu reinado.'),
('acf','2rs',24,13,'E tirou dali todos os tesouros da casa do Senhor e os tesouros da casa do rei; e partiu todos os vasos de ouro, que fizera Salomão, rei de Israel, no templo do Senhor, como o Senhor tinha falado.'),
('acf','2rs',24,14,'E transportou a toda a Jerusalém como também a todos os príncipes, e a todos os homens valorosos, dez mil presos, e a todos os artífices e ferreiros; ninguém ficou senão o povo pobre da terra.'),
('acf','2rs',24,15,'Assim transportou Joaquim à babilônia; como também a mãe do rei, as mulheres do rei, os seus oficiais e os poderosos da terra levou presos de Jerusalém à babilônia.'),
('acf','2rs',24,16,'E todos os homens valentes, até sete mil, e artífices e ferreiros até mil, e todos os homens destros na guerra, a estes o rei de babilônia levou presos para babilônia.'),
('acf','2rs',24,17,'E o rei de babilônia estabeleceu a Matanias, seu tio, rei em seu lugar; e lhe mudou o nome para Zedequias.'),
('acf','2rs',24,18,'Tinha Zedequias vinte e um anos de idade quando começou a reinar, e reinou onze anos em Jerusalém; e era o nome de sua mãe Hamutal, filha de Jeremias, de Libna.'),
('acf','2rs',24,19,'E fez o que era mau aos olhos do Senhor, conforme tudo quanto fizera Jeoiaquim.'),
('acf','2rs',24,20,'Porque assim sucedeu por causa da ira do SENHOR contra Jerusalém, e contra Judá, até os rejeitar de diante da sua presença; e Zedequias se rebelou contra o rei de babilônia.'),
('acf','2rs',25,1,'E sucedeu que, no nono ano do seu reinado, no mês décimo, aos dez do mês, Nabucodonosor, rei de babilônia, veio contra Jerusalém, ele e todo o seu exército, e se acampou contra ela, e levantaram contra ela trincheiras em redor.'),
('acf','2rs',25,2,'E a cidade foi sitiada até ao undécimo ano do rei Zedequias.'),
('acf','2rs',25,3,'Aos nove do mês quarto, quando a cidade se via apertada pela fome, nem havia pão para o povo da terra,'),
('acf','2rs',25,4,'Então a cidade foi invadida, e todos os homens de guerra fugiram de noite pelo caminho da porta, entre os dois muros que estavam junto ao jardim do rei (porque os caldeus estavam contra a cidade em redor), e o rei se foi pelo caminho da campina.'),
('acf','2rs',25,5,'Porém o exército dos caldeus perseguiu o rei, e o alcançou nas campinas de Jericó; e todo o seu exército se dispersou.'),
('acf','2rs',25,6,'E tomaram o rei, e o fizeram subir ao rei de babilônia, a Ribla; e foi-lhe pronunciada a sentença.'),
('acf','2rs',25,7,'E aos filhos de Zedequias mataram diante dos seus olhos; e vazaram os olhos de Zedequias, e o ataram com duas cadeias de bronze, e o levaram a babilônia.'),
('acf','2rs',25,8,'E no quinto mês, no sétimo dia do mês (este era o ano décimo nono de Nabucodonosor, rei de babilônia), veio Nebuzaradã, capitão da guarda, servo do rei de babilônia, a Jerusalém.'),
('acf','2rs',25,9,'E queimou a casa do Senhor e a casa do rei, como também todas as casas de Jerusalém, e todas as casas dos grandes queimou.'),
('acf','2rs',25,10,'E todo o exército dos caldeus, que estava com o capitão da guarda, derrubou os muros em redor de Jerusalém.'),
('acf','2rs',25,11,'E o mais do povo que deixaram ficar na cidade, os rebeldes que se renderam ao rei de babilônia e o mais da multidão, Nebuzaradã, o capitão da guarda, levou presos.'),
('acf','2rs',25,12,'Porém dos mais pobres da terra deixou o capitão da guarda ficar alguns para vinheiros e para lavradores.'),
('acf','2rs',25,13,'Quebraram mais, os caldeus, as colunas de cobre que estavam na casa do SENHOR, como também as bases e o mar de cobre que estavam na casa do SENHOR; e levaram o seu bronze para babilônia.'),
('acf','2rs',25,14,'Também tomaram as caldeiras, as pás, os apagadores, as colheres e todos os vasos de cobre, com que se ministrava.'),
('acf','2rs',25,15,'Também o capitão-da-guarda tomou os braseiros, e as bacias, o que era de ouro puro, em ouro e o que era de prata, em prata.'),
('acf','2rs',25,16,'As duas colunas, um mar, e as bases, que Salomão fizera para a casa do Senhor; o cobre de todos estes vasos não tinha peso.'),
('acf','2rs',25,17,'A altura de uma coluna era de dezoito côvados, e sobre ela havia um capitel de cobre, e de altura tinha o capitel três côvados; e a rede e as romãs em redor do capitel, tudo era de cobre; e semelhante a esta era a outra coluna com a rede.'),
('acf','2rs',25,18,'Também o capitão-da-guarda tomou a Seraías, primeiro sacerdote, e a Sofonias, segundo sacerdote, e aos três guardas do umbral da porta.'),
('acf','2rs',25,19,'E da cidade tomou a um oficial, que tinha cargo dos homens de guerra, e a cinco homens dos que estavam na presença do rei, e se achavam na cidade, como também ao escrivão-mor do exército, que registrava o povo da terra para a guerra, e a sessenta homens do povo da terra, que se achavam na cidade.'),
('acf','2rs',25,20,'E tomando-os Nebuzaradã, o capitão da guarda, os levou ao rei de babilônia, a Ribla.'),
('acf','2rs',25,21,'E o rei de babilônia os feriu e os matou em Ribla, na terra de Hamate; e Judá foi levado preso para fora da sua terra.'),
('acf','2rs',25,22,'Porém, quanto ao povo que ficara na terra de Judá, que Nabucodonosor, rei de babilônia, deixou ficar, pôs sobre ele, por governador a Gedalias, filho de Aicão, filho de Safã.'),
('acf','2rs',25,23,'Ouvindo, pois, os capitães dos exércitos, eles e os seus homens, que o rei de babilônia pusera a Gedalias por governador, vieram a Gedalias, a Mizpá, a saber: Ismael, filho de Netanias, e Joanã, filho de Careá, e Seraías, filho de Tanumete, o netofatita, e Jazanias, filho do maacatita, eles e os seus homens.'),
('acf','2rs',25,24,'E Gedalias jurou a eles e aos seus homens, e lhes disse: Não temais ser servos dos caldeus; ficai na terra, servi ao rei de babilônia, e bem vos irá.'),
('acf','2rs',25,25,'Sucedeu, porém, que, no sétimo mês, veio Ismael, filho de Netanias, o filho de Elisama, da descendência real, e dez homens com ele, e feriram a Gedalias, e ele morreu, como também aos judeus, e aos caldeus que estavam com ele em Mizpá.'),
('acf','2rs',25,26,'Então todo o povo se levantou, desde o menor até ao maior, como também os capitães dos exércitos, e foram ao Egito, porque temiam os caldeus.'),
('acf','2rs',25,27,'Depois disto sucedeu que, no ano trinta e sete do cativeiro de Joaquim, rei de Judá, no mês duodécimo, aos vinte e sete do mês, Evil-Merodaque, rei de babilônia, no ano em que reinou, levantou a cabeça de Joaquim, rei de Judá, tirando-o da casa da prisão.'),
('acf','2rs',25,28,'E lhe falou benignamente; e pôs o seu trono acima do trono dos reis que estavam com ele em babilônia.'),
('acf','2rs',25,29,'E lhe mudou as roupas de prisão, e de contínuo comeu pão na sua presença todos os dias da sua vida.'),
('acf','2rs',25,30,'E, quanto à sua subsistência, pelo rei lhe foi dada subsistência contínua, a porção de cada dia no seu dia, todos os dias da sua vida.')
insert into public.bible_verses (version, book_abbrev, chapter, verse, text) values
('acf','1cr',1,1,'Adão, Sete, Enos,'),
('acf','1cr',1,2,'Cainã, Maalaleel, Jerede,'),
('acf','1cr',1,3,'Enoque, Matusalém, Lameque,'),
('acf','1cr',1,4,'Noé, Sem, Cão e Jafé.'),
('acf','1cr',1,5,'Os filhos de Jafé foram: Gomer, Magogue, Madai, Javã, Tubal, Meseque e Tiras.'),
('acf','1cr',1,6,'E os filhos de Gomer: Asquenaz, Rifate, Togarma.'),
('acf','1cr',1,7,'E os filhos de Javã: Elisá, Társis, Quitim e Dodanim.'),
('acf','1cr',1,8,'Os filhos de Cão: Cuxe, Mizraim, Pute e Canaã.'),
('acf','1cr',1,9,'E os filhos de Cuxe eram: Sebá, Havilá, Sabtá, Raamá e Sabtecá; os filhos de Raamá: Sebá e Dedã.'),
('acf','1cr',1,10,'E Cuxe gerou a Ninrode, que começou a ser poderoso na terra.'),
('acf','1cr',1,11,'E Mizraim gerou a Ludim e a Anamim e a Leabim e a Naftuim,'),
('acf','1cr',1,12,'E a Patrusim e a Casluim (dos quais procedem os filisteus) e a Caftorim.'),
('acf','1cr',1,13,'E Canaã gerou a Sidom seu primogênito, e a Hete,'),
('acf','1cr',1,14,'E aos jebuseus e aos amorreus e aos girgaseus,'),
('acf','1cr',1,15,'E aos heveus e aos arqueus e aos sineus,'),
('acf','1cr',1,16,'E aos arvadeus e aos zemareus e aos hamateus.'),
('acf','1cr',1,17,'E foram os filhos de Sem: Elão, Assur, Arfaxade, Lude, Arã, Uz, Hul, Geter e Meseque.'),
('acf','1cr',1,18,'E Arfaxade gerou a Selá e Selá gerou a Éber.'),
('acf','1cr',1,19,'E a Éber nasceram dois filhos: o nome de um foi Pelegue, porquanto nos seus dias se repartiu a terra, e o nome de seu irmão era Joctã.'),
('acf','1cr',1,20,'E Joctã gerou a Almodá, a Selefe, a Hazarmavé, e a Jerá,'),
('acf','1cr',1,21,'E a Hadorão, a Usal, e a Dicla,'),
('acf','1cr',1,22,'E a Obal, a Abimael, a Sebá,'),
('acf','1cr',1,23,'E a Ofir, a Havilá, e a Jobabe: todos estes foram filhos de Joctã.'),
('acf','1cr',1,24,'Sem, Arfaxade, Selá,'),
('acf','1cr',1,25,'Éber, Pelegue, Reú,'),
('acf','1cr',1,26,'Serugue, Naor, Terá,'),
('acf','1cr',1,27,'Abrão, que é Abraão.'),
('acf','1cr',1,28,'Os filhos de Abraão foram: Isaque e Ismael.'),
('acf','1cr',1,29,'Estas são as suas gerações: o primogênito de Ismael foi Nebaiote, e, depois, Quedar, Adbeel, Mibsão,'),
('acf','1cr',1,30,'Misma, Dumá, Massá, Hadade, Tema,'),
('acf','1cr',1,31,'Jetur, Nafis e Quedemá; estes foram os filhos de Ismael.'),
('acf','1cr',1,32,'Quanto aos filhos de Quetura, concubina de Abraão, esta deu à luz a Zinrã, a Jocsã, a Medã, a Midiã, a Jisbaque e a Suá; e os filhos de Jocsã foram Seba e Dedã.'),
('acf','1cr',1,33,'E os filhos de Midiã: Efá, Efer, Enoque, Abida e Elda; todos estes foram filhos de Quetura.'),
('acf','1cr',1,34,'Abraão, pois, gerou a Isaque; e foram os filhos de Isaque: Esaú e Israel.'),
('acf','1cr',1,35,'Os filhos de Esaú: Elifaz, Reuel, Jeús, Jalão e Coré.'),
('acf','1cr',1,36,'Os filhos de Elifaz: Temã, Omar, Zefi, Gaetã, Quenaz, Timna e Amaleque.'),
('acf','1cr',1,37,'Os filhos de Reuel: Naate, Zerá, Samá e Mizá.'),
('acf','1cr',1,38,'E os filhos de Seir: Lotã, Sobal, Zibeão, Aná, Disom, Eser e Disã.'),
('acf','1cr',1,39,'E os filhos de Lotã: Hori e Homã; e a irmã de Lotã foi Timna.'),
('acf','1cr',1,40,'Os filhos de Sobal eram Alvã, Manaate, Ebal, Sefi e Onã; e os filhos de Zibeão eram Aiá e Aná.'),
('acf','1cr',1,41,'O filho de Aná foi Disom; e os filhos de Disom foram Hanrão, Esbã, Itrã e Querã.'),
('acf','1cr',1,42,'Os filhos de Eser eram: Bilã, Zaavã e Jaacã; os filhos de Disã eram: Uz e Arã.'),
('acf','1cr',1,43,'E estes são os reis que reinaram na terra de Edom, antes que reinasse rei sobre os filhos de Israel: Bela, filho de Beor, e era o nome da sua cidade Dinabá.'),
('acf','1cr',1,44,'E morreu Bela, e reinou em seu lugar Jobabe, filho de Zerá, de Bozra.'),
('acf','1cr',1,45,'E morreu Jobabe, e reinou em seu lugar Husão, da terra dos temanitas.'),
('acf','1cr',1,46,'E morreu Husão, e reinou em seu lugar Hadade, filho de Bedade; este feriu os midianitas no campo de Moabe; e era o nome da sua cidade Avite.'),
('acf','1cr',1,47,'E morreu Hadade, e reinou em seu lugar Samlá, de Masreca.'),
('acf','1cr',1,48,'E morreu Samlá, e reinou em seu lugar Saul, de Reobote, junto ao rio.'),
('acf','1cr',1,49,'E morreu Saul, e reinou em seu lugar Baal-Hanã, filho de Acbor.'),
('acf','1cr',1,50,'E, morrendo Baal-Hanã, Hadade reinou em seu lugar; e era o nome da sua cidade Paí; e o nome de sua mulher era Meetabel, filha de Matrede, filha de Me-Zaabe.'),
('acf','1cr',1,51,'E, morrendo Hadade, foram príncipes em Edom o príncipe Timna, o príncipe Alva, o príncipe Jetete,'),
('acf','1cr',1,52,'O príncipe Oolibama, o príncipe Elá, o príncipe Pinom,'),
('acf','1cr',1,53,'O príncipe Quenaz, o príncipe Temã, o príncipe Mibzar,'),
('acf','1cr',1,54,'O príncipe Magdiel, o príncipe Irã, estes foram os príncipes de Edom.'),
('acf','1cr',2,1,'Estes são os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar e Zebulom;'),
('acf','1cr',2,2,'Dã, José e Benjamim, Naftali, Gade e Aser.'),
('acf','1cr',2,3,'Os filhos de Judá foram Er, e Onã, e Selá, estes três lhe nasceram da filha de Suá, a cananéia; e Er, o primogênito de Judá, foi mau aos olhos do Senhor, pelo que o matou.'),
('acf','1cr',2,4,'Porém Tamar, sua nora, lhe deu à luz Perez e Zerá; todos os filhos de Judá foram cinco.'),
('acf','1cr',2,5,'Os filhos de Perez foram Hezrom e Hamul.'),
('acf','1cr',2,6,'E os filhos de Zerá: Zinri, e Etã, e Hemã, e Calcol, e Dara: cinco ao todo.'),
('acf','1cr',2,7,'E os filhos de Carmi foram Acar, o perturbador de Israel, que pecou no anátema.'),
('acf','1cr',2,8,'E o filho de Etã foi Azarias.'),
('acf','1cr',2,9,'E os filhos de Hezrom, que lhe nasceram, foram Jerameel, e Rão, e Quelubai.'),
('acf','1cr',2,10,'E Rão gerou a Aminadabe, e Aminadabe gerou a Naassom, príncipe dos filhos de Judá.'),
('acf','1cr',2,11,'E Naassom gerou a Salma, e Salma gerou a Boaz.'),
('acf','1cr',2,12,'E Boaz gerou a Obede, e Obede gerou a Jessé.'),
('acf','1cr',2,13,'E Jessé gerou a Eliabe, seu primogênito, e Abinadabe, o segundo, e Siméia, o terceiro.'),
('acf','1cr',2,14,'Natanael, o quarto, Radai, o quinto.'),
('acf','1cr',2,15,'Ozém, o sexto, Davi, o sétimo.'),
('acf','1cr',2,16,'E foram suas irmãs Zeruia e Abigail; e foram os filhos de Zeruia: Abisai e Joabe, e Asael, três.'),
('acf','1cr',2,17,'E Abigail deu à luz a Amasa; e o pai de Amasa foi Jeter, o ismaelita.'),
('acf','1cr',2,18,'E Calebe, filho de Hezrom, gerou filhos de Azuba, sua mulher, e de Jeriote; e os filhos desta foram estes: Jeser, Sobabe, e Ardom.'),
('acf','1cr',2,19,'E morreu Azuba; e Calebe tomou para si a Efrate, da qual lhe nasceu Hur.'),
('acf','1cr',2,20,'E Hur gerou a Uri, e Uri gerou a Bezaleel.'),
('acf','1cr',2,21,'Então Hezrom coabitou com a filha de Maquir, pai de Gileade, e, sendo ele de sessenta anos, a tomou; e ela deu à luz a Segube.'),
('acf','1cr',2,22,'E Segube gerou a Jair; e este tinha vinte e três cidades na terra de Gileade.'),
('acf','1cr',2,23,'E Gesur e Arã tomaram deles as aldeias de Jair, e Quenate, e seus lugares, sessenta cidades; todos estes foram filhos de Maquir, pai de Gileade.'),
('acf','1cr',2,24,'E, depois da morte de Hezrom, em Calebe de Efrata, Abia, mulher de Hezrom, deu à luz a Asur, pai de Tecoa.'),
('acf','1cr',2,25,'E os filhos de Jerameel, primogênito de Hezrom, foram Rão, o primogênito, Buna, Orem, Ozém e Aías.'),
('acf','1cr',2,26,'Teve também Jerameel ainda outra mulher cujo nome era Atara; esta foi a mãe de Onã.'),
('acf','1cr',2,27,'E foram os filhos de Rão, primogênito de Jerameel: Maaz, Jamim, e Equer.'),
('acf','1cr',2,28,'E foram os filhos de Onã: Samai e Jada; e os filhos de Samai: Nadabe e Abisur.'),
('acf','1cr',2,29,'E o nome da mulher de Abisur era Abiail, que lhe deu a Abã e a Molide.'),
('acf','1cr',2,30,'E foram os filhos de Nadabe, Selede e Apaim; e Selede morreu sem filhos.'),
('acf','1cr',2,31,'E o filho de Apaim foi Isi; e o filho de Isi, Sesã. E o filho de Sesã, Alai.'),
('acf','1cr',2,32,'E os filhos de Jada, irmão de Samai, foram Jeter e Jônatas; e Jeter morreu sem filhos.'),
('acf','1cr',2,33,'E os filhos de Jônatas foram: Pelete e Zaza; estes foram os filhos de Jerameel.'),
('acf','1cr',2,34,'E Sesã não teve filhos, mas filhas; e tinha Sesã um servo egípcio, cujo nome era Jará.'),
('acf','1cr',2,35,'Deu, pois, Sesã sua filha por mulher a Jará, seu servo; e lhe deu à luz a Atai.'),
('acf','1cr',2,36,'E Atai gerou a Natã, e Natã gerou a Zabade.'),
('acf','1cr',2,37,'E Zabade gerou a Eflal, e Eflal gerou a Obede.'),
('acf','1cr',2,38,'E Obede gerou a Jeú, e Jeú gerou a Azarias.'),
('acf','1cr',2,39,'E Azarias gerou a Helez, e Helez gerou a Eleasá.'),
('acf','1cr',2,40,'E Eleasá gerou a Sismai, e Sismai gerou a Salum.'),
('acf','1cr',2,41,'E Salum gerou a Jecamias, e Jecamias gerou a Elisama.'),
('acf','1cr',2,42,'E foram os filhos de Calebe, irmão de Jerameel, Messa, seu primogênito (este foi o pai de Zife), e os filhos de Maressa, pai de Hebrom.'),
('acf','1cr',2,43,'E foram os filhos de Hebrom: Coré, Tápua, Requém e Sema.'),
('acf','1cr',2,44,'E Sema gerou a Raão, pai de Jorqueão; e Requém gerou a Samai.'),
('acf','1cr',2,45,'E foi o filho de Samai, Maom; e Maom foi pai de Bete-Zur.'),
('acf','1cr',2,46,'E Efá, a concubina de Calebe, deu à luz a Harã, a Mosa, e a Gazez; e Harã gerou a Gazez.'),
('acf','1cr',2,47,'E foram filhos de Jadai: Regém, Jotão, Gesã, Pelete, Efá e Saafe.'),
('acf','1cr',2,48,'De Maaca, concubina, Calebe gerou a Seber e a Tiraná.'),
('acf','1cr',2,49,'E a mulher de Saafe, pai de Madmana, deu à luz a Seva, pai de Macbena e pai de Gibeá; e foi a filha de Calebe, Acsa.'),
('acf','1cr',2,50,'Estes foram os filhos de Calebe, filho de Hur, o primogênito de Efrata: Sobal, pai de Quiriate-Jearim,'),
('acf','1cr',2,51,'E Salma, pai dos belemitas, Harefe, pai de Bete-Gader.'),
('acf','1cr',2,52,'E foram os filhos de Sobal, pai de Quiriate-Jearim: Haroé e metade dos menuítas.'),
('acf','1cr',2,53,'E as famílias de Quiriate-Jearim foram os jitreus, e os puteus, e os sumateus, e os misraeus; destes saíram os zorateus, e os estaoleus.'),
('acf','1cr',2,54,'Os filhos de Salma foram Belém e os netofatitas, Atarote, Bete-Joabe, e metade dos manaatitas, e os zoritas.'),
('acf','1cr',2,55,'E as famílias dos escribas que habitavam em Jabez foram os tiratitas, os simeatitas e os sucatitas; estes são os queneus, que vieram de Hamate, pai da casa de Recabe.'),
('acf','1cr',3,1,'E estes foram os filhos de Davi, que lhe nasceram em Hebrom: o primogênito, Amnom, de Ainoã, a jizreelita; o segundo Daniel, de Abigail, a carmelita;'),
('acf','1cr',3,2,'O terceiro, Absalão, filho de Maaca, filha de Talmai, rei de Gesur; o quarto, Adonias, filho de Hagite;'),
('acf','1cr',3,3,'O quinto, Sefatias, de Abital; o sexto, Itreão, de Eglá, sua mulher.'),
('acf','1cr',3,4,'Seis filhos lhe nasceram em Hebrom, porque ali reinou sete anos e seis meses; e trinta e três anos reinou em Jerusalém.'),
('acf','1cr',3,5,'E estes lhe nasceram em Jerusalém: Siméia, e Sobabe, e Natã, e Salomão; estes quatro lhe nasceram de Bate-Sua, filha de Amiel.'),
('acf','1cr',3,6,'Nasceram-lhe mais Ibar, Elisama, Elifelete,'),
('acf','1cr',3,7,'Nogá, Nefegue, Jafia,'),
('acf','1cr',3,8,'Elisama, Eliada, e Elifelete, nove.'),
('acf','1cr',3,9,'Todos estes foram filhos de Davi, afora os filhos das concubinas e Tamar, irmã deles.'),
('acf','1cr',3,10,'E o filho de Salomão foi Roboão; de quem foi filho Abias; de quem foi filho Asa; de quem foi filho Jeosafá;'),
('acf','1cr',3,11,'De quem foi filho Jorão; de quem foi filho Acazias; de quem foi filho Joás;'),
('acf','1cr',3,12,'De quem foi filho Amazias; de quem foi filho Jotão;'),
('acf','1cr',3,13,'De quem foi filho Acaz; de quem foi filho Ezequias; de quem foi filho Manassés;'),
('acf','1cr',3,14,'De quem foi filho Amom; de quem foi filho Josias.'),
('acf','1cr',3,15,'E os filhos de Josias foram: o primogênito, Joanã: o segundo, Jeoiaquim; o terceiro, Zedequias; o quarto, Salum.'),
('acf','1cr',3,16,'E os filhos de Jeoiaquim: Jeconias, seu filho, e Zedequias, seu filho.'),
('acf','1cr',3,17,'E os filhos de Jeconias: Assir, e seu filho Sealtiel.'),
('acf','1cr',3,18,'Os filhos deste foram: Malquirão, Pedaías, Senazar, Jecamias, Hosama, e Nedabias.'),
('acf','1cr',3,19,'E os filhos de Pedaías: Zorobabel e Simei; e os filhos de Zorobabel: Mesulão, Hananias, e Selomite, sua irmã,'),
('acf','1cr',3,20,'E Hasubá, Oel, Berequias, Hasadias, Jusabe-Hesede, cinco.'),
('acf','1cr',3,21,'E os filhos de Hananias: Pelatias e Jesaías; os filhos de Refaías, os filhos de Arnã, os filhos de Obadias, e os filhos de Secanias.'),
('acf','1cr',3,22,'E o filho de Secanias foi Semaías; e os filhos de Semaías: Hatus, e Igeal, e Bariá, e Nearias, e Safate, seis.'),
('acf','1cr',3,23,'E os filhos de Nearias: Elioenai, e Ezequias, e Azricão, três.'),
('acf','1cr',3,24,'E os filhos de Elioenai; Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías, e Anani, sete.'),
('acf','1cr',4,1,'Os filhos de Judá foram: Perez, Hezrom, Carmi, Hur, e Sobal.'),
('acf','1cr',4,2,'E Reaías, filho de Sobal gerou a Jaate, e Jaate gerou a Aumai e a Laade; estas são as famílias dos zoratitas.'),
('acf','1cr',4,3,'E estes foram os filhos do pai de Etã: Jizreel, Isma e Idbas; e era o nome de sua irmã Hazelelponi.'),
('acf','1cr',4,4,'E mais Penuel, pai de Gedor, e Ezer, pai de Husá; estes foram os filhos de Hur, o primogênito de Efrata, pai de Belém.'),
('acf','1cr',4,5,'E tinha Asur, pai de Tecoa, duas mulheres: Helá e Naará.'),
('acf','1cr',4,6,'E Naará deu à luz a Auzão, e a Hefer, e a Temeni, e a Haastari; estes foram os filhos de Naará.'),
('acf','1cr',4,7,'E os filhos de Helá: Zerete, Izar e Etnã.'),
('acf','1cr',4,8,'E Coz gerou a Anube e a Zobeba e as famílias de Aarel, filho de Harum.'),
('acf','1cr',4,9,'E foi Jabez mais ilustre do que seus irmãos; e sua mãe deu-lhe o nome de Jabez, dizendo: Porquanto com dores o dei à luz.'),
('acf','1cr',4,10,'Porque Jabez invocou o Deus de Israel, dizendo: Se me abençoares muitíssimo, e meus termos ampliares, e a tua mão for comigo, e fizeres que do mal não seja afligido! E Deus lhe concedeu o que lhe tinha pedido.'),
('acf','1cr',4,11,'E Quelube, irmão de Suá, gerou a Meir; este é o pai de Estom.'),
('acf','1cr',4,12,'E Estom gerou a Bete-Rafa, a Pasea, e a Teina, pai de Ir-Naás; estes foram os homens de Reca.'),
('acf','1cr',4,13,'E foram os filhos de Quenaz: Otniel e Seraías; o filho de Otniel: Hatate.'),
('acf','1cr',4,14,'E Meonotai gerou a Ofra, e Seraías gerou a Joabe, pai dos do vale dos artífices; porque os dali eram artífices.'),
('acf','1cr',4,15,'E foram os filhos de Calebe, filho de Jefoné: Iru, Elá e Naã; e o filho de Elá: Quenaz.'),
('acf','1cr',4,16,'E os filhos de Jealelel: Zife, Zifa, Tiria e Asareel.'),
('acf','1cr',4,17,'E os filhos de Ezra: Jeter, Merede, Efer, e Jalom; e teve mais a Miriã, e Samai, e Isbá, pai de Estemoa.'),
('acf','1cr',4,18,'E sua mulher, Judia, deu à luz a Jerede, pai de Gedor, e a Héber, pai de Socó, e a Jecutiel, pai de Zanoa; e estes foram os filhos de Bitia, filha de Faraó, que Merede tomou.'),
('acf','1cr',4,19,'E foram os filhos da mulher de Hodias, irmã de Naã: Abiqueila, o garmita, Estemoa, o maacatita.'),
('acf','1cr',4,20,'E os filhos de Simeão: Amom, Rina, Bene-Hanã, e Tilom; e os filhos de Isi: Zoete e Bene-Zoete.'),
('acf','1cr',4,21,'Os filhos de Selá, filho de Judá: Er, pai de Leca, e Lada, pai de Maressa, e as famílias da casa dos que fabricavam linho fino, em casa de Asbéia.'),
('acf','1cr',4,22,'Como também Joquim, e os homens de Cozeba, e Joás, e Sarafe (que dominaram sobre os moabitas), e Jasubi-Leém; porém estas coisas já são antigas.'),
('acf','1cr',4,23,'Estes foram oleiros, e habitavam nas hortas e nos cerrados; estes ficaram ali com o rei na sua obra.'),
('acf','1cr',4,24,'Os filhos de Simeão foram Nemuel, Jamim, Jaribe, Zerá, e Saul,'),
('acf','1cr',4,25,'Cujo filho foi Salum, de quem foi filho Mibsão, de quem foi filho Misma.'),
('acf','1cr',4,26,'E os filhos de Misma foram: Hamuel, de quem foi filho Zacur, de quem foi filho Simei.'),
('acf','1cr',4,27,'E Simei teve dezesseis filhos, e seis filhas, porém seus irmãos não tiveram muitos filhos; e toda a sua família não se multiplicou tanto como as dos filhos de Judá.'),
('acf','1cr',4,28,'E habitaram em Berseba, e em Moladá, e em Hazar-Sual,'),
('acf','1cr',4,29,'E em Bila, e em Ezém, e em Tolade,'),
('acf','1cr',4,30,'E em Betuel, e em Hormá, e em Ziclague,'),
('acf','1cr',4,31,'E em Bete-Marcabote, e em Hazar-Susim, e em Bete-Biri, e em Saaraim; estas foram as suas cidades, até que Davi reinou.'),
('acf','1cr',4,32,'E foram as suas aldeias: Etã, Aim, Rimom, Toquém, e Asã, cinco cidades,'),
('acf','1cr',4,33,'E todas as suas aldeias, que estavam em redor destas cidades, até Baal. Estas foram as suas habitações e suas genealogias.'),
('acf','1cr',4,34,'Porém Mesobabe, e Janleque e Josa, filho de Amazias,'),
('acf','1cr',4,35,'E Joel, e Jeú, filho de Josibias, filho de Seraías, filho de Asiel,'),
('acf','1cr',4,36,'E Elioenai e Jaacobá, Jesoaías, Asaías, Adiel, Jesimiel, Benaias,'),
('acf','1cr',4,37,'E Ziza, filho de Sifi, filho de Alom, filho de Jedaías, filho de Sinri, filho de Semaías;'),
('acf','1cr',4,38,'Estes, registrados por seus nomes, foram príncipes nas suas famílias; e as famílias de seus pais se multiplicaram abundantemente.'),
('acf','1cr',4,39,'E chegaram até à entrada de Gedor, ao oriente do vale, a buscar pasto para os seus rebanhos.'),
('acf','1cr',4,40,'E acharam pasto fértil e terra espaçosa, e quieta, e descansada; porque os de Cão haviam habitado ali antes.'),
('acf','1cr',4,41,'Estes, pois, que estão descritos por seus nomes, vieram nos dias de Ezequias, rei de Judá, e derrubaram as tendas e habitações dos que se acharam ali, e as destruíram totalmente até o dia de hoje, e habitaram em seu lugar; porque ali havia pasto para os seus rebanhos.'),
('acf','1cr',4,42,'Também deles, dos filhos de Simeão, quinhentos homens foram às montanhas de Seir; levaram por cabeças a Pelatias, e a Nearias, e a Refaías, e a Uziel, filhos de Isi.'),
('acf','1cr',4,43,'E feriram o restante dos que escaparam dos amalequitas, e habitaram ali até o dia de hoje.'),
('acf','1cr',5,1,'Quanto aos filhos de Rúben, o primogênito de Israel (pois ele era o primogênito; mas porque profanara a cama de seu pai, deu-se a sua primogenitura aos filhos de José, filho de Israel; de modo que não foi contado, na genealogia da primogenitura,'),
('acf','1cr',5,2,'Porque Judá foi poderoso entre seus irmãos, e dele veio o soberano; porém a primogenitura foi de José).'),
('acf','1cr',5,3,'Foram, pois, os filhos de Rúben, o primogênito de Israel: Enoque, Palu, Hezrom, e Carmi.'),
('acf','1cr',5,4,'Os filhos de Joel: Semaías, seu filho; Gogue, seu filho; Simei, seu filho;'),
('acf','1cr',5,5,'Mica, seu filho; Reaías, seu filho; Baal, seu filho;'),
('acf','1cr',5,6,'Beera, seu filho, o qual Tiglate-Pilneser, rei da Assíria, levou preso; este foi príncipe dos rubenitas.'),
('acf','1cr',5,7,'Quanto a seus irmãos pelas suas famílias, quando foram postos nas genealogias, segundo as suas descendências, tiveram por chefes Jeiel e Zacarias,'),
('acf','1cr',5,8,'E Bela, filho de Azaz, filho de Sema, filho de Joel, que habitou em Aroer, até Nebo e Baal-Meom,'),
('acf','1cr',5,9,'Também habitou do lado do oriente, até à entrada do deserto, desde o rio Eufrates; porque seu gado se tinha multiplicado na terra de Gileade.'),
('acf','1cr',5,10,'E nos dias de Saul fizeram guerra aos hagarenos, que caíram pela sua mão; e eles habitaram nas suas tendas defronte de todo o lado oriental de Gileade.'),
('acf','1cr',5,11,'E os filhos de Gade habitaram defronte deles, na terra de Basã, até Salcá.'),
('acf','1cr',5,12,'Joel foi chefe, e Safã o segundo; também Janai e Safate estavam em Basã.'),
('acf','1cr',5,13,'E seus irmãos, segundo as suas casas paternas, foram: Micael, Mesulão, Seba, Jorai, Jacã, Zia, e Éber, sete.'),
('acf','1cr',5,14,'Estes foram os filhos de Abiail filho de Huri, filho de Jaroa, filho de Gileade, filho de Micael, filho de Jesisai, filho de Jado, filho de Buz;'),
('acf','1cr',5,15,'Aí, filho de Abdiel, filho de Guni, foi chefe da casa de seus pais.'),
('acf','1cr',5,16,'E habitaram em Gileade, em Basã e nos lugares da sua jurisdição; como também em todos os arrabaldes de Sarom, até aos seus termos.'),
('acf','1cr',5,17,'Todos estes foram registrados, segundo as suas genealogias, nos dias de Jotão, rei de Judá, e nos dias de Jeroboão, rei de Israel.'),
('acf','1cr',5,18,'Dos filhos de Rúben, e dos gaditas, e da meia tribo de Manassés, homens muito valentes, que traziam escudo e espada, e entesavam o arco, e eram destros na guerra; houve quarenta e quatro mil e setecentos e sessenta, que saíam à peleja.'),
('acf','1cr',5,19,'E fizeram guerra aos hagarenos, como a Jetur, e a Nafis e a Nodabe.'),
('acf','1cr',5,20,'E foram ajudados contra eles, e os hagarenos e todos quantos estavam com eles foram entregues em sua mão; porque, na peleja, clamaram a Deus que lhes deu ouvidos, porquanto confiaram nele.'),
('acf','1cr',5,21,'E levaram preso o seu gado; seus camelos, cinqüenta mil, e duzentas e cinqüenta mil ovelhas, e dois mil jumentos, e cem mil homens.'),
('acf','1cr',5,22,'Porque muitos caíram feridos, porque de Deus era a peleja; e habitaram em seu lugar, até ao cativeiro.'),
('acf','1cr',5,23,'E os filhos da meia tribo de Manassés habitaram naquela terra; multiplicaram-se desde Basã até Baal-Hermom, e Senir, e o monte de Hermom.'),
('acf','1cr',5,24,'E estes foram cabeças de suas casas paternas, a saber: Hefer, Isi, Eliel, Azriel, Jeremias, Hodavias, e Jadiel, homens valentes, homens de nome, e chefes das casas de seus pais.'),
('acf','1cr',5,25,'Porém transgrediram contra o Deus de seus pais; e se prostituíram, seguindo os deuses dos povos da terra, os quais Deus destruíra de diante deles.'),
('acf','1cr',5,26,'Por isso o Deus de Israel suscitou o espírito de Pul, rei da Assíria, e o espírito de Tiglate-Pilneser, rei da Assíria, que os levaram presos, a saber: os rubenitas e gaditas, e a meia tribo de Manassés; e os trouxeram a Hala, e a Habor, e a Hara, e ao rio de Gozã, até ao dia de hoje.'),
('acf','1cr',6,1,'Os filhos de Levi foram: Gérson, Coate e Merari,'),
('acf','1cr',6,2,'E os filhos de Coate: Anrão, e Izar, e Hebrom, e Uziel.'),
('acf','1cr',6,3,'E os filhos de Anrão: Arão, Moisés, e Miriã; e os filhos de Arão: Nadabe, Abiú, Eleazar, e Itamar.'),
('acf','1cr',6,4,'E Eleazar gerou a Finéias, e Finéias gerou a Abisua,'),
('acf','1cr',6,5,'E Abisua gerou a Buqui, e Buqui gerou a Uzi,'),
('acf','1cr',6,6,'E Uzi gerou a Zeraías, e Zeraías gerou a Meraiote.'),
('acf','1cr',6,7,'E Meraiote gerou a Amarias, e Amarias gerou a Aitube.'),
('acf','1cr',6,8,'E Aitube gerou a Zadoque, e Zadoque gerou a Aimaás,'),
('acf','1cr',6,9,'E Aimaás gerou a Azarias, e Azarias gerou a Joanã,'),
('acf','1cr',6,10,'E Joanã gerou a Azarias; e este é o que exerceu o sacerdócio na casa que Salomão tinha edificado em Jerusalém.'),
('acf','1cr',6,11,'E Azarias gerou a Amarias, e Amarias gerou a Aitube,'),
('acf','1cr',6,12,'E Aitube gerou a Zadoque, e Zadoque gerou a Salum,'),
('acf','1cr',6,13,'E Salum gerou a Hilquias, e Hilquias gerou a Azarias,'),
('acf','1cr',6,14,'E Azarias gerou a Seraías, e Seraías gerou a Jeozadaque,'),
('acf','1cr',6,15,'E Jeozadaque foi levado cativo quando o Senhor levou presos a Judá e a Jerusalém pela mão de Nabucodonosor.'),
('acf','1cr',6,16,'Os filhos de Levi foram, pois, Gérson, Coate, e Merari.'),
('acf','1cr',6,17,'E estes são os nomes dos filhos de Gérson: Libni e Simei.'),
('acf','1cr',6,18,'E os filhos de Coate: Anrão, Izar, Hebrom, e Uziel.'),
('acf','1cr',6,19,'Os filhos de Merari: Mali e Musi; estas são as famílias dos levitas, segundo seus pais.'),
('acf','1cr',6,20,'De Gérson: Libni, seu filho; Jaate, seu filho; Zima, seu filho;'),
('acf','1cr',6,21,'Joá, seu filho; Ido, seu filho; Zerá, seu filho; Jeatarai, seu filho.'),
('acf','1cr',6,22,'Os filhos de Coate foram: Aminadabe, seu filho; Coré, seu filho; Assir, seu filho;'),
('acf','1cr',6,23,'Elcana, seu filho; Ebiasafe, seu filho; Assir, seu filho;'),
('acf','1cr',6,24,'Taate, seu filho; Uriel, seu filho; Uzias, seu filho; e Saul, seu filho.'),
('acf','1cr',6,25,'E os filhos de Elcana: Amasai e Aimote.'),
('acf','1cr',6,26,'Quanto a Elcana: os filhos de Elcana foram Zofai, seu filho; e seu filho Naate.'),
('acf','1cr',6,27,'Seu filho Eliabe, seu filho Jeroão, seu filho Elcana.'),
('acf','1cr',6,28,'E os filhos de Samuel: Joel, seu primogênito, e o segundo Abias.'),
('acf','1cr',6,29,'Os filhos de Merari: Mali, seu filho Libni, seu filho Simei, seu filho Uzá.'),
('acf','1cr',6,30,'Seu filho Siméia, seu filho Hagias, seu filho Asaías.'),
('acf','1cr',6,31,'Estes são, pois, os que Davi constituiu para o ofício do canto na casa do Senhor, depois que a arca teve repouso.'),
('acf','1cr',6,32,'E ministravam diante do tabernáculo da tenda da congregação com cantares, até que Salomão edificou a casa do Senhor em Jerusalém; e estiveram, segundo o seu costume, no seu ministério.'),
('acf','1cr',6,33,'Estes são, pois, os que ali estavam com seus filhos: dos filhos dos coatitas, Hemã, o cantor, filho de Joel, filho de Samuel,'),
('acf','1cr',6,34,'Filho de Elcana, filho de Jeroão, filho de Eliel, filho de Toá,'),
('acf','1cr',6,35,'Filho de Zufe, filho de Elcana, filho de Maate, filho de Amasai,'),
('acf','1cr',6,36,'Filho de Elcana, filho de Joel, filho de Azarias, filho de Sofonias.'),
('acf','1cr',6,37,'Filho de Taate, filho de Assir, filho de Ebiasafe, filho de Coré,'),
('acf','1cr',6,38,'Filho de Isar, filho de Coate, filho de Levi, filho de Israel.'),
('acf','1cr',6,39,'E seu irmão Asafe estava à sua direita; e era Asafe filho de Berequias, filho de Siméia,'),
('acf','1cr',6,40,'Filho de Micael, filho de Baaséias, filho de Malquias,'),
('acf','1cr',6,41,'Filho de Etni, filho de Zerá, filho de Adaías,'),
('acf','1cr',6,42,'Filho de Etã, filho de Zima, filho de Simei,'),
('acf','1cr',6,43,'Filho de Jaate, filho de Gérson, filho de Levi.'),
('acf','1cr',6,44,'E seus irmãos, os filhos de Merari, estavam à esquerda; a saber: Etã, filho de Quisi, filho de Abdi, filho de Maluque,'),
('acf','1cr',6,45,'Filho de Hasabias, filho de Amazias, filho de Hilquias,'),
('acf','1cr',6,46,'Filho de Anzi, filho de Bani, filho de Semer,'),
('acf','1cr',6,47,'Filho de Mali, filho de Musi, filho de Merari, filho de Levi.'),
('acf','1cr',6,48,'E seus irmãos, os levitas, foram postos para todo o ministério do tabernáculo da casa de Deus.'),
('acf','1cr',6,49,'E Arão e seus filhos ofereceram sobre o altar do holocausto e sobre o altar do incenso, por todo o serviço do lugar santíssimo, e para fazer expiação por Israel, conforme tudo quanto Moisés, servo de Deus, tinha ordenado.'),
('acf','1cr',6,50,'E estes foram os filhos de Arão: seu filho Eleazar, seu filho Finéias, seu filho Abisua.'),
('acf','1cr',6,51,'Seu filho Buqui, seu filho Uzi, seu filho Seraías,'),
('acf','1cr',6,52,'Seu filho Meraiote, seu filho Amarias, seu filho Aitube,'),
('acf','1cr',6,53,'Seu filho Zadoque, seu filho Aimaás.'),
('acf','1cr',6,54,'E estas foram as suas habitações, segundo os seus acampamentos, nos seus termos, a saber: dos filhos de Arão, da família dos coatitas, porque a eles caiu a sorte.'),
('acf','1cr',6,55,'Deram-lhes, pois, a Hebrom, na terra de Judá, e os arrabaldes que a rodeiam.'),
('acf','1cr',6,56,'Porém o território da cidade e as suas aldeias deram a Calebe, filho de Jefoné.'),
('acf','1cr',6,57,'E aos filhos de Arão deram as cidades de refúgio: Hebrom e Libna e os seus arrabaldes, e Jatir e Estemoa e os seus arrabaldes.'),
('acf','1cr',6,58,'E Hilém, e os seus arrabaldes, Debir e os seus arrabaldes,'),
('acf','1cr',6,59,'E Asã e os seus arrabaldes, e Bete-Semes e os seus arrabaldes.'),
('acf','1cr',6,60,'E da tribo de Benjamim, Geba e os seus arrabaldes, Alemete e os seus arrabaldes, e Anatote e os seus arrabaldes; todas as suas cidades, pelas suas famílias, foram treze.'),
('acf','1cr',6,61,'Mas os filhos de Coate, que restaram da sua família, tiveram, por sorte, dez cidades da meia tribo de Manassés.'),
('acf','1cr',6,62,'E os filhos de Gérson, segundo as suas famílias, tiveram treze cidades da tribo de Issacar, e da tribo de Aser, e da tribo de Naftali e da tribo de Manassés, em Basã.'),
('acf','1cr',6,63,'Os filhos de Merari, segundo as suas famílias, tiveram, por sorte, doze cidades da tribo de Rúben, e da tribo de Gade, e da tribo de Zebulom.'),
('acf','1cr',6,64,'Assim os filhos de Israel deram aos levitas estas cidades e os seus arrabaldes.'),
('acf','1cr',6,65,'E deram-lhes por sorte estas cidades, da tribo dos filhos de Judá, da tribo dos filhos de Simeão, e da tribo dos filhos de Benjamim, às quais deram os seus nomes.'),
('acf','1cr',6,66,'E quanto ao mais das famílias dos filhos de Coate, se lhes deram, da tribo de Efraim as cidades dos seus termos.'),
('acf','1cr',6,67,'Porque lhes deram as cidades de refúgio, Siquém e os seus arrabaldes, nas montanhas de Efraim, como também Gezer e os seus arrabaldes,'),
('acf','1cr',6,68,'E Jocmeão e os seus arrabaldes, Bete-Horom e os seus arrabaldes,'),
('acf','1cr',6,69,'E Aijalom e os seus arrabaldes, Gate-Rimom e os seus arrabaldes.'),
('acf','1cr',6,70,'E da meia tribo de Manassés, Aner e os seus arrabaldes, e Bileã e os seus arrabaldes; estas cidades tiveram os que ficaram da família dos filhos de Coate.'),
('acf','1cr',6,71,'Os filhos de Gérson tiveram, da família da meia tribo de Manassés, Golã, em Basã, e os seus arrabaldes, e Astarote e os seus arrabaldes.'),
('acf','1cr',6,72,'E da tribo de Issacar, Quedes e os seus arrabaldes, e Daberate e os seus arrabaldes.'),
('acf','1cr',6,73,'E Ramote e os seus arrabaldes, e Aném e os seus arrabaldes.'),
('acf','1cr',6,74,'E da tribo de Aser, Masal e os seus arrabaldes, e Abdom e os seus arrabaldes,'),
('acf','1cr',6,75,'E Hucoque e os seus arrabaldes, e Reobe e os seus arrabaldes.'),
('acf','1cr',6,76,'E da tribo de Naftali, Quedes, em Galiléia, e os seus arrabaldes, Hamom e os seus arrabaldes e Quiriataim e os seus arrabaldes.'),
('acf','1cr',6,77,'Os que ficaram dos filhos de Merari tiveram, da tribo de Zebulom, a Rimom e os seus arrabaldes, a Tabor e os seus arrabaldes.'),
('acf','1cr',6,78,'E dalém do Jordão, na altura de Jericó, ao oriente do Jordão, da tribo de Rúben, a Bezer, no deserto, e os seus arrabaldes, e a Jaza e os seus arrabaldes,'),
('acf','1cr',6,79,'E a Quedemote e os seus arrabaldes, e a Mefaate e os seus arrabaldes.'),
('acf','1cr',6,80,'E da tribo de Gade, a Ramote, em Gileade, e os seus arrabaldes, e Maanaim e os seus arrabaldes,'),
('acf','1cr',6,81,'E a Hesbom e os seus arrabaldes, e a Jazer e os seus arrabaldes.'),
('acf','1cr',7,1,'E quanto aos filhos de Issacar, foram: Tola, Pua, Jasube e Sinrom, quatro.'),
('acf','1cr',7,2,'E os filhos de Tola foram: Uzi, Refaías, Jeriel, Jamai, Ibsão e Semuel, chefes das casas de seus pais, descendentes de Tola, homens valentes nas suas gerações; o seu número, nos dias de Davi, foi de vinte e dois mil e seiscentos.'),
('acf','1cr',7,3,'E o filho de Uzi: Izraías; e os filhos de Izraías foram: Mical, Obadias, Joel e Issias; todos estes cinco chefes.'),
('acf','1cr',7,4,'E houve com eles nas suas gerações, segundo as suas casas paternas, em tropas de guerra, trinta e seis mil; porque tiveram muitas mulheres e filhos.'),
('acf','1cr',7,5,'E seus irmãos, em todas as famílias de Issacar, homens valentes, foram oitenta e sete mil, todos contados pelas suas genealogias.'),
('acf','1cr',7,6,'Os filhos de Benjamim foram: Belá, e Bequer, e Jediael, três.'),
('acf','1cr',7,7,'E os filhos de Belá: Esbom, e Uzi, e Uziel, e Jerimote, e Iri, cinco chefes da casa dos pais, homens valentes que foram contados pelas suas genealogias, vinte e dois mil e trinta e quatro.'),
('acf','1cr',7,8,'E os filhos de Bequer: Zemira, Joás, Eliezer, Elioenai, Onri, Jerimote, Abias, Anatote, e Alemete; todos estes foram filhos de Bequer.'),
('acf','1cr',7,9,'E foram contados pelas suas genealogias, segundo as suas gerações, e chefes das casas de seus pais, homens valentes, vinte mil e duzentos.'),
('acf','1cr',7,10,'E foi o filho de Jediael, Bilã; e os filhos de Bilã foram Jeús, Benjamim, Eúde, Quenaaná, Zetã, Társis e Aisaar.'),
('acf','1cr',7,11,'Todos estes filhos de Jediael foram chefes das famílias dos pais, homens valentes, dezessete mil e duzentos, que saíam no exército à peleja.'),
('acf','1cr',7,12,'E Supim, e Hupim, filhos de Ir, e Husim, dos filhos de Aer.'),
('acf','1cr',7,13,'Os filhos de Naftali: Jaziel, e Guni, e Jezer, e Salum, filhos de Bila.'),
('acf','1cr',7,14,'Os filhos de Manassés: Asriel, que a mulher de Gileade concebeu (porém a sua concubina, a síria, concebeu a Maquir, pai de Gileade;'),
('acf','1cr',7,15,'E Maquir tomou a irmã de Hupim e Supim por mulher, e era o seu nome Maaca), e foi o nome do segundo Zelofeade; e Zelofeade teve filhas.'),
('acf','1cr',7,16,'E Maaca, mulher de Maquir, deu à luz um filho, e chamou-o Perez; e o nome de seu irmão foi Seres; e foram seus filhos Ulão e Raquém.'),
('acf','1cr',7,17,'E o filho de Ulão, Bedã; estes foram os filhos de Gileade, filho de Maquir, filho de Manassés.'),
('acf','1cr',7,18,'E quanto à sua irmã Hamolequete, teve a Is-Hode, a Abiezer, e a Maalá.'),
('acf','1cr',7,19,'E foram os filhos de Semida: Aiã, Siquém, Liqui, e Anião.'),
('acf','1cr',7,20,'E os filhos de Efraim: Sutela, e seu filho Berede, e seu filho Taate, e seu filho Elada e seu filho Taate.'),
('acf','1cr',7,21,'E seu filho Zabade, e seu filho Sutela, e Ezer, e Elade; e os homens de Gate, naturais da terra, os mataram, porque desceram para tomar os seus gados.'),
('acf','1cr',7,22,'Por isso Efraim, seu pai, por muitos dias os chorou; e vieram seus irmãos para o consolar.'),
('acf','1cr',7,23,'Depois coabitou com sua mulher, e ela concebeu, e teve um filho; e chamou-o Berias; porque ia mal na sua casa.'),
('acf','1cr',7,24,'E sua filha foi Seerá, que edificou a Bete-Horom, a baixa e a alta, como também a Uzém-Seerá.'),
('acf','1cr',7,25,'E foi seu filho Refa, e Resefe, de quem foi filho Tela, de quem foi filho Taã,'),
('acf','1cr',7,26,'De quem foi filho Ladã, de quem foi filho Amiúde, de quem foi filho Elisama,'),
('acf','1cr',7,27,'De quem foi filho Num, de quem foi filho Josué.'),
('acf','1cr',7,28,'E foi a sua possessão e habitação Betel e os lugares da sua jurisdição; e ao oriente Naarã, e ao ocidente Gezer e os lugares da sua jurisdição, e Siquém e os lugares da sua jurisdição, até Gaza e os lugares da sua jurisdição;'),
('acf','1cr',7,29,'E do lado dos filhos de Manassés, Bete-Seã e os lugares da sua jurisdição, Taanaque e os lugares da sua jurisdição, Megido e os lugares da sua jurisdição, Dor e os lugares da sua jurisdição; nestas habitaram os filhos de José, filho de Israel.'),
('acf','1cr',7,30,'Os filhos de Aser foram: Imná, Isvá, Isvi, Berias, e Sera, irmã deles.'),
('acf','1cr',7,31,'E os filhos de Berias: Héber e Malquiel; este foi o pai de Birzavite.'),
('acf','1cr',7,32,'E Héber gerou a Jaflete, e a Somer, e a Hotão, e a Suá, irmã deles.'),
('acf','1cr',7,33,'E foram os filhos de Jaflete: Pasaque, e Bimal e Asvate; estes foram os filhos de Jaflete.'),
('acf','1cr',7,34,'E os filhos de Semer: Ai, Roga, Jeubá, e Arã.'),
('acf','1cr',7,35,'E os filhos de seu irmão Helém: Zofa, e Imna, e Seles, e Amal.'),
('acf','1cr',7,36,'Os filhos de Zofa: Suá, e Harnefer, e Sual, e Beri, e Inra,'),
('acf','1cr',7,37,'Bezer, Hode, Samá, Silsa, Itrã, e Beera.'),
('acf','1cr',7,38,'E os filhos de Jeter: Jefoné, Pispa e Ara.'),
('acf','1cr',7,39,'E os filhos de Ula: Ará e Haniel e Rizia.'),
('acf','1cr',7,40,'Todos estes foram filhos de Aser, chefes das casas paternas, homens escolhidos e valentes, chefes dos príncipes, e contados nas suas genealogias, no exército para a guerra; foi seu número de vinte e seis mil homens.'),
('acf','1cr',8,1,'E Benjamim gerou a Belá, seu primogênito, a Asbel o segundo, e a Aará o terceiro,'),
('acf','1cr',8,2,'A Noá o quarto, e a Rafa o quinto.'),
('acf','1cr',8,3,'E Belá teve estes filhos: Adar, Gera, Abiúde,'),
('acf','1cr',8,4,'Abisua, Naamã, Aoá,'),
('acf','1cr',8,5,'Gera, Sefufá e Hurão.'),
('acf','1cr',8,6,'E estes foram os filhos de Eúde; que foram chefes dos pais dos moradores de Geba, e os levaram cativos a Manaate;'),
('acf','1cr',8,7,'E Naamã, e Aías e Gera; este os transportou, e gerou a Uzá e a Aiúde.'),
('acf','1cr',8,8,'E Saaraim (depois de os enviar), na terra de Moabe, gerou filhos de Husim e Baara, suas mulheres.'),
('acf','1cr',8,9,'E de Hodes, sua mulher, gerou a Jobabe, a Zíbia, a Mesa, a Malcã,'),
('acf','1cr',8,10,'A Jeuz, a Saquias e a Mirma; estes foram seus filhos, chefes dos pais.'),
('acf','1cr',8,11,'E de Husim gerou a Abitube e a Elpaal.'),
('acf','1cr',8,12,'E foram os filhos de Elpaal: Éber, Misã e Semede; este edificou a Ono e a Lode e os lugares da sua jurisdição.'),
('acf','1cr',8,13,'E Berias e Sema foram cabeças dos pais dos moradores de Aijalom; estes afugentaram os moradores de Gate.'),
('acf','1cr',8,14,'E Aiô, Sasaque, Jerimote,'),
('acf','1cr',8,15,'Zebadias, Arade, Eder,'),
('acf','1cr',8,16,'Micael, Ispa e Joa foram filhos de Berias.'),
('acf','1cr',8,17,'Zebadias, Mesulão, Hizque, Héber,'),
('acf','1cr',8,18,'Ismerai, Izlias e Jobabe, filhos de Elpaal.'),
('acf','1cr',8,19,'Jaquim, Zicri, Zabdi,'),
('acf','1cr',8,20,'Elienai, Ziletai, Eliel,'),
('acf','1cr',8,21,'Adaías, Beraías e Sinrate, filhos de Simei.'),
('acf','1cr',8,22,'E Ispã, Éber, Eliel,'),
('acf','1cr',8,23,'Abdom, Zicri, Hanã,'),
('acf','1cr',8,24,'Hananias, Elão, Antotias,'),
('acf','1cr',8,25,'E Ifdéias, e Penuel, filhos de Sasaque;'),
('acf','1cr',8,26,'E Sanserai, e Searias, e Atalias,'),
('acf','1cr',8,27,'E Jaaresias, e Elias e Zicri, filhos de Jeroão.'),
('acf','1cr',8,28,'Estes foram cabeças dos pais, segundo as suas gerações, chefes, e habitaram em Jerusalém.'),
('acf','1cr',8,29,'E em Gibeão habitou o pai de Gibeão; e era o nome de sua mulher Maaca;'),
('acf','1cr',8,30,'E seu filho primogênito, Abdom; depois Zur, e Quis, Baal, e Nadabe,'),
('acf','1cr',8,31,'E Gedor, Aiô, e Zequer,'),
('acf','1cr',8,32,'E Miclote gerou a Siméia; e também estes, defronte de seus irmãos, habitaram em Jerusalém com eles.'),
('acf','1cr',8,33,'E Ner gerou a Quis, e Quis gerou a Saul; e Saul gerou a Jônatas, a Malquisua, a Abinadabe, e a Esbaal.'),
('acf','1cr',8,34,'E o filho de Jônatas foi Meribe-Baal; e Meribe-Baal gerou a Mica.'),
('acf','1cr',8,35,'E os filhos de Mica foram: Pitom, Meleque, Tareá, e Acaz.'),
('acf','1cr',8,36,'E Acaz gerou a Jeoada; e Jeoada gerou a Alemete, e a Azmavete, e a Zinri; e Zinri gerou a Moza,'),
('acf','1cr',8,37,'E Moza gerou a Bineá, cujo filho foi Rafa, de quem foi filho Eleasá, cujo filho foi Azel.'),
('acf','1cr',8,38,'E teve Azel seis filhos, e estes foram os seus nomes: Azricão, Bocru, Ismael, Searias, Obadias, e Hanã; todos estes foram filhos de Azel.'),
('acf','1cr',8,39,'E os filhos de Ezeque, seu irmão: Ulão, seu primogênito, Jeús o segundo e Elifelete o terceiro.'),
('acf','1cr',8,40,'E foram os filhos de Ulão homens heróis, valentes, e flecheiros destros; e tiveram muitos filhos, e filhos de filhos, cento e cinqüenta; todos estes foram dos filhos de Benjamim.'),
('acf','1cr',9,1,'E todo o Israel foi contado por genealogias, que estão escritas no livro dos reis de Israel; e os de Judá foram transportados a Babilônia, por causa da sua transgressão.'),
('acf','1cr',9,2,'E os primeiros habitantes, que moravam na sua possessão e nas suas cidades, foram os israelitas, os sacerdotes, os levitas, e os netineus.'),
('acf','1cr',9,3,'Porém alguns dos filhos de Judá, e dos filhos de Benjamim, e dos filhos de Efraim e Manassés, habitaram em Jerusalém:'),
('acf','1cr',9,4,'Utai, filho de Amiúde, filho de Onri, filho de Inri, filho de Bani, dos filhos de Perez, filho de Judá;'),
('acf','1cr',9,5,'E dos silonitas: Asaías o primogênito, e seus filhos;'),
('acf','1cr',9,6,'E dos filhos de Zerá: Jeuel, e seus irmãos, seiscentos e noventa;'),
('acf','1cr',9,7,'E dos filhos de Benjamim: Salu, filho de Mesulão, filho de Hodavias, filho de Hassenua,'),
('acf','1cr',9,8,'E Ibnéias, filho de Jeroão, e Elá, filho de Uzi, filho de Micri, e Mesulão, filho de Sefatias, filho de Reuel, filho de Ibnijas;'),
('acf','1cr',9,9,'E seus irmãos, segundo as suas gerações, novecentos e cinqüenta e seis; todos estes homens foram chefes dos pais nas casas de seus pais.'),
('acf','1cr',9,10,'E dos sacerdotes: Jedaías, e Jeoiaribe, e Jaquim,'),
('acf','1cr',9,11,'E Azarias, filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, maioral da casa de Deus;'),
('acf','1cr',9,12,'Adaías, filho de Jeroão, filho de Pasur, filho de Malquias, e Masai, filho de Adiel, filho de Jazera, filho de Mesulão, filho de Mesilemite, filho de Imer;'),
('acf','1cr',9,13,'Como também seus irmãos, cabeças nas casas de seus pais, mil, setecentos e sessenta, homens valentes para a obra do ministério da casa de Deus.'),
('acf','1cr',9,14,'E dos levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, dos filhos de Merari;'),
('acf','1cr',9,15,'E Baquebacar, Heres e Galal; e Matanias, filho de Mica, filho de Zicri, filho de Asafe;'),
('acf','1cr',9,16,'E Obadias, filho de Semaías, filho de Galal, filho de Jedutum; e Berequias, filho de Asa, filho de Elcana, morador das aldeias dos netofatitas.'),
('acf','1cr',9,17,'E foram porteiros: Salum, Acube, Talmom, Aimã, e seus irmãos, cujo chefe era Salum.'),
('acf','1cr',9,18,'E até aquele tempo estavam de guarda à porta do rei, do lado do oriente; estes foram os porteiros dos arraiais dos filhos de Levi.'),
('acf','1cr',9,19,'E Salum, filho de Coré, filho de Ebiasafe, filho de Corá, e seus irmãos da casa de seu pai, os coraítas, tinham cargo da obra do ministério, e eram guardas das portas do tabernáculo, como seus pais foram responsáveis pelo arraial do Senhor, e guardas da entrada.'),
('acf','1cr',9,20,'Finéias, filho de Eleazar, antes era líder entre eles; e o Senhor era com ele.'),
('acf','1cr',9,21,'E Zacarias, filho de Meselemias, porteiro da entrada da tenda da congregação.'),
('acf','1cr',9,22,'Todos estes, escolhidos para serem guardas das portas, foram duzentos e doze; e foram estes, segundo as suas aldeias, postos em suas genealogias; e Davi e Samuel, o vidente, os constituíram nos seus respectivos cargos.'),
('acf','1cr',9,23,'Estavam, pois, eles, e seus filhos, às portas da casa do Senhor, na casa da tenda, junto aos guardas,'),
('acf','1cr',9,24,'Os porteiros estavam aos quatro lados; ao oriente, ao ocidente, ao norte, e ao sul.'),
('acf','1cr',9,25,'E seus irmãos, que estavam nas suas aldeias, deviam, de tempo em tempo, vir por sete dias para servirem com eles.'),
('acf','1cr',9,26,'Porque havia naquele ofício quatro porteiros principais que eram levitas, e tinham o encargo das câmaras e dos tesouros da casa de Deus.'),
('acf','1cr',9,27,'E de noite ficavam em redor da casa de Deus, cuja guarda lhes tinha sido confiada, e tinham o encargo de abri-la cada manhã.'),
('acf','1cr',9,28,'E alguns deles estavam encarregados dos utensílios do ministério, porque por conta os traziam e por conta os tiravam.'),
('acf','1cr',9,29,'Porque deles havia alguns que tinham o encargo dos objetos e de todos os utensílios do santuário; como também da flor de farinha, do vinho, do azeite, do incenso, e das especiarias.'),
('acf','1cr',9,30,'E alguns dos filhos dos sacerdotes eram os obreiros da confecção das especiarias.'),
('acf','1cr',9,31,'E Matitias, dentre os levitas, o primogênito de Salum, o coraíta, tinha o encargo da obra que se fazia em sertãs.'),
('acf','1cr',9,32,'E alguns dos seus irmãos, dos filhos dos coatitas, tinham o encargo de preparar os pães da proposição para todos os sábados.'),
('acf','1cr',9,33,'Destes foram também os cantores, chefes dos pais entre os levitas, habitando nas câmaras, isentos de serviços; porque de dia e de noite estava a seu cargo ocuparem-se naquela obra.'),
('acf','1cr',9,34,'Estes foram cabeças dos pais entre os levitas, chefes em suas gerações; estes habitaram em Jerusalém.'),
('acf','1cr',9,35,'Porém em Gibeão habitaram Jeiel, pai de Gibeão (e era o nome de sua mulher Maaca).'),
('acf','1cr',9,36,'E seu filho primogênito Abdom; depois Zur, Quis, Baal, Ner e Nadabe,'),
('acf','1cr',9,37,'E Gedor, Aiô, Zacarias e Miclote.'),
('acf','1cr',9,38,'Miclote gerou a Simeão; e também estes habitaram em Jerusalém, defronte de seus irmãos, com eles.'),
('acf','1cr',9,39,'E Ner gerou a Quis; e Quis gerou a Saul, Saul gerou a Jônatas, a Malquisua, a Abinadabe e a Esbaal.'),
('acf','1cr',9,40,'E o filho de Jônatas foi Meribe-Baal, e Meribe-Baal gerou a Mica.'),
('acf','1cr',9,41,'E os filhos de Mica foram: Pitom, Meleque e Taréia.'),
('acf','1cr',9,42,'E Acaz gerou a Jaerá, e Jaerá gerou a Alemete, a Azmavete e a Zinri; e Zinri gerou a Moza.'),
('acf','1cr',9,43,'E Moza gerou a Bineá, cujo filho foi Refaías, de quem foi filho Eleasá, cujo filho foi Azel.'),
('acf','1cr',9,44,'E teve Azel seis filhos, e estes foram os seus nomes: Azricão, Bocru, Ismael, Searias, Obadias e Hanã; estes foram os filhos de Azel.'),
('acf','1cr',10,1,'E os filisteus pelejaram com Israel; e os homens de Israel fugiram de diante dos filisteus, e caíram mortos nas montanhas de Gilboa.'),
('acf','1cr',10,2,'E os filisteus perseguiram a Saul e aos seus filhos e mataram a Jônatas, a Abinadabe e a Malquisua, filhos de Saul.'),
('acf','1cr',10,3,'E a peleja se agravou contra Saul, e os flecheiros o alcançaram; e temeu muito aos flecheiros.'),
('acf','1cr',10,4,'Então disse Saul ao seu escudeiro: Arranca a tua espada, e atravessa-me com ela; para que porventura não venham estes incircuncisos e escarneçam de mim. Porém o seu escudeiro não quis, porque temia muito; então tomou Saul a espada, e se lançou sobre ela.'),
('acf','1cr',10,5,'Vendo, pois, o seu escudeiro que Saul estava morto, também ele se lançou sobre a espada e morreu.'),
('acf','1cr',10,6,'Assim morreram Saul e seus três filhos; e toda a sua casa morreu juntamente.'),
('acf','1cr',10,7,'E, vendo todos os homens de Israel, que estavam no vale, que haviam fugido, e que Saul e seus filhos eram mortos, deixaram as suas cidades, e fugiram; então vieram os filisteus, e habitaram nelas.'),
('acf','1cr',10,8,'E sucedeu que, no dia seguinte, vindo os filisteus a despojar os mortos, acharam a Saul e a seus filhos estirados nas montanhas de Gilboa.'),
('acf','1cr',10,9,'E o despojaram, e tomaram a sua cabeça e as suas armas, e as enviaram pela terra dos filisteus em redor, para o anunciarem a seus ídolos e ao povo.'),
('acf','1cr',10,10,'E puseram as suas armas na casa do seu deus, e a sua cabeça afixaram na casa de Dagom.'),
('acf','1cr',10,11,'Ouvindo, pois, toda a Jabes de Gileade tudo quanto os filisteus fizeram a Saul,'),
('acf','1cr',10,12,'Então todos os homens valorosos se levantaram, e tomaram o corpo de Saul, e os corpos de seus filhos, e os trouxeram a Jabes; e sepultaram os seus ossos debaixo de um carvalho em Jabes, e jejuaram sete dias.'),
('acf','1cr',10,13,'Assim morreu Saul por causa da transgressão que cometeu contra o Senhor, por causa da palavra do Senhor, a qual não havia guardado; e também porque buscou a adivinhadora para a consultar.'),
('acf','1cr',10,14,'E não buscou ao Senhor, que por isso o matou, e transferiu o reino a Davi, filho de Jessé.'),
('acf','1cr',11,1,'Então todo o Israel se ajuntou a Davi em Hebrom, dizendo: Eis que somos teus ossos e tua carne.'),
('acf','1cr',11,2,'E também outrora, sendo Saul ainda rei, eras tu o que fazias sair e entrar a Israel; também o Senhor teu Deus te disse: Tu apascentarás o meu povo Israel, e tu serás chefe sobre o meu povo Israel.'),
('acf','1cr',11,3,'Também vieram todos os anciãos de Israel ao rei, a Hebrom, e Davi fez com eles aliança em Hebrom, perante o Senhor; e ungiram a Davi rei sobre Israel, conforme a palavra do Senhor pelo ministério de Samuel.'),
('acf','1cr',11,4,'E partiu Davi e todo o Israel para Jerusalém, que é Jebus; porque ali estavam os jebuseus, habitantes da terra.'),
('acf','1cr',11,5,'E disseram os habitantes de Jebus a Davi: Tu não entrarás aqui. Porém Davi ganhou a fortaleza de Sião, que é a cidade de Davi.'),
('acf','1cr',11,6,'Porque disse Davi: Qualquer que primeiro ferir os jebuseus será chefe e capitão. Então Joabe, filho de Zeruia, subiu primeiro a ela; pelo que foi feito chefe.'),
('acf','1cr',11,7,'E Davi habitou na fortaleza; por isso foi chamada a cidade de Davi.'),
('acf','1cr',11,8,'E edificou a cidade ao redor, desde Milo até ao circuito; e Joabe renovou o restante da cidade.'),
('acf','1cr',11,9,'E Davi tornava-se cada vez mais forte; porque o Senhor dos Exércitos era com ele.'),
('acf','1cr',11,10,'E estes foram os chefes dos poderosos que Davi tinha, e que o apoiaram fortemente no seu reino, com todo o Israel, para o fazerem rei, conforme a palavra do Senhor, no tocante a Israel.'),
('acf','1cr',11,11,'E este é o número dos poderosos que Davi tinha: Jasobeão, hacmonita, chefe dos capitães, o qual, brandindo a sua lança contra trezentos, de uma vez os matou.'),
('acf','1cr',11,12,'E, depois dele Eleazar, filho de Dodó, o aoíta; ele estava entre os três poderosos.'),
('acf','1cr',11,13,'Este esteve com Davi em Pas-Damim, quando os filisteus ali se ajuntaram à peleja, onde havia um pedaço de campo cheio de cevada; e o povo fugiu de diante dos filisteus.'),
('acf','1cr',11,14,'E puseram-se no meio daquele campo, e o defenderam, e feriram os filisteus; e o Senhor efetuou um grande livramento.'),
('acf','1cr',11,15,'E três dos trinta capitães desceram à penha, a ter com Davi, na caverna de Adulão; e o exército dos filisteus estava acampado no vale de Refaim.'),
('acf','1cr',11,16,'E Davi estava então no lugar forte; e o alojamento dos filisteus estava então em Belém.'),
('acf','1cr',11,17,'E desejou Davi, e disse: Quem me dera beber da água do poço de Belém, que está junto à porta!'),
('acf','1cr',11,18,'Então aqueles três romperam pelo acampamento dos filisteus, e tiraram água do poço de Belém, que estava junto à porta, e tomaram dela e a trouxeram a Davi; porém Davi não a quis beber, mas a derramou ao Senhor,'),
('acf','1cr',11,19,'E disse: Nunca meu Deus permita que faça tal! Beberia eu o sangue destes homens com as suas vidas? Pois com perigo das suas vidas a trouxeram. E ele não a quis beber. Isto fizeram aqueles três homens.'),
('acf','1cr',11,20,'E também Abisai, irmão de Joabe, era chefe de três, o qual, brandindo a sua lança contra trezentos, os feriu; e teve nome entre os três.'),
('acf','1cr',11,21,'Ele foi o mais ilustre dos três, pelo que foi capitão deles; porém não igualou aos primeiros três.'),
('acf','1cr',11,22,'Também Benaia, filho de Joiada, filho de um homem poderoso de Cabzeel, grande em obras; ele feriu a dois heróis de Moabe; e também desceu, e feriu um leão dentro de uma cova, no tempo da neve.'),
('acf','1cr',11,23,'Também feriu ele a um homem egípcio, homem de grande altura, de cinco côvados; e trazia o egípcio uma lança na mão, como o órgão do tecelão; mas Benaia desceu contra ele com uma vara, e arrancou a lança da mão do egípcio, e com ela o matou.'),
('acf','1cr',11,24,'Estas coisas fez Benaia, filho de Joiada; pelo que teve nome entre aqueles três poderosos.'),
('acf','1cr',11,25,'Eis que dos trinta foi ele o mais ilustre; contudo não chegou aos primeiros três; e Davi o pôs sobre os da sua guarda.'),
('acf','1cr',11,26,'E foram os poderosos dos exércitos: Asael, irmão de Joabe, El-Hanã, filho de Dodó, de Belém;'),
('acf','1cr',11,27,'Samote, o harorita; Helez, o pelonita;'),
('acf','1cr',11,28,'Ira, filho de Iques, o tecoíta; Abiezer, o anatotita;'),
('acf','1cr',11,29,'Sibecai, o husatita; Ilai, o aoíta;'),
('acf','1cr',11,30,'Maarai, o netofatita; Helede, filho de Baaná, o netofatita;'),
('acf','1cr',11,31,'Itai, filho de Ribai, de Gileade, dos filhos de Benjamim; Benaia, o piratonita;'),
('acf','1cr',11,32,'Hurai, do ribeiro de Gaás; Abiel, o arbatita;'),
('acf','1cr',11,33,'Azmavete, o baarumita; Eliabe, o saalbonita;'),
('acf','1cr',11,34,'Dos filhos de Hasém, o gizonita: Jônatas, filho de Sage, o hararita;'),
('acf','1cr',11,35,'Aião, filho de Sacar, o hararita; Elifal, filho de Ur;'),
('acf','1cr',11,36,'Hefer, o mequeratita; Aías, o pelonita;'),
('acf','1cr',11,37,'Hezro, o carmelita; Naarai, filho de Ezbai;'),
('acf','1cr',11,38,'Joel, irmão de Natã; Mibar, filho de Hagri;'),
('acf','1cr',11,39,'Zeleque, o amonita; Naarai, o beerotita, escudeiro de Joabe, filho de Zeruia;'),
('acf','1cr',11,40,'Ira, o itrita; Garebe, o itrita;'),
('acf','1cr',11,41,'Urias, o heteu; Zabade, filho de Alai;'),
('acf','1cr',11,42,'Adina, filho de Siza, o rubenita, capitão dos rubenitas, e com ele trinta;'),
('acf','1cr',11,43,'Hanã, filho de Maaca; e Josafá, o mitatita;'),
('acf','1cr',11,44,'Uzias, o asteratita; Sama e Jeiel, filhos de Hotão, o aroerita;'),
('acf','1cr',11,45,'Jediael, filho de Sinri; e Joa, seu irmão, o tizita;'),
('acf','1cr',11,46,'Eliel, o maavita; e Jeribai e Josavias, filhos de Elnaão; e Itma, o moabita;'),
('acf','1cr',11,47,'Eliel, Obede, e Jaasiel, o mesobaíta.'),
('acf','1cr',12,1,'Estes, porém, são os que vieram a Davi, a Ziclague, estando ele ainda escondido, por causa de Saul, filho de Quis; e eram dos valentes que o ajudaram na guerra.'),
('acf','1cr',12,2,'Estavam armados de arco, e usavam tanto da mão direita como da esquerda em atirar pedras e em atirar flechas com o arco; eram dos irmãos de Saul, benjamitas.'),
('acf','1cr',12,3,'Aiezer, o chefe, e Joás, filho de Semaa, o gibeatita, e Jeziel e Pelete, filhos de Azmavete; e Beraca, e Jeú, o anatotita,'),
('acf','1cr',12,4,'E Ismaías, o gibeonita, valente entre os trinta, líder deles; e Jeremias, e Jaaziel, e Joanã, e Jozabade, o gederatita,'),
('acf','1cr',12,5,'Eluzai, e Jerimote, e Bealias, e Samarias, e Sefatias, o harufita,'),
('acf','1cr',12,6,'Elcana, Issias, Azarel, Joezer, e Jasobeão, os coraítas,'),
('acf','1cr',12,7,'E Joela, e Zabadias, filhos de Jeroão de Gedor.'),
('acf','1cr',12,8,'E dos gaditas se desertaram para Davi, ao lugar forte no deserto, valentes, homens de guerra para pelejar, armados com escudo e lança; e seus rostos eram como rostos de leões, e ligeiros como corças sobre os montes:'),
('acf','1cr',12,9,'Ezer, o primeiro; Obadias, o segundo; Eliabe, o terceiro;'),
('acf','1cr',12,10,'Mismana, o quarto; Jeremias, o quinto;'),
('acf','1cr',12,11,'Atai, o sexto; Eliel, o sétimo;'),
('acf','1cr',12,12,'Joanã, o oitavo; Elzabade, o nono;'),
('acf','1cr',12,13,'Jeremias, o décimo; Macbanai, o undécimo;'),
('acf','1cr',12,14,'Estes, dos filhos de Gade, foram os capitães do exército; o menor tinha o encargo de cem homens e o maior de mil.'),
('acf','1cr',12,15,'Estes são os que passaram o Jordão no primeiro mês, quando ele transbordava por todas as suas ribanceiras, e fizeram fugir a todos os dos vales ao oriente e ao ocidente.'),
('acf','1cr',12,16,'Também alguns dos filhos de Benjamim e de Judá vieram a Davi, ao lugar forte.'),
('acf','1cr',12,17,'E Davi lhes saiu ao encontro, e lhes falou, dizendo: Se vós vindes a mim pacificamente e para me ajudar, o meu coração se unirá convosco; porém, se é para me entregar aos meus inimigos, sem que haja deslealdade nas minhas mãos, o Deus de nossos pais o veja e o repreenda.'),
('acf','1cr',12,18,'Então veio o espírito sobre Amasai, chefe de trinta, e disse: Nós somos teus, ó Davi, e contigo estamos, ó filho de Jessé! Paz, paz contigo, e paz com quem te ajuda, pois que teu Deus te ajuda. E Davi os recebeu, e os fez capitães das tropas.'),
('acf','1cr',12,19,'Também de Manassés alguns passaram para Davi, quando veio com os filisteus para a batalha contra Saul; todavia Davi não os ajudou, porque os príncipes dos filisteus, tendo feito conselho, o despediram, dizendo: À custa de nossas cabeças passará a Saul, seu senhor.'),
('acf','1cr',12,20,'Voltando ele, pois, a Ziclague, passaram-se para ele, de Manassés, Adna, Jozabade, Jediael, Micael, Jozabade, Eliú, e Ziletai, capitães de milhares dos de Manassés.'),
('acf','1cr',12,21,'E estes ajudaram a Davi contra aquela tropa, porque todos eles eram heróis poderosos, e foram capitães no exército.'),
('acf','1cr',12,22,'Porque naquele tempo, dia após dia, vinham a Davi para o ajudar, até que se fez um grande exército, como o exército de Deus.'),
('acf','1cr',12,23,'Ora este é o número dos chefes armados para a peleja, que vieram a Davi em Hebrom, para transferir a ele o reino de Saul, conforme a palavra do Senhor.'),
('acf','1cr',12,24,'Dos filhos de Judá, que traziam escudo e lança, seis mil e oitocentos, armados para a peleja;'),
('acf','1cr',12,25,'Dos filhos de Simeão, homens poderosos para pelejar, sete mil e cem;'),
('acf','1cr',12,26,'Dos filhos de Levi, quatro mil e seiscentos.'),
('acf','1cr',12,27,'Joiada, que era o líder dos de Arão, e com ele três mil e setecentos.'),
('acf','1cr',12,28,'E Zadoque, sendo ainda jovem, homem poderoso, com vinte e dois capitães da família de seu pai;'),
('acf','1cr',12,29,'E dos filhos de Benjamim, irmãos de Saul, três mil; porque até então havia ainda muitos deles que eram pela casa de Saul.'),
('acf','1cr',12,30,'E dos filhos de Efraim, vinte mil e oitocentos homens poderosos, homens de nome nas casas de seus pais.'),
('acf','1cr',12,31,'E da meia tribo de Manassés, dezoito mil, que foram apontados pelos seus nomes para virem fazer rei a Davi.'),
('acf','1cr',12,32,'E dos filhos de Issacar, duzentos de seus chefes, destros na ciência dos tempos, para saberem o que Israel devia fazer, e todos os seus irmãos seguiam suas ordens.'),
('acf','1cr',12,33,'De Zebulom, dos que podiam sair no exército, cinqüenta mil ordenados para a peleja com todas as armas de guerra; como também destros para ordenarem uma batalha, e não eram de coração dobre.'),
('acf','1cr',12,34,'E de Naftali, mil capitães, e com eles trinta e sete mil com escudo e lança.'),
('acf','1cr',12,35,'E dos danitas, ordenados para a peleja, vinte e oito mil e seiscentos.'),
('acf','1cr',12,36,'E de Aser, dos que podiam sair no exército, para ordenarem a batalha, quarenta mil.'),
('acf','1cr',12,37,'E do outro lado do Jordão, dos rubenitas e gaditas, e da meia tribo de Manassés, com toda a sorte de instrumentos de guerra para pelejar, cento e vinte mil.'),
('acf','1cr',12,38,'Todos estes homens de guerra, postos em ordem de batalha, vieram a Hebrom, com corações decididos, para constituírem a Davi rei sobre todo o Israel; e também todo o restante de Israel tinha o mesmo coração para constituir a Davi rei.'),
('acf','1cr',12,39,'E estiveram ali com Davi três dias, comendo e bebendo; porque seus irmãos lhes tinham preparado as provisões.'),
('acf','1cr',12,40,'E também seus vizinhos de mais perto, até Issacar, e Zebulom, e Naftali, trouxeram, sobre jumentos, e sobre camelos, e sobre mulos, e sobre bois, pão, provisões de farinha, pastas de figos e cachos de passas, e vinho, e azeite, e bois, gado miúdo em abundância; porque havia alegria em Israel.'),
('acf','1cr',13,1,'E Davi tomou conselho com os capitães dos milhares, e das centenas, e com todos os líderes.'),
('acf','1cr',13,2,'E disse Davi a toda a congregação de Israel: Se bem vos parece, e se isto vem do Senhor nosso Deus, enviemos depressa mensageiros a todos os nossos outros irmãos em todas as terras de Israel, e aos sacerdotes, e aos levitas nas suas cidades e nos seus arrabaldes, para que se reúnam conosco;'),
('acf','1cr',13,3,'E tornemos a trazer para nós a arca do nosso Deus; porque não a buscamos nos dias de Saul.'),
('acf','1cr',13,4,'Então disse toda a congregação que se fizesse assim; porque este negócio pareceu reto aos olhos de todo o povo.'),
('acf','1cr',13,5,'Convocou, pois, Davi a todo o Israel desde Sior do Egito até chegar a Hamate; para trazer a arca de Deus de Quiriate-Jearim.'),
('acf','1cr',13,6,'E então Davi com todo o Israel subiu a Baalá de Quiriate-Jearim, que está em Judá, para fazer subir dali a arca de Deus, o Senhor que habita entre os querubins, sobre a qual é invocado o seu nome.'),
('acf','1cr',13,7,'E levaram a arca de Deus, da casa de Abinadabe, sobre um carro novo; e Uzá e Aiô guiavam o carro.'),
('acf','1cr',13,8,'E Davi e todo o Israel, alegraram-se perante Deus com todas as suas forças; com cânticos, e com harpas, e com saltérios, e com tamborins, e com címbalos, e com trombetas.'),
('acf','1cr',13,9,'E, chegando à eira de Quidom, estendeu Uzá a sua mão, para segurar a arca, porque os bois tropeçavam.'),
('acf','1cr',13,10,'Então se acendeu a ira do Senhor contra Uzá, e o feriu, por ter estendido a sua mão à arca; e morreu ali perante Deus.'),
('acf','1cr',13,11,'E Davi se encheu de tristeza porque o Senhor havia aberto brecha em Uzá; pelo que chamou aquele lugar Perez-Uzá, até ao dia de hoje.'),
('acf','1cr',13,12,'E aquele dia temeu Davi a Deus, dizendo: Como trarei a mim a arca de Deus?'),
('acf','1cr',13,13,'Por isso Davi não trouxe a arca a si, à cidade de Davi; porém a fez levar à casa de Obede-Edom, o giteu.'),
('acf','1cr',13,14,'Assim ficou a arca de Deus com a família de Obede-Edom, três meses em sua casa; e o Senhor abençoou a casa de Obede-Edom, e tudo quanto tinha.'),
('acf','1cr',14,1,'Então Hirão, rei de Tiro, mandou mensageiros a Davi, e madeira de cedro, e pedreiros, e carpinteiros, para lhe edificarem uma casa.'),
('acf','1cr',14,2,'E entendeu Davi que o Senhor o tinha confirmado rei sobre Israel; porque o seu reino tinha sido muito exaltado por amor do seu povo Israel.'),
('acf','1cr',14,3,'E Davi tomou ainda mais mulheres em Jerusalém; e gerou Davi ainda mais filhos e filhas.'),
('acf','1cr',14,4,'E estes são os nomes dos filhos que teve em Jerusalém: Samua, Sobabe, Natã, Salomão,'),
('acf','1cr',14,5,'E Ibar, Elisua, Elpelete,'),
('acf','1cr',14,6,'E Nogá, Nefegue, Jafia,'),
('acf','1cr',14,7,'E Elisama, Eliada, e Elifelete.'),
('acf','1cr',14,8,'Ouvindo, pois, os filisteus que Davi havia sido ungido rei sobre todo o Israel, todos os filisteus subiram em busca de Davi; o que ouvindo Davi, logo saiu contra eles.'),
('acf','1cr',14,9,'E vindo os filisteus, se estenderam pelo vale de Refaim.'),
('acf','1cr',14,10,'Então consultou Davi a Deus, dizendo: Subirei contra os filisteus, e nas minhas mãos os entregarás? E o Senhor lhe disse: Sobe, porque os entregarei nas tuas mãos.'),
('acf','1cr',14,11,'E, subindo a Baal-Perazim, Davi ali os feriu; e disse Davi: Por minha mão Deus derrotou a meus inimigos, como se rompem as águas. Pelo que chamaram aquele lugar, Baal-Perazim.'),
('acf','1cr',14,12,'E deixaram ali seus deuses; e ordenou Davi que se queimassem a fogo;'),
('acf','1cr',14,13,'Porém os filisteus tornaram, e se estenderam pelo vale.'),
('acf','1cr',14,14,'E tornou Davi a consultar a Deus; e disse-lhe Deus: Não subirás atrás deles; mas rodeia-os por detrás, e vem a eles por defronte das amoreiras;'),
('acf','1cr',14,15,'E há de ser que, ouvindo tu um ruído de marcha pelas copas das amoreiras, então sairás à peleja; porque Deus terá saído diante de ti, para ferir o exército dos filisteus.'),
('acf','1cr',14,16,'E fez Davi como Deus lhe ordenara; e feriram o exército dos filisteus desde Gibeom até Gezer.'),
('acf','1cr',14,17,'Assim se espalhou o nome de Davi por todas aquelas terras; e o Senhor pôs o temor dele sobre todas aquelas nações.'),
('acf','1cr',15,1,'Davi também fez casa para si na cidade de Davi; e preparou um lugar para a arca de Deus, e armou-lhe uma tenda.'),
('acf','1cr',15,2,'Então disse Davi: Ninguém pode levar a arca de Deus, senão os levitas; porque o Senhor os escolheu, para levar a arca de Deus, e para o servirem eternamente.'),
('acf','1cr',15,3,'E Davi convocou a todo o Israel em Jerusalém, para fazer subir a arca do Senhor ao seu lugar, que lhe tinha preparado.'),
('acf','1cr',15,4,'E Davi reuniu os filhos de Arão e os levitas:'),
('acf','1cr',15,5,'Dos filhos de Coate: Uriel, o chefe, e de seus irmãos cento e vinte.'),
('acf','1cr',15,6,'Dos filhos de Merari: Asaías, o chefe, e de seus irmãos duzentos e vinte.'),
('acf','1cr',15,7,'Dos filhos de Gérson: Joel, o chefe, e de seus irmãos cento e trinta.'),
('acf','1cr',15,8,'Dos filhos de Elizafã: Semaías, o chefe, e de seus irmãos duzentos.'),
('acf','1cr',15,9,'Dos filhos de Hebrom: Eliel, o chefe, e de seus irmãos oitenta.'),
('acf','1cr',15,10,'Dos filhos de Uziel: Aminadabe, o chefe, e de seus irmãos cento e doze.'),
('acf','1cr',15,11,'E chamou Davi os sacerdotes Zadoque e Abiatar, e os levitas, Uriel, Asaías, Joel, Semaías, Eliel, e Aminadabe.'),
('acf','1cr',15,12,'E disse-lhes: Vós sois os chefes dos pais entre os levitas; santificai-vos, vós e vossos irmãos, para que façais subir a arca do Senhor Deus de Israel, ao lugar que lhe tenho preparado.'),
('acf','1cr',15,13,'Porquanto vós não a levastes na primeira vez, o Senhor nosso Deus fez rotura em nós, porque não o buscamos segundo a ordenança.'),
('acf','1cr',15,14,'Santificaram-se, pois, os sacerdotes e os levitas, para fazerem subir a arca do Senhor Deus de Israel.'),
('acf','1cr',15,15,'E os filhos dos levitas trouxeram a arca de Deus sobre os seus ombros, pelas varas que nela havia, como Moisés tinha ordenado conforme a palavra do Senhor.'),
('acf','1cr',15,16,'E disse Davi aos chefes dos levitas que constituíssem, de seus irmãos, cantores, para que com instrumentos musicais, com alaúdes, harpas e címbalos, se fizessem ouvir, levantando a voz com alegria.'),
('acf','1cr',15,17,'Designaram, pois, os levitas a Hemã, filho de Joel; e dos seus irmãos, Asafe, filho de Berequias; e dos filhos de Merari, seus irmãos, Etã, filho de Cusaías.'),
('acf','1cr',15,18,'E com eles a seus irmãos da segunda ordem: a Zacarias, Bene, Jaaziel, Semiramote, Jeiel, Uni, Eliabe, Benaia, Maaséias, Matitias, Elifeleu, Micnéias, Obede-Edom, e Jeiel, os porteiros.'),
('acf','1cr',15,19,'E os cantores, Hemã, Asafe e Etã, se faziam ouvir com címbalos de metal;'),
('acf','1cr',15,20,'E Zacarias, Aziel, Semiramote, Jeiel, Uni, Eliabe, Maaséias, e Benaia, com alaúdes, sobre Alamote:'),
('acf','1cr',15,21,'E Matitias, Elifeleu, Micnéias, Obede-Edom, Jeiel, e Azazias, com harpas, sobre Seminite, para sobressaírem.'),
('acf','1cr',15,22,'E Quenanias, chefe dos levitas, tinha o encargo de dirigir o canto; ensinava-os a entoá-lo, porque era entendido.'),
('acf','1cr',15,23,'E Berequias e Elcana eram porteiros da arca.'),
('acf','1cr',15,24,'E Sebanias, Jeosafá, Netanel, Amasai, Zacarias, Benaia, e Eliezer, os sacerdotes, tocavam as trombetas perante a arca de Deus; e Obede-Edom e Jeías eram porteiros da arca.'),
('acf','1cr',15,25,'Sucedeu, pois, que Davi e os anciãos de Israel, e os capitães dos milhares, foram, com alegria, para fazer subir a arca da aliança do Senhor, da casa de Obede-Edom.'),
('acf','1cr',15,26,'E sucedeu que, ajudando Deus os levitas que levavam a arca da aliança do Senhor, sacrificaram sete novilhos e sete carneiros.'),
('acf','1cr',15,27,'E Davi ia vestido de um manto de linho fino, como também todos os levitas que levavam a arca, e os cantores, e Quenanias, mestre dos cantores; também Davi levava sobre si um éfode de linho,'),
('acf','1cr',15,28,'E todo o Israel fez subir a arca da aliança do Senhor, com júbilo, e ao som de buzinas, e de trombetas, e de címbalos, fazendo ressoar alaúdes e harpas.'),
('acf','1cr',15,29,'E sucedeu que, chegando a arca da aliança do Senhor à cidade de Davi, Mical, a filha de Saul, olhou de uma janela, e, vendo a Davi dançar e tocar, o desprezou no seu coração.'),
('acf','1cr',16,1,'Trouxeram, pois, a arca de Deus, e a puseram no meio da tenda que Davi lhe tinha armado; e ofereceram holocaustos e sacrifícios pacíficos perante Deus.'),
('acf','1cr',16,2,'E, acabando Davi de oferecer os holocaustos e sacrifícios pacíficos, abençoou o povo em nome do Senhor.'),
('acf','1cr',16,3,'E repartiu a todos em Israel, tanto a homens como a mulheres, a cada um, um pão, e um bom pedaço de carne, e um frasco de vinho.'),
('acf','1cr',16,4,'E pôs alguns dos levitas por ministros perante a arca do Senhor; isto para recordarem, e louvarem, e celebrarem ao Senhor Deus de Israel.'),
('acf','1cr',16,5,'Era Asafe, o chefe, e Zacarias o segundo depois dele; Jeiel, e Semiramote, e Jeiel, e Matitias, e Eliabe, e Benaia, e Obede-Edom, e Jeiel, com alaúdes e com harpas; e Asafe se fazia ouvir com címbalos;'),
('acf','1cr',16,6,'Também Benaia, e Jaaziel, os sacerdotes, continuamente tocavam trombetas, perante a arca da aliança de Deus.'),
('acf','1cr',16,7,'Então naquele mesmo dia Davi, em primeiro lugar, deu o seguinte salmo para que, pelo ministério de Asafe e de seus irmãos, louvassem ao Senhor;'),
('acf','1cr',16,8,'Louvai ao Senhor, invocai o seu nome, fazei conhecidas as suas obras entre os povos.'),
('acf','1cr',16,9,'Cantai-lhe, salmodiai-lhe, atentamente falai de todas as suas maravilhas.'),
('acf','1cr',16,10,'Gloriai-vos no seu santo nome; alegre-se o coração dos que buscam ao Senhor.'),
('acf','1cr',16,11,'Buscai ao Senhor e a sua força; buscai a sua face continuamente.'),
('acf','1cr',16,12,'Lembrai-vos das maravilhas que fez, de seus prodígios, e dos juízos da sua boca;'),
('acf','1cr',16,13,'Vós, semente de Israel, seus servos, vós, filhos de Jacó, seus escolhidos.'),
('acf','1cr',16,14,'Ele é o Senhor nosso Deus; os seus juízos estão em toda a terra.'),
('acf','1cr',16,15,'Lembrai-vos perpetuamente da sua aliança e da palavra que prescreveu para mil gerações;'),
('acf','1cr',16,16,'Da aliança que fez com Abraão, e do seu juramento a Isaque;'),
('acf','1cr',16,17,'O qual também a Jacó confirmou por estatuto, e a Israel por aliança eterna,'),
('acf','1cr',16,18,'Dizendo: A ti te darei a terra de Canaã, quinhão da vossa herança.'),
('acf','1cr',16,19,'Quando eram poucos homens em número, sim, mui poucos, e estrangeiros nela,'),
('acf','1cr',16,20,'Quando andavam de nação em nação, e de um reino para outro povo,'),
('acf','1cr',16,21,'A ninguém permitiu que os oprimisse, e por amor deles repreendeu reis, dizendo:'),
('acf','1cr',16,22,'Não toqueis os meus ungidos, e aos meus profetas não façais mal.'),
('acf','1cr',16,23,'Cantai ao Senhor em toda a terra; anunciai de dia em dia a sua salvação.'),
('acf','1cr',16,24,'Contai entre as nações a sua glória, entre todos os povos as suas maravilhas.'),
('acf','1cr',16,25,'Porque grande é o Senhor, e mui digno de louvor, e mais temível é do que todos os deuses.'),
('acf','1cr',16,26,'Porque todos os deuses dos povos são ídolos; porém o Senhor fez os céus.'),
('acf','1cr',16,27,'Louvor e majestade há diante dele, força e alegria no seu lugar.'),
('acf','1cr',16,28,'Tributai ao Senhor, ó famílias dos povos, tributai ao Senhor glória e força.'),
('acf','1cr',16,29,'Tributai ao Senhor a glória de seu nome; trazei presentes, e vinde perante ele; adorai ao Senhor na beleza da sua santidade.'),
('acf','1cr',16,30,'Trema perante ele, trema toda a terra; pois o mundo se firmará, para que não se abale.'),
('acf','1cr',16,31,'Alegrem-se os céus, e regozije-se a terra; e diga-se entre as nações: O Senhor reina.'),
('acf','1cr',16,32,'Brame o mar com a sua plenitude; exulte o campo com tudo o que nele há;'),
('acf','1cr',16,33,'Então jubilarão as árvores dos bosques perante o Senhor; porquanto vem julgar a terra.'),
('acf','1cr',16,34,'Louvai ao Senhor, porque é bom; pois a sua benignidade dura perpetuamente.'),
('acf','1cr',16,35,'E dizei: Salva-nos, ó Deus da nossa salvação, e ajunta-nos, e livra-nos das nações, para que louvemos o teu santo nome, e nos gloriemos no teu louvor.'),
('acf','1cr',16,36,'Bendito seja o Senhor Deus de Israel, de eternidade a eternidade. E todo o povo disse: Amém! E louvou ao Senhor.'),
('acf','1cr',16,37,'Então Davi deixou ali, diante da arca da aliança do Senhor, a Asafe e a seus irmãos, para ministrarem continuamente perante a arca, segundo se ordenara para cada dia.'),
('acf','1cr',16,38,'E mais a Obede-Edom, com seus irmãos, sessenta e oito; a este Obede-Edom, filho de Jedutum, e a Hosa, deixou por porteiros.'),
('acf','1cr',16,39,'E deixou a Zadoque, o sacerdote, e a seus irmãos, os sacerdotes, diante do tabernáculo do Senhor, no alto que está em Gibeom,'),
('acf','1cr',16,40,'Para oferecerem holocaustos ao Senhor continuamente, pela manhã e à tarde, sobre o altar dos holocaustos; e isto segundo tudo o que está escrito na lei do Senhor que tinha prescrito a Israel.'),
('acf','1cr',16,41,'E com eles a Hemã, e a Jedutum, e aos mais escolhidos, que foram apontados pelos seus nomes, para louvarem ao Senhor, porque a sua benignidade dura perpetuamente.'),
('acf','1cr',16,42,'Com eles, pois, estavam Hemã e Jedutum, com trombetas e címbalos, para os que haviam de tocar, e com outros instrumentos de música de Deus; porém os filhos de Jedutum estavam à porta.'),
('acf','1cr',16,43,'Então todo o povo se retirou, cada um para a sua casa; e voltou Davi, para abençoar a sua casa.'),
('acf','1cr',17,1,'Sucedeu, pois, que, morando Davi já em sua casa, disse ao profeta Natã: Eis que moro em casa de cedro, mas a arca da aliança do SENHOR está debaixo de cortinas.'),
('acf','1cr',17,2,'Então Natã disse a Davi: Tudo quanto tens no teu coração faze, porque Deus é contigo.'),
('acf','1cr',17,3,'Mas sucedeu, na mesma noite, que a palavra de Deus veio a Natã, dizendo:'),
('acf','1cr',17,4,'Vai, e dize a Davi meu servo: Assim diz o Senhor: Tu não me edificarás uma casa para eu morar;'),
('acf','1cr',17,5,'Porque em casa nenhuma morei, desde o dia em que fiz subir a Israel até ao dia de hoje; mas fui de tenda em tenda, e de tabernáculo em tabernáculo.'),
('acf','1cr',17,6,'Por todas as partes por onde andei com todo o Israel, porventura falei alguma palavra a algum dos juízes de Israel, a quem ordenei que apascentasse o meu povo, dizendo: Por que não me edificais uma casa de cedro?'),
('acf','1cr',17,7,'Agora, pois, assim dirás a meu servo Davi: Assim diz o Senhor dos Exércitos: Eu te tirei do curral, de detrás das ovelhas, para que fosses chefe do meu povo Israel.'),
('acf','1cr',17,8,'E estive contigo por toda a parte, por onde foste, e de diante de ti exterminei todos os teus inimigos, e te fiz um nome como o nome dos grandes que estão na terra,'),
('acf','1cr',17,9,'E ordenarei um lugar para o meu povo Israel, e o plantarei, para que habite no seu lugar, e nunca mais seja removido de uma para outra parte; e nunca mais os filhos da perversidade o debilitarão como dantes,'),
('acf','1cr',17,10,'E desde os dias em que ordenei juízes sobre o meu povo Israel. Assim abaterei a todos os teus inimigos; também te faço saber que o Senhor te edificará uma casa.'),
('acf','1cr',17,11,'E há de ser que, quando forem cumpridos os teus dias, para ires a teus pais, suscitarei a tua descendência depois de ti, um dos teus filhos, e estabelecerei o seu reino.'),
('acf','1cr',17,12,'Este me edificará casa; e eu confirmarei o seu trono para sempre.'),
('acf','1cr',17,13,'Eu lhe serei por pai, e ele me será por filho; e a minha benignidade não retirarei dele, como a tirei daquele, que foi antes de ti.'),
('acf','1cr',17,14,'Mas o confirmarei na minha casa e no meu reino para sempre, e o seu trono será firme para sempre.'),
('acf','1cr',17,15,'Conforme todas estas palavras, e conforme toda esta visão, assim falou Natã a Davi.'),
('acf','1cr',17,16,'Então entrou o rei Davi, e ficou perante o Senhor; e disse: Quem sou eu, Senhor Deus? e qual é a minha casa, para que me tenhas trazido até aqui?'),
('acf','1cr',17,17,'E ainda isto, ó Deus, foi pouco aos teus olhos; pelo que falaste da casa de teu servo para tempos distantes; e trataste-me como a um homem ilustre, ó Senhor Deus.'),
('acf','1cr',17,18,'Que mais te dirá Davi, acerca da honra feita a teu servo? Porém tu conheces bem a teu servo.'),
('acf','1cr',17,19,'Ó Senhor, por amor de teu servo, e segundo o teu coração, fizeste toda esta grandeza, para fazer notória todas estas grandes coisas.'),
('acf','1cr',17,20,'Senhor, ninguém há como tu, e não há Deus fora de ti, segundo tudo quanto ouvimos com os nossos ouvidos.'),
('acf','1cr',17,21,'E quem há como o teu povo Israel, única gente na terra, a quem Deus foi resgatar para seu povo, fazendo-te nome com coisas grandes e temerosas, lançando as nações de diante do teu povo, que resgataste do Egito?'),
('acf','1cr',17,22,'E confirmaste o teu povo Israel para ser teu povo para sempre; e tu, Senhor, lhe foste por Deus.'),
('acf','1cr',17,23,'Agora, pois, Senhor, a palavra que falaste de teu servo, e acerca da sua casa, confirma-a para sempre; e faze como falaste.'),
('acf','1cr',17,24,'Confirme-se e engrandeça-se o teu nome para sempre, e diga-se: O Senhor dos Exércitos é o Deus de Israel, é Deus para Israel; e permaneça firme diante de ti a casa de Davi, teu servo.'),
('acf','1cr',17,25,'Porque tu, Deus meu, revelaste ao ouvido de teu servo que lhe edificarias casa; pelo que o teu servo achou confiança para orar em tua presença.'),
('acf','1cr',17,26,'Agora, pois, Senhor, tu és o mesmo Deus, e falaste este bem acerca de teu servo.'),
('acf','1cr',17,27,'Agora, pois, foste servido abençoar a casa de teu servo, para que permaneça para sempre diante de ti: porque tu, Senhor, a abençoaste, e ficará abençoada para sempre.'),
('acf','1cr',18,1,'E depois disto aconteceu que Davi derrotou os filisteus, e os sujeitou; e tomou a Gate, e os lugares da sua jurisdição, da mão dos filisteus.'),
('acf','1cr',18,2,'Também derrotou os moabitas; e os moabitas ficaram por servos de Davi, pagando tributos.'),
('acf','1cr',18,3,'Também Davi derrotou a Hadar-Ezer, rei de Zobá, junto a Hamate, quando ele ia estabelecer o seu domínio sobre o rio Eufrates.'),
('acf','1cr',18,4,'E Davi lhe tomou mil carros, e sete mil cavaleiros, e vinte mil homens de pé; e Davi jarretou todos os cavalos dos carros; porém reservou deles para cem carros.'),
('acf','1cr',18,5,'E vieram os sírios de Damasco a socorrer a Hadar-Ezer, rei de Zobá; porém Davi feriu dos sírios vinte e dois mil homens.'),
('acf','1cr',18,6,'E Davi pôs guarnições na Síria de Damasco, e os sírios ficaram por servos de Davi, pagando-lhe tributo; e o Senhor guardava a Davi, por onde quer que ia.'),
('acf','1cr',18,7,'E Davi tomou os escudos de ouro, que tinham os servos de Hadar-Ezer, e os trouxe a Jerusalém.'),
('acf','1cr',18,8,'Também de Tibate, e de Cum, cidades de Hadar-Ezer, tomou Davi muitíssimo cobre, de que Salomão fez o mar de cobre, e as colunas, e os utensílios de cobre.'),
('acf','1cr',18,9,'E ouvindo Toí, rei de Hamate, que Davi destruíra todo o exército de Hadar-Ezer, rei de Zobá,'),
('acf','1cr',18,10,'Mandou seu filho Hadorão a Davi, para lhe perguntar como estava, e para o abençoar, por haver pelejado contra Hadar-Ezer, e por havê-lo ferido (porque Hadar-Ezer fazia guerra a Toí), enviando-lhe também toda a sorte de vasos de ouro, e de prata, e de cobre.'),
('acf','1cr',18,11,'Os quais Davi também consagrou ao Senhor, juntamente com a prata e ouro que trouxera de todas as demais nações: dos edomeus, e dos moabitas, e dos filhos de Amom, e dos filisteus, e dos amalequitas.'),
('acf','1cr',18,12,'Também Abisai, filho de Zeruia, feriu a dezoito mil edomeus no Vale do Sal.'),
('acf','1cr',18,13,'E pôs guarnições em Edom, e todos os edomeus ficaram por servos de Davi; e o Senhor guardava a Davi, por onde quer que ia.'),
('acf','1cr',18,14,'E Davi reinou sobre todo o Israel; e fazia juízo e justiça a todo o seu povo.'),
('acf','1cr',18,15,'E Joabe, filho de Zeruia, comandava o exército; Jeosafá, filho de Ailude, era cronista.'),
('acf','1cr',18,16,'E Zadoque, filho de Aitube, e Abimeleque, filho de Abiatar, eram sacerdotes; e Savsa escrivão.'),
('acf','1cr',18,17,'E Benaia, filho de Joiada, estava sobre os quereteus e peleteus; porém os filhos de Davi eram os primeiros junto ao rei.'),
('acf','1cr',19,1,'E aconteceu, depois disto que Naás, rei dos filhos de Amom, morreu; e seu filho reinou em seu lugar.'),
('acf','1cr',19,2,'Então disse Davi: Usarei de benevolência com Hanum, filho de Naás, porque seu pai usou de benevolência comigo. Por isso Davi enviou mensageiros para o consolarem acerca de seu pai. E, chegando os servos de Davi à terra dos filhos de Amom, a Hanum, para o consolarem,'),
('acf','1cr',19,3,'Disseram os príncipes dos filhos de Amom a Hanum: Pensas porventura, que foi para honrar teu pai aos teus olhos, que Davi te mandou consoladores? Não vieram seus servos a ti, a esquadrinhar, e a transtornar, e a espiar a terra?'),
('acf','1cr',19,4,'Por isso Hanum tomou os servos de Davi, e raspou-os, e cortou-lhes as vestes no meio até à coxa da perna, e os despediu.'),
('acf','1cr',19,5,'E foram-se, e avisaram a Davi acerca daqueles homens; e enviou ele mensageiros a encontrá-los; porque aqueles homens estavam sobremaneira envergonhados. Disse, pois, o rei: Deixai-vos ficar em Jericó, até que vos torne a crescer a barba, e então voltai.'),
('acf','1cr',19,6,'Vendo, pois, os filhos de Amom que se tinham feito odiosos para com Davi, enviou Hanum, e os filhos de Amom, mil talentos de prata para alugarem para si carros e cavaleiros da Mesopotâmia, e da Síria de Maaca, e de Zobá.'),
('acf','1cr',19,7,'E alugaram para si trinta e dois mil carros, e o rei de Maaca e o seu povo, e eles vieram, e se acamparam diante de Medeba; também os filhos de Amom se ajuntaram das suas cidades, e vieram para a guerra.'),
('acf','1cr',19,8,'O que ouvindo Davi, enviou Joabe e todo o exército dos homens valentes.'),
('acf','1cr',19,9,'E, saindo os filhos de Amom, ordenaram a batalha à porta da cidade; porém os reis que vieram se puseram à parte no campo.'),
('acf','1cr',19,10,'E, vendo Joabe que a batalha estava preparada contra ele, pela frente e pela retaguarda, separou dentre os mais escolhidos de Israel, e os ordenou contra os sírios.'),
('acf','1cr',19,11,'E o resto do povo entregou na mão de Abisai, seu irmão; e puseram-se em ordem de batalha contra os filhos de Amom.'),
('acf','1cr',19,12,'E disse: Se os sírios forem mais fortes do que eu, tu virás socorrer-me; e, se os filhos de Amom forem mais fortes do que tu, então eu te socorrerei.'),
('acf','1cr',19,13,'Esforça-te, e esforcemo-nos pelo nosso povo, e pelas cidades do nosso Deus, e faça o Senhor o que parecer bem aos seus olhos.'),
('acf','1cr',19,14,'Então se chegou Joabe, e o povo que tinha consigo, diante dos sírios, para a batalha; e fugiram de diante dele.'),
('acf','1cr',19,15,'Vendo, pois, os filhos de Amom que os sírios fugiram, também eles fugiram de diante de Abisai, seu irmão, e entraram na cidade; e veio Joabe para Jerusalém.'),
('acf','1cr',19,16,'E, vendo os sírios que foram derrotados diante de Israel, enviaram mensageiros, e fizeram sair os sírios que habitavam do outro lado do rio; e Sofaque, capitão do exército de Hadar-Ezer, marchava diante deles.'),
('acf','1cr',19,17,'Do que avisado Davi, ajuntou a todo o Israel, e passou o Jordão, e foi ter com eles, e ordenou contra eles a batalha; e, tendo Davi ordenado a batalha contra os sírios, pelejaram contra ele.'),
('acf','1cr',19,18,'Porém os sírios fugiram de diante de Israel, e feriu Davi, dos sírios, os homens de sete mil carros, e quarenta mil homens de pé; e a Sofaque, capitão do exército, matou.'),
('acf','1cr',19,19,'Vendo, pois, os servos de Hadar-Ezer que tinham sido feridos diante de Israel, fizeram paz com Davi, e o serviram; e os sírios nunca mais quiseram socorrer os filhos de Amom.'),
('acf','1cr',20,1,'Aconteceu que, no decurso de um ano, no tempo em que os reis costumam sair para a guerra, Joabe levou o exército, e destruiu a terra dos filhos de Amom, e veio, e cercou a Rabá; porém Davi ficou em Jerusalém; e Joabe feriu a Rabá, e a destruiu.'),
('acf','1cr',20,2,'E Davi tirou a coroa da cabeça do rei deles, e achou nela o peso de um talento de ouro, e havia nela pedras preciosas; e foi posta sobre a cabeça de Davi; e levou da cidade mui grande despojo.'),
('acf','1cr',20,3,'Também levou o povo que estava nela, e os fez trabalhar com a serra, e com talhadeiras de ferro e com machados; e assim fez Davi com todas as cidades dos filhos de Amom; então voltou Davi, com todo o povo, para Jerusalém.'),
('acf','1cr',20,4,'E, depois disto, aconteceu que, levantando-se guerra em Gezer, com os filisteus, então Sibecai, o husatita, feriu a Sipai, dos filhos do gigante; e ficaram subjugados.'),
('acf','1cr',20,5,'E tornou a haver guerra com os filisteus; e El-Hanã, filho de Jair, feriu a Lami, irmão de Golias, o giteu, cuja haste da lança era como órgão de tecelão.'),
('acf','1cr',20,6,'E houve ainda outra guerra em Gate; onde havia um homem de grande estatura, e tinha vinte e quatro dedos, seis em cada mão, e seis em cada pé, e que também era filho do gigante.'),
('acf','1cr',20,7,'E injuriou a Israel; porém Jônatas, filho de Simei, irmão de Davi, o feriu;'),
('acf','1cr',20,8,'Estes nasceram ao gigante em Gate; e caíram pela mão de Davi e pela mão dos seus servos.'),
('acf','1cr',21,1,'Então Satanás se levantou contra Israel, e incitou Davi a numerar a Israel.'),
('acf','1cr',21,2,'E disse Davi a Joabe e aos maiorais do povo: Ide, numerai a Israel, desde Berseba até Dã; e trazei-me a conta para que saiba o número deles.'),
('acf','1cr',21,3,'Então disse Joabe: O SENHOR acrescente ao seu povo cem vezes tanto como é; porventura, ó rei meu senhor, não são todos servos de meu senhor? Por que procura isto o meu senhor? Porque seria isto causa de delito para com Israel.'),
('acf','1cr',21,4,'Porém a palavra do rei prevaleceu contra Joabe; por isso saiu Joabe, e passou por todo o Israel; então voltou para Jerusalém.'),
('acf','1cr',21,5,'E Joabe deu a Davi a soma do número do povo; e era todo o Israel um milhão e cem mil homens, dos que arrancavam da espada; e de Judá quatrocentos e setenta mil homens, dos que arrancavam da espada.'),
('acf','1cr',21,6,'Porém os de Levi e Benjamim não contou entre eles, porque a palavra do rei foi abominável a Joabe.'),
('acf','1cr',21,7,'E este negócio também pareceu mau aos olhos de Deus; por isso feriu a Israel.'),
('acf','1cr',21,8,'Então disse Davi a Deus: Gravemente pequei em fazer este negócio; porém agora sê servido tirar a iniqüidade de teu servo, porque procedi mui loucamente.'),
('acf','1cr',21,9,'Falou, pois, o Senhor a Gade, o vidente de Davi, dizendo:'),
('acf','1cr',21,10,'Vai, e fala a Davi, dizendo: Assim diz o Senhor: Três coisas te proponho; escolhe uma delas, para que eu ta faça.'),
('acf','1cr',21,11,'E Gade veio a Davi, e lhe disse: Assim diz o Senhor: Escolhe para ti,'),
('acf','1cr',21,12,'Ou três anos de fome, ou que três meses sejas consumido diante dos teus adversários, e a espada de teus inimigos te alcance, ou que três dias a espada do Senhor, isto é, a peste na terra, e o anjo do Senhor destrua todos os termos de Israel; vê, pois, agora, que resposta hei de levar a quem me enviou.'),
('acf','1cr',21,13,'Então disse Davi a Gade: Estou em grande angústia; caia eu, pois, nas mãos do Senhor, porque são muitíssimas as suas misericórdias; mas que eu não caia nas mãos dos homens.'),
('acf','1cr',21,14,'Mandou, pois, o Senhor a peste a Israel; e caíram de Israel setenta mil homens.'),
('acf','1cr',21,15,'E Deus mandou um anjo a Jerusalém para a destruir; e, destruindo-a ele, o Senhor olhou, e se arrependeu daquele mal, e disse ao anjo destruidor: Basta, agora retira a tua mão. E o anjo do Senhor estava junto à eira de Ornã, o jebuseu.'),
('acf','1cr',21,16,'E, levantando Davi os seus olhos, viu o anjo do Senhor, que estava entre a terra e o céu, com a sua espada desembainhada na sua mão estendida contra Jerusalém; então Davi e os anciãos, cobertos de sacos, se prostraram sobre os seus rostos.'),
('acf','1cr',21,17,'E disse Davi a Deus: Não sou eu o que disse que se contasse o povo? E eu mesmo sou o que pequei, e fiz muito mal; mas estas ovelhas que fizeram? Ah! Senhor, meu Deus, seja a tua mão contra mim, e contra a casa de meu pai, e não para castigo de teu povo.'),
('acf','1cr',21,18,'Então o anjo do Senhor ordenou a Gade que dissesse a Davi para subir e levantar um altar ao Senhor na eira de Ornã, o jebuseu.'),
('acf','1cr',21,19,'Subiu, pois, Davi, conforme a palavra de Gade, que falara em nome do Senhor.'),
('acf','1cr',21,20,'E, virando-se Ornã, viu o anjo, e esconderam-se seus quatro filhos que estavam com ele; e Ornã estava trilhando o trigo.'),
('acf','1cr',21,21,'E Davi veio a Ornã; e olhou Ornã, e viu a Davi, e saiu da eira, e se prostrou perante Davi com o rosto em terra.'),
('acf','1cr',21,22,'E disse Davi a Ornã: Dá-me este lugar da eira, para edificar nele um altar ao Senhor; dá-mo pelo seu valor, para que cesse este castigo sobre o povo.'),
('acf','1cr',21,23,'Então disse Ornã a Davi: Toma-o para ti, e faça o rei meu senhor dele o que parecer bem aos seus olhos; eis que dou os bois para holocaustos, e os trilhos para lenha, e o trigo para oferta de alimentos; tudo dou.'),
('acf','1cr',21,24,'E disse o rei Davi a Ornã: Não, antes, pelo seu valor, a quero comprar; porque não tomarei o que é teu, para o Senhor, para que não ofereça holocausto sem custo.'),
('acf','1cr',21,25,'E Davi deu a Ornã, por aquele lugar, o peso de seiscentos siclos de ouro.'),
('acf','1cr',21,26,'Então Davi edificou ali um altar ao Senhor, e ofereceu nele holocaustos e sacrifícios pacíficos; e invocou o Senhor, o qual lhe respondeu com fogo do céu sobre o altar do holocausto.'),
('acf','1cr',21,27,'E o Senhor deu ordem ao anjo, e ele tornou a sua espada à bainha.'),
('acf','1cr',21,28,'Vendo Davi, no mesmo tempo, que o Senhor lhe respondera na eira de Ornã, o jebuseu, sacrificou ali.'),
('acf','1cr',21,29,'Porque o tabernáculo do Senhor, que Moisés fizera no deserto, e o altar do holocausto, estavam naquele tempo no alto de Gibeom.'),
('acf','1cr',21,30,'E não podia Davi ir perante ele consultar a Deus; porque estava aterrorizado por causa da espada do anjo do Senhor.'),
('acf','1cr',22,1,'E disse Davi: Esta será a casa do SENHOR Deus, e este será o altar do holocausto para Israel.'),
('acf','1cr',22,2,'E deu ordem Davi que se ajuntassem os estrangeiros que estavam na terra de Israel; e ordenou cortadores de pedras, para que lavrassem pedras de cantaria, para edificar a casa de Deus.'),
('acf','1cr',22,3,'E aparelhou Davi ferro em abundância, para os pregos das portas das entradas, e para as junturas; como também cobre em abundância, que não foi pesado;'),
('acf','1cr',22,4,'E madeira de cedro sem conta; porque os sidônios e tírios traziam a Davi madeira de cedro em abundância.'),
('acf','1cr',22,5,'Porque dizia Davi: Salomão, meu filho, ainda é moço e tenro, e a casa que se há de edificar para o Senhor deve ser magnífica em excelência, para nome e glória em todas as terras; eu, pois, agora lhe prepararei materiais. Assim preparou Davi materiais em abundância, antes da sua morte.'),
('acf','1cr',22,6,'Então chamou a Salomão seu filho, e lhe ordenou que edificasse uma casa ao Senhor Deus de Israel.'),
('acf','1cr',22,7,'E disse Davi a Salomão: Filho meu, quanto a mim, tive em meu coração o propósito de edificar uma casa ao nome do Senhor meu Deus.'),
('acf','1cr',22,8,'Porém, veio a mim a palavra do Senhor, dizendo: Tu derramaste sangue em abundância, e fizeste grandes guerras; não edificarás casa ao meu nome; porquanto muito sangue tens derramado na terra, perante mim.'),
('acf','1cr',22,9,'Eis que o filho que te nascer será homem de repouso; porque repouso lhe hei de dar de todos os seus inimigos ao redor; portanto, Salomão será o seu nome, e paz e descanso darei a Israel nos seus dias.'),
('acf','1cr',22,10,'Ele edificará uma casa ao meu nome, e me será por filho, e eu lhe serei por pai, e confirmarei o trono de seu reino sobre Israel, para sempre.'),
('acf','1cr',22,11,'Agora, pois, meu filho, o Senhor seja contigo; e prospera, e edifica a casa do Senhor teu Deus, como ele disse de ti.'),
('acf','1cr',22,12,'O Senhor te dê tão-somente prudência e entendimento, e te instrua acerca de Israel; e isso para guardar a lei do Senhor teu Deus.'),
('acf','1cr',22,13,'Então prosperarás, se tiveres cuidado de cumprir os estatutos e os juízos, que o Senhor mandou a Moisés acerca de Israel; esforça-te, e tem bom ânimo; não temas, nem tenhas pavor.'),
('acf','1cr',22,14,'Eis que na minha aflição preparei para a casa do Senhor cem mil talentos de ouro, e um milhão de talentos de prata, e de cobre e de ferro que não se pesou, porque era em abundância; também madeira e pedras preparei, e tu suprirás o que faltar.'),
('acf','1cr',22,15,'Também tens contigo obreiros em grande número, cortadores e artífices em obra de pedra e madeira; e toda a sorte de peritos em toda a espécie de obra.'),
('acf','1cr',22,16,'Do ouro, da prata, e do cobre, e do ferro não há conta. Levanta-te, pois, e faze a obra, e o Senhor seja contigo.'),
('acf','1cr',22,17,'E Davi deu ordem a todos os príncipes de Israel que ajudassem a Salomão, seu filho, dizendo:'),
('acf','1cr',22,18,'Porventura não está convosco o Senhor vosso Deus, e não vos deu repouso ao redor? Porque entregou na minha mão os moradores da terra; e a terra foi sujeita perante o Senhor e perante o seu povo.'),
('acf','1cr',22,19,'Disponde, pois, agora o vosso coração e a vossa alma para buscardes ao Senhor vosso Deus; e levantai-vos, e edificai o santuário do Senhor Deus, para que a arca da aliança do Senhor, e os vasos sagrados de Deus se tragam a esta casa, que se há de edificar ao nome do Senhor.'),
('acf','1cr',23,1,'Sendo, pois, Davi já velho, e cheio de dias, fez a Salomão, seu filho, rei sobre Israel.'),
('acf','1cr',23,2,'E reuniu a todos os príncipes de Israel, como também aos sacerdotes e levitas.'),
('acf','1cr',23,3,'E foram contados os levitas de trinta anos para cima; e foi o número deles, segundo as suas cabeças, trinta e oito mil homens.'),
('acf','1cr',23,4,'Destes havia vinte e quatro mil, para promoverem a obra da casa do Senhor, e seis mil oficiais e juízes,'),
('acf','1cr',23,5,'E quatro mil porteiros, e quatro mil para louvarem ao Senhor com os instrumentos, que eu fiz para o louvar, disse Davi.'),
('acf','1cr',23,6,'E Davi os repartiu por turnos, segundo os filhos de Levi, Gérson, Coate e Merari.'),
('acf','1cr',23,7,'Dos gersonitas: Ladã e Simei.'),
('acf','1cr',23,8,'Os filhos de Ladã: Jeiel, o chefe, e Zetã, e Joel, três.'),
('acf','1cr',23,9,'Os filhos de Simei: Selomite, Haziel, e Harã, três; estes foram os chefes dos pais de Ladã.'),
('acf','1cr',23,10,'E os filhos de Simei: Jaate, Ziza, Jeús, e Berias; estes foram os filhos de Simei, quatro.'),
('acf','1cr',23,11,'E Jaate era o chefe, e Ziza o segundo, mas Jeús e Berias não tiveram muitos filhos; por isso estes, sendo contados juntos se tornaram uma só família.'),
('acf','1cr',23,12,'Os filhos de Coate: Anrão, Izar, Hebrom, e Uziel, quatro.'),
('acf','1cr',23,13,'Os filhos de Anrão: Arão e Moisés; e Arão foi separado para santificar o santo dos santos, ele e seus filhos, eternamente; para incensar diante do Senhor, para o servirem, e para darem a bênção em seu nome eternamente.'),
('acf','1cr',23,14,'E, quanto a Moisés, homem de Deus, seus filhos foram contados entre os da tribo de Levi.'),
('acf','1cr',23,15,'Foram, pois, os filhos de Moisés, Gérson e Eliézer.'),
('acf','1cr',23,16,'Dos filhos de Gérson foi Sebuel o chefe.'),
('acf','1cr',23,17,'E, quanto aos filhos de Eliézer, foi Reabias o chefe; e Eliézer não teve outros filhos; porém os filhos de Reabias foram muitos.'),
('acf','1cr',23,18,'Dos filhos de Izar foi Selomite o chefe.'),
('acf','1cr',23,19,'Quanto aos filhos de Hebrom, foram Jerias o primeiro, Amarias o segundo, Jaaziel o terceiro, e Jecameão o quarto.'),
('acf','1cr',23,20,'Quanto aos filhos de Uziel, Mica o chefe, e Issias o segundo.'),
('acf','1cr',23,21,'Os filhos de Merari: Mali, e Musi; os filhos de Mali: Eleazar e Quis.'),
('acf','1cr',23,22,'E morreu Eleazar, e não teve filhos, porém filhas; e os filhos de Quis, seus parentes, as tomaram por mulheres.'),
('acf','1cr',23,23,'Os filhos de Musi: Mali, e Eder, e Jeremote, três.'),
('acf','1cr',23,24,'Estes são os filhos de Levi, segundo a casa de seus pais, chefes dos pais, conforme foram contados pelos seus nomes, segundo as suas cabeças, que faziam a obra do ministério da casa do Senhor, desde a idade de vinte anos para cima.'),
('acf','1cr',23,25,'Porque disse Davi: O Senhor Deus de Israel deu repouso ao seu povo, e habitará em Jerusalém para sempre.'),
('acf','1cr',23,26,'E também, quanto aos levitas, que nunca mais levassem o tabernáculo, nem algum de seus aparelhos pertencentes ao seu ministério.'),
('acf','1cr',23,27,'Porque, segundo as últimas palavras de Davi, foram contados os filhos de Levi da idade de vinte anos para cima:'),
('acf','1cr',23,28,'Porque o seu cargo era assistir aos filhos de Arão no ministério da casa do Senhor, nos átrios, e nas câmaras, e na purificação de todas as coisas sagradas, e na obra do ministério da casa de Deus.'),
('acf','1cr',23,29,'A saber: para os pães da proposição, e para a flor de farinha, para a oferta de alimentos, e para os coscorões ázimos, e para as sertãs, e para o tostado, e para todo o peso e medida;'),
('acf','1cr',23,30,'E para estarem cada manhã em pé para louvarem e celebrarem ao Senhor; e semelhantemente à tarde;'),
('acf','1cr',23,31,'E para oferecerem os holocaustos do Senhor, aos sábados, nas luas novas, e nas solenidades, segundo o seu número e costume, continuamente perante o Senhor;'),
('acf','1cr',23,32,'E para que tivessem cuidado da guarda da tenda da congregação, e da guarda do santuário, e da guarda dos filhos de Arão, seus irmãos, no ministério da casa do Senhor.'),
('acf','1cr',24,1,'E quanto aos filhos de Arão, estas foram as suas divisões: os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar.'),
('acf','1cr',24,2,'E morreram Nadabe e Abiú antes de seu pai, e não tiveram filhos; e Eleazar e Itamar administravam o sacerdócio.'),
('acf','1cr',24,3,'E Davi, com Zadoque, dos filhos de Eleazar, e Aimeleque, dos filhos de Itamar, dividiu-os segundo o seu ofício no seu ministério.'),
('acf','1cr',24,4,'E acharam-se muito mais chefes dos pais entre os filhos de Eleazar do que entre os filhos de Itamar, quando os repartiram; dos filhos de Eleazar dezesseis chefes das casas paternas, mas dos filhos de Itamar, segundo as casas paternas, oito.'),
('acf','1cr',24,5,'E os repartiram por sortes, uns com os outros; porque houve governadores do santuário e governadores da casa de Deus, assim dentre os filhos de Eleazar, como dentre os filhos de Itamar.'),
('acf','1cr',24,6,'E Semaías, filho de Natanael, o escrivão dentre os levitas, os registrou perante o rei, e os príncipes, e Zadoque, o sacerdote, e Aimeleque, filho de Abiatar, e os chefes dos pais entre os sacerdotes, e entre os levitas; dentre as casas dos pais tomou-se uma para Eleazar, e outra para Itamar.'),
('acf','1cr',24,7,'E saiu a primeira sorte a Jeoiaribe, a segunda a Jedaías,'),
('acf','1cr',24,8,'A terceira a Harim, a quarta a Seorim,'),
('acf','1cr',24,9,'A quinta a Malquias, a sexta a Miamim,'),
('acf','1cr',24,10,'A sétima a Hacoz, a oitava a Abias,'),
('acf','1cr',24,11,'A nona a Jesua, a décima a Secanias,'),
('acf','1cr',24,12,'A undécima a Eliasibe, a duodécima a Jaquim,'),
('acf','1cr',24,13,'A décima terceira a Hupa, a décima quarta a Jesebeabe,'),
('acf','1cr',24,14,'A décima quinta a Bilga, a décima sexta a Imer,'),
('acf','1cr',24,15,'A décima sétima a Hezir, a décima oitava a Hapizes,'),
('acf','1cr',24,16,'A décima nona a Petaías, a vigésima a Jeezquel,'),
('acf','1cr',24,17,'A vigésima primeira a Jaquim, a vigésima segunda a Gamul,'),
('acf','1cr',24,18,'A vigésima terceira a Delaías, a vigésima quarta a Maazias.'),
('acf','1cr',24,19,'O ofício destes no seu ministério era entrar na casa do Senhor, segundo lhes fora ordenado por Arão seu pai, como o Senhor Deus de Israel lhe tinha mandado.'),
('acf','1cr',24,20,'E do restante dos filhos de Levi: dos filhos de Anrão, Subael; dos filhos de Subael, Jedias.'),
('acf','1cr',24,21,'Quanto a Reabias: dos filhos de Reabias, Issias era o primeiro;'),
('acf','1cr',24,22,'Dos izaritas, Selomote; dos filhos de Selomote, Jaate;'),
('acf','1cr',24,23,'E dos filhos de Hebrom, Jerias o primeiro, Amarias o segundo, Jaaziel o terceiro, Jecameão o quarto;'),
('acf','1cr',24,24,'Dos filhos de Uziel, Mica; dos filhos de Mica, Samir;'),
('acf','1cr',24,25,'O irmão de Mica, Issias; dos filhos de Issias, Zacarias;'),
('acf','1cr',24,26,'Os filhos de Merari, Mali e Musi; dos filhos de Jaazias, Beno;'),
('acf','1cr',24,27,'Os filhos de Merari: de Jaazias, Beno, e Soão, e Zacur, e Ibri;'),
('acf','1cr',24,28,'De Mali, Eleazar; e este não teve filhos.'),
('acf','1cr',24,29,'Quanto a Quis: dos filhos de Quis, Jerameel;'),
('acf','1cr',24,30,'E os filhos de Musi: Mali, e Eder, e Jerimote; estes foram os filhos dos levitas, segundo as suas casas paternas.'),
('acf','1cr',24,31,'Estes também lançaram sortes como seus irmãos, os filhos de Arão, perante o rei Davi, e Zadoque, e Aimeleque, e os chefes das famílias entre os sacerdotes e entre os levitas; assim fizeram, tanto os pais principais como os irmãos menores.'),
('acf','1cr',25,1,'E Davi, juntamente com os capitães do exército, separou para o ministério os filhos de Asafe, e de Hemã, e de Jedutum, para profetizarem com harpas, com címbalos, e com saltérios; e este foi o número dos homens aptos para a obra do seu ministério:'),
('acf','1cr',25,2,'Dos filhos de Asafe: Zacur, José, Netanias, e Asarela, filhos de Asafe; a cargo de Asafe, que profetizava debaixo das ordens do rei Davi.'),
('acf','1cr',25,3,'Quanto a Jedutum, os filhos: Gedalias, Zeri, Jesaías, Hasabias, e Matitias, seis, a cargo de seu pai, Jedutum, o qual profetizava com a harpa, louvando e dando graças ao Senhor.'),
('acf','1cr',25,4,'Quanto a Hemã, os filhos: Buquias, Matanias, Uziel, Sebuel, Jerimote, Hananias, Hanani, Eliata, Gidalti, Romanti-Ezer, Josbecasa, Maloti, Hotir, e Maaziote.'),
('acf','1cr',25,5,'Todos estes foram filhos de Hemã, o vidente do rei nas palavras de Deus, para exaltar o seu poder; porque Deus dera a Hemã catorze filhos e três filhas.'),
('acf','1cr',25,6,'Todos estes estavam sob a direção de seu pai, para a música da casa do Senhor, com saltérios, címbalos e harpas, para o ministério da casa de Deus; e Asafe, Jedutum, e Hemã, estavam sob as ordens do rei.'),
('acf','1cr',25,7,'E era o número deles, juntamente com seus irmãos instruídos no canto ao Senhor, todos eles mestres, duzentos e oitenta e oito.'),
('acf','1cr',25,8,'E deitaram sortes acerca da guarda igualmente, assim o pequeno como o grande, o mestre juntamente com o discípulo.'),
('acf','1cr',25,9,'Saiu, pois, a primeira sorte a Asafe, a saber a José; a segunda a Gedalias; e ele, e seus irmãos, e seus filhos, ao todo eram doze.'),
('acf','1cr',25,10,'A terceira a Zacur, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,11,'A quarta a Izri, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,12,'A quinta a Netanias, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,13,'A sexta a Buquias, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,14,'A sétima a Jesarela, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,15,'A oitava a Jesaías, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,16,'A nona a Matanias, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,17,'A décima a Simei, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,18,'A undécima a Azareel, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,19,'A duodécima a Hasabias, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,20,'A décima terceira a Subael, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,21,'A décima quarta a Matitias, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,22,'A décima quinta a Jeremote, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,23,'A décima sexta a Hananias, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,24,'A décima sétima a Josbecasa, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,25,'A décima oitava a Hanani, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,26,'A décima nona a Maloti, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,27,'A vigésima a Eliata, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,28,'A vigésima primeira a Hotir, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,29,'A vigésima segunda a Gidalti, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,30,'A vigésima terceira a Maaziote, seus filhos, e seus irmãos, doze.'),
('acf','1cr',25,31,'A vigésima quarta a Romanti-Ezer, seus filhos, e seus irmãos, doze.'),
('acf','1cr',26,1,'Quanto às divisões dos porteiros: dos coraítas: Meselemias, filho de Coré, dos filhos de Asafe.'),
('acf','1cr',26,2,'E foram os filhos de Meselemias: Zacarias o primogênito, Jediael o segundo, Zebadias o terceiro, Jatniel o quarto,'),
('acf','1cr',26,3,'Elão o quinto, Joanã o sexto, Elioenai o sétimo.'),
('acf','1cr',26,4,'E os filhos de Obede-Edom foram: Semaías o primogênito, Jozabade o segundo, Joá o terceiro, e Sacar o quarto, e Natanael o quinto,'),
('acf','1cr',26,5,'Amiel o sexto, Issacar o sétimo, Peuletai o oitavo; porque Deus o tinha abençoado.'),
('acf','1cr',26,6,'Também a seu filho Semaías nasceram filhos, que dominaram sobre a casa de seu pai; porque foram homens valentes.'),
('acf','1cr',26,7,'Os filhos de Semaías: Otni, Rafael, Obede, e Elzabade, com seus irmãos, homens valentes, Eliú e Semaquias.'),
('acf','1cr',26,8,'Todos estes foram dos filhos de Obede-Edom; eles e seus filhos, e seus irmãos, homens valentes e de força para o ministério; ao todo sessenta e dois, de Obede-Edom.'),
('acf','1cr',26,9,'E os filhos e os irmãos de Meselemias, homens valentes, foram dezoito.'),
('acf','1cr',26,10,'E de Hosa, dentre os filhos de Merari, foram filhos: Sinri o chefe (ainda que não era o primogênito, contudo seu pai o constituiu chefe),'),
('acf','1cr',26,11,'Hilquias o segundo, Tebalias o terceiro, Zacarias o quarto; todos os filhos e irmãos de Hosa foram treze.'),
('acf','1cr',26,12,'Destes se fizeram as turmas dos porteiros, alternando os principais dos homens da guarda, juntamente com os seus irmãos, para ministrarem na casa do Senhor.'),
('acf','1cr',26,13,'E lançaram sortes, assim os pequenos como os grandes, segundo as casas de seus pais, para cada porta.'),
('acf','1cr',26,14,'E caiu a sorte do oriente a Selemias; e lançou-se a sorte por seu filho Zacarias, conselheiro entendido, e saiu-lhe a do norte.'),
('acf','1cr',26,15,'E para Obede-Edom a do sul; e para seus filhos a casa dos depósitos.'),
('acf','1cr',26,16,'Para Supim e Hosa a do ocidente, junto a porta Salequete, perto do caminho da subida; uma guarda defronte de outra guarda.'),
('acf','1cr',26,17,'Ao oriente seis levitas; ao norte quatro por dia, ao sul quatro por dia, porém para as casas dos depósitos de dois em dois.'),
('acf','1cr',26,18,'Em Parbar, ao ocidente, quatro junto ao caminho, e dois junto a Parbar.'),
('acf','1cr',26,19,'Estas são as turmas dos porteiros dentre os filhos dos coraítas, e dentre os filhos de Merari.'),
('acf','1cr',26,20,'E dos levitas: Aías tinha cargo dos tesouros da casa de Deus e dos tesouros das coisas sagradas.'),
('acf','1cr',26,21,'Quanto aos filhos de Ladã, os filhos dos gersonitas que pertencem a Ladã, chefes das casas paternas de Ladã: Jeieli.'),
('acf','1cr',26,22,'Os filhos de Jeieli: Zetã e Joel, seu irmão; estes tinham cargo dos tesouros da casa do Senhor,'),
('acf','1cr',26,23,'Dos anramitas, dos izaritas, dos hebronitas, dos uzielitas.'),
('acf','1cr',26,24,'E Sebuel, filho de Gérson, o filho de Moisés, era o chefe dos tesouros.'),
('acf','1cr',26,25,'E seus irmãos foram, do lado de Eliézer, Reabias seu filho, e Jesaías seu filho, e Jorão seu filho, e Zicri seu filho, e Selomite, seu filho.'),
('acf','1cr',26,26,'Este Selomite e seus irmãos tinham a seu cargo todos os tesouros das coisas dedicadas que o rei Davi e os chefes das casas paternas, capitães de milhares, e de centenas, e capitães do exército tinham consagrado.'),
('acf','1cr',26,27,'Dos despojos das guerras dedicaram ofertas para repararem a casa do Senhor.'),
('acf','1cr',26,28,'Como também tudo quanto tinha consagrado Samuel, o vidente, e Saul filho de Quis, e Abner filho de Ner, e Joabe filho de Zeruia; tudo que qualquer havia dedicado estava debaixo da mão de Selomite e seus irmãos.'),
('acf','1cr',26,29,'Dos izaritas, Quenanias e seus filhos foram postos sobre Israel como oficiais e como juízes, dos negócios externos.'),
('acf','1cr',26,30,'Dos hebronitas foram Hasabias e seus irmãos, homens valentes, mil e setecentos, que tinham a superintendência sobre Israel, além do Jordão para o ocidente, em toda a obra do Senhor, e para o serviço do rei.'),
('acf','1cr',26,31,'Dos hebronitas Jerias era o chefe, segundo as suas gerações conforme as suas famílias. No ano quarenta do reino de Davi se buscaram e acharam entre eles homens valentes em Jazer de Gileade.'),
('acf','1cr',26,32,'E seus irmãos, homens valentes, dois mil e setecentos, chefes dos pais; e o rei Davi os constituiu sobre os rubenitas e os gaditas, e a meia tribo dos manassitas, para todos os negócios de Deus, e para todos os negócios do rei.'),
('acf','1cr',27,1,'Estes são os filhos de Israel segundo o seu número, os chefes dos pais, e os capitães dos milhares e das centenas, com os seus oficiais, que serviam ao rei em todos os negócios das turmas que entravam e saíam de mês em mês, em todos os meses do ano; cada turma de vinte e quatro mil.'),
('acf','1cr',27,2,'Sobre a primeira turma do primeiro mês estava Jasobeão, filho de Zabdiel; e em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,3,'Era este dos filhos de Perez, chefe de todos os capitães dos exércitos, para o primeiro mês,'),
('acf','1cr',27,4,'E sobre a turma do segundo mês estava Dodai, o aoíta, com a sua turma, cujo líder era Miclote; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,5,'O terceiro capitão do exército, para o terceiro mês, era Benaia, filho de Joiada, chefe dos sacerdotes; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,6,'Era este Benaia valente entre os trinta, e sobre os trinta; e na sua turma estava Amizabade, seu filho.'),
('acf','1cr',27,7,'O quarto, do quarto mês, era Asael, irmão de Joabe, e depois dele Zebadias, seu filho; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,8,'O quinto, do quinto mês, Samute, o israíta; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,9,'O sexto, do sexto mês, Ira, filho de Iques, o tecoíta; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,10,'O sétimo, do sétimo mês, Helez, o pelonita, dos filhos de Efraim; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,11,'O oitavo, do oitavo mês, Sibecai, o husatita, dos zeraítas; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,12,'O nono, do nono mês, Abiezer, o anatotita, dos benjamitas; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,13,'O décimo, do décimo mês, Maarai, o netofatita, dos zeraítas; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,14,'O undécimo, do undécimo mês, Benaia, o piratonita, dos filhos de Efraim; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,15,'O duodécimo, do duodécimo mês, Heldai, o netofatita, de Otniel; também em sua turma havia vinte e quatro mil.'),
('acf','1cr',27,16,'Sobre as tribos de Israel estavam: sobre os rubenitas era líder Eliezer, filho de Zicri; sobre os simeonitas, Sefatias, filho de Maaca.'),
('acf','1cr',27,17,'Sobre os levitas, Hasabias, filho de Quemuel; sobre os aronitas, Zadoque;'),
('acf','1cr',27,18,'Sobre Judá, Eliú, dos irmãos de Davi; sobre Issacar, Onri, filho de Micael;'),
('acf','1cr',27,19,'Sobre Zebulom, Ismaías, filho de Obadias; sobre Naftali, Jerimote, filho de Azriel;'),
('acf','1cr',27,20,'Sobre os filhos de Efraim, Oséias, filho de Azazias; sobre a meia tribo de Manassés, Joel, filho de Pedaías;'),
('acf','1cr',27,21,'Sobre a outra meia tribo de Manassés em Gileade, Ido, filho de Zacarias; sobre Benjamim, Jaasiel, filho de Abner;'),
('acf','1cr',27,22,'Sobre Dã, Azarel, filho de Jeroão. Estes eram os príncipes das tribos de Israel.'),
('acf','1cr',27,23,'Não tomou, porém, Davi o número dos de vinte anos para baixo, porquanto o Senhor tinha falado que havia de multiplicar a Israel como as estrelas do céu.'),
('acf','1cr',27,24,'Joabe, filho de Zeruia, tinha começado a numerá-los, porém não acabou; porquanto viera por isso grande ira sobre Israel; assim o número não se pôs no registro das crônicas do rei Davi.'),
('acf','1cr',27,25,'E sobre os tesouros do rei estava Azmavete, filho de Adiel; e sobre os tesouros dos campos, das cidades, e das aldeias, e das torres, Jônatas, filho de Uzias.'),
('acf','1cr',27,26,'E sobre os que faziam a obra do campo, na lavoura da terra, Ezri, filho de Quelube.'),
('acf','1cr',27,27,'E sobre as vinhas, Simei, o ramatita; porém sobre o que das vides entrava nas adegas do vinho, Zabdi, o sifmita.'),
('acf','1cr',27,28,'E sobre os olivais e sicômoros que havia nas campinas, Baal-Hanã, o gederita; porém Joás sobre os armazéns do azeite.'),
('acf','1cr',27,29,'E sobre os gados que pastavam em Sarom, Sitrai, o saronita; porém, sobre os gados dos vales, Safate, filho de Adlai.'),
('acf','1cr',27,30,'E sobre os camelos, Obil, o ismaelita; e sobre as jumentas, Jedias, o meronotita.'),
('acf','1cr',27,31,'E sobre o gado miúdo, Jaziz, o hagrita; todos esses eram administradores da fazenda que tinha o rei Davi.'),
('acf','1cr',27,32,'E Jônatas, tio de Davi, era do conselho, homem entendido, e também escriba; e Jeiel, filho de Hacmoni, estava com os filhos do rei.'),
('acf','1cr',27,33,'E Aitofel era do conselho do rei; e Husai, o arquita, amigo do rei.'),
('acf','1cr',27,34,'E depois de Aitofel, Joiada, filho de Benaia, e Abiatar; porém Joabe era o general do exército do rei.'),
('acf','1cr',28,1,'Então Davi reuniu em Jerusalém todos os príncipes de Israel, os príncipes das tribos, e os capitães das turmas, que serviam o rei, e os capitães dos milhares, e os capitães das centenas, e os administradores de toda a fazenda e possessão do rei, e de seus filhos, como também os oficiais, os poderosos, e todo o homem valente.'),
('acf','1cr',28,2,'E pôs-se o rei Davi em pé, e disse: Ouvi-me, irmãos meus, e povo meu; em meu coração propus eu edificar uma casa de repouso para a arca da aliança do Senhor e para o estrado dos pés do nosso Deus, e eu tinha feito o preparo para a edificar.'),
('acf','1cr',28,3,'Porém Deus me disse: Não edificarás casa ao meu nome, porque és homem de guerra, e derramaste muito sangue.'),
('acf','1cr',28,4,'E o Senhor Deus de Israel escolheu-me de toda a casa de meu pai, para que eternamente fosse rei sobre Israel; porque a Judá escolheu por soberano, e a casa de meu pai na casa de Judá; e entre os filhos de meu pai se agradou de mim para me fazer reinar sobre todo o Israel.'),
('acf','1cr',28,5,'E, de todos os meus filhos (porque muitos filhos me deu o Senhor), escolheu ele o meu filho Salomão para se assentar no trono do reino do Senhor sobre Israel.'),
('acf','1cr',28,6,'E me disse: Teu filho Salomão, ele edificará a minha casa e os meus átrios; porque o escolhi para filho, e eu lhe serei por pai.'),
('acf','1cr',28,7,'E estabelecerei o seu reino para sempre, se perseverar em cumprir os meus mandamentos e os meus juízos, como até ao dia de hoje.'),
('acf','1cr',28,8,'Agora, pois, perante os olhos de todo o Israel, a congregação do Senhor, e perante os ouvidos de nosso Deus, guardai e buscai todos os mandamentos do Senhor vosso Deus, para que possuais esta boa terra, e a façais herdar a vossos filhos depois de vós, para sempre.'),
('acf','1cr',28,9,'E tu, meu filho Salomão, conhece o Deus de teu pai, e serve-o com um coração perfeito e com uma alma voluntária; porque esquadrinha o Senhor todos os corações, e entende todas as imaginações dos pensamentos; se o buscares, será achado de ti; porém, se o deixares, rejeitar-te-á para sempre.'),
('acf','1cr',28,10,'Olha, pois, agora, porque o Senhor te escolheu para edificares uma casa para o santuário; esforça-te, e faze a obra.'),
('acf','1cr',28,11,'E deu Davi a Salomão, seu filho, a planta do alpendre com as suas casas, e as suas tesourarias, e os seus cenáculos, e as suas recâmaras interiores, como também da casa do propiciatório.'),
('acf','1cr',28,12,'E também a planta de tudo quanto tinha em mente, a saber: dos átrios da casa do Senhor, e de todas as câmaras ao redor, para os tesouros da casa de Deus, e para os tesouros das coisas sagradas;'),
('acf','1cr',28,13,'E para as turmas dos sacerdotes, e para os levitas, e para toda a obra do ministério da casa do Senhor, e para todos os utensílios do ministério da casa do Senhor.'),
('acf','1cr',28,14,'E deu ouro, segundo o peso do ouro, para todos os utensílios de cada ministério; também a prata, por peso, para todos os utensílios de prata, para todos os utensílios de cada ministério.'),
('acf','1cr',28,15,'E o peso para os castiçais de ouro, e suas candeias de ouro segundo o peso de cada castiçal e as suas candeias; também para os castiçais de prata, segundo o peso do castiçal e as suas candeias, segundo o uso de cada castiçal.'),
('acf','1cr',28,16,'Também deu o ouro por peso para as mesas da proposição, para cada mesa; como também a prata para as mesas de prata.'),
('acf','1cr',28,17,'E ouro puro para os garfos, e para as bacias, e para os jarros, e para as taças de ouro, para cada taça seu peso; como também para as taças de prata, para cada taça seu peso.'),
('acf','1cr',28,18,'E para o altar do incenso, ouro purificado, por seu peso; como também o ouro para o modelo do carro, a saber, dos querubins, que haviam de estender as asas, e cobrir a arca da aliança do Senhor.'),
('acf','1cr',28,19,'Tudo isto, disse Davi, fez-me entender o Senhor, por escrito da sua mão, a saber, todas as obras desta planta.'),
('acf','1cr',28,20,'E disse Davi a Salomão seu filho: Esforça-te e tem bom ânimo, e faze a obra; não temas, nem te apavores; porque o Senhor Deus, meu Deus, há de ser contigo; não te deixará, nem te desamparará, até que acabes toda a obra do serviço da casa do Senhor.'),
('acf','1cr',28,21,'E eis que aí tens as turmas dos sacerdotes e dos levitas para todo o ministério da casa de Deus; estão também contigo, para toda a obra, voluntários com sabedoria de toda a espécie para todo o ministério; como também todos os príncipes, e todo o povo, para todos os teus mandados.'),
('acf','1cr',29,1,'Disse mais o rei Davi a toda a congregação: Salomão, meu filho, a quem só Deus escolheu, é ainda moço e tenro, e esta obra é grande; porque não é o palácio para homem, mas para o SENHOR Deus.'),
('acf','1cr',29,2,'Eu, pois, com todas as minhas forças já tenho preparado para a casa de meu Deus ouro para as obras de ouro, e prata para as de prata, e cobre para as de cobre, ferro para as de ferro e madeira para as de madeira, pedras de ônix, e as de engaste, e pedras ornamentais, e pedras de diversas cores, e toda a sorte de pedras preciosas, e pedras de mármore em abundância.'),
('acf','1cr',29,3,'E ainda, porque tenho afeto à casa de meu Deus, o ouro e prata particular que tenho eu dou para a casa do meu Deus, afora tudo quanto tenho preparado para a casa do santuário:'),
('acf','1cr',29,4,'Três mil talentos de ouro de Ofir; e sete mil talentos de prata purificada, para cobrir as paredes das casas.'),
('acf','1cr',29,5,'Ouro para os objetos de ouro, e prata para os de prata; e para toda a obra de mão dos artífices. Quem, pois, está disposto a encher a sua mão, para oferecer hoje voluntariamente ao Senhor?'),
('acf','1cr',29,6,'Então os chefes dos pais, e os príncipes das tribos de Israel, e os capitães de mil e de cem, até os chefes da obra do rei, voluntariamente contribuíram.'),
('acf','1cr',29,7,'E deram para o serviço da casa de Deus cinco mil talentos de ouro, e dez mil dracmas, e dez mil talentos de prata, e dezoito mil talentos de cobre, e cem mil talentos de ferro.'),
('acf','1cr',29,8,'E os que possuíam pedras preciosas, deram-nas para o tesouro da casa do Senhor, a cargo de Jeiel o gersonita.'),
('acf','1cr',29,9,'E o povo se alegrou porque contribuíram voluntariamente; porque, com coração perfeito, voluntariamente deram ao Senhor; e também o rei Davi se alegrou com grande alegria.'),
('acf','1cr',29,10,'Por isso Davi louvou ao Senhor na presença de toda a congregação; e disse Davi: Bendito és tu, Senhor Deus de Israel, nosso pai, de eternidade em eternidade.'),
('acf','1cr',29,11,'Tua é, Senhor, a magnificência, e o poder, e a honra, e a vitória, e a majestade; porque teu é tudo quanto há nos céus e na terra; teu é, Senhor, o reino, e tu te exaltaste por cabeça sobre todos.'),
('acf','1cr',29,12,'E riquezas e glória vêm de diante de ti, e tu dominas sobre tudo, e na tua mão há força e poder; e na tua mão está o engrandecer e o dar força a tudo.'),
('acf','1cr',29,13,'Agora, pois, ó Deus nosso, graças te damos, e louvamos o nome da tua glória.'),
('acf','1cr',29,14,'Porque quem sou eu, e quem é o meu povo, para que pudéssemos oferecer voluntariamente coisas semelhantes? Porque tudo vem de ti, e do que é teu to damos.'),
('acf','1cr',29,15,'Porque somos estrangeiros diante de ti, e peregrinos como todos os nossos pais; como a sombra são os nossos dias sobre a terra, e sem ti não há esperança.'),
('acf','1cr',29,16,'Senhor, nosso Deus, toda esta abundância, que preparamos, para te edificar uma casa ao teu santo nome, vem da tua mão, e é toda tua.'),
('acf','1cr',29,17,'E bem sei eu, Deus meu, que tu provas os corações, e que da sinceridade te agradas; eu também na sinceridade de meu coração voluntariamente dei todas estas coisas; e agora vi com alegria que o teu povo, que se acha aqui, voluntariamente te deu.'),
('acf','1cr',29,18,'Senhor Deus de Abraão, Isaque, e Israel, nossos pais, conserva isto para sempre no intento dos pensamentos do coração de teu povo; e encaminha o seu coração para ti.'),
('acf','1cr',29,19,'E a Salomão, meu filho, dá um coração perfeito, para guardar os teus mandamentos, os teus testemunhos, e os teus estatutos; e para fazer tudo, e para edificar este palácio que tenho preparado.'),
('acf','1cr',29,20,'Então disse Davi a toda a congregação: Agora louvai ao Senhor vosso Deus. Então toda a congregação louvou ao Senhor Deus de seus pais, e inclinaram-se, e prostraram-se perante o Senhor, e o rei.'),
('acf','1cr',29,21,'E ao outro dia imolaram sacrifícios ao Senhor, e ofereceram holocaustos ao Senhor, mil bezerros, mil carneiros, mil cordeiros, com as suas libações; e sacrifícios em abundância por todo o Israel.'),
('acf','1cr',29,22,'E comeram e beberam naquele dia perante o Senhor, com grande gozo; e a segunda vez fizeram rei a Salomão filho de Davi, e o ungiram ao Senhor por líder, e a Zadoque por sacerdote.'),
('acf','1cr',29,23,'Assim Salomão se assentou no trono do Senhor, como rei, em lugar de Davi seu pai, e prosperou; e todo o Israel lhe obedecia.'),
('acf','1cr',29,24,'E todos os príncipes, e os grandes, e até todos os filhos do rei Davi, se submeteram ao rei Salomão.'),
('acf','1cr',29,25,'E o Senhor magnificou a Salomão grandissimamente, perante os olhos de todo o Israel; e deu-lhe majestade real, qual antes dele não teve nenhum rei em Israel.'),
('acf','1cr',29,26,'Assim Davi, filho de Jessé, reinou sobre todo o Israel.'),
('acf','1cr',29,27,'E foram os dias que reinou sobre Israel, quarenta anos; em Hebrom reinou sete anos, e em Jerusalém reinou trinta e três.'),
('acf','1cr',29,28,'E morreu numa boa velhice, cheio de dias, riquezas e glória; e Salomão, seu filho, reinou em seu lugar.'),
('acf','1cr',29,29,'Os atos, pois, do rei Davi, assim os primeiros como os últimos, eis que estão escritos nas crônicas de Samuel, o vidente, e nas crônicas do profeta Natã, e nas crônicas de Gade, o vidente,'),
('acf','1cr',29,30,'Juntamente com todo o seu reinado e o seu poder; e os tempos que passaram sobre ele, e sobre Israel, e sobre todos os reinos daquelas terras.')
